    private List<AppSemanticMigrationPlan> appSemanticMigrationPlans(List<RepositoryQueryPlan> repositoryQueryPlans,
                                                                     List<ObjectSnapshotPlan> objectSnapshotPlans,
                                                                     List<RemoteServiceAssignment> remoteAssignments,
                                                                     List<PhysicalRemotePlan> physicalRemotePlans,
                                                                     List<QuantumAccessPlan> quantumAccessPlans) {
        List<AppSemanticMigrationPlan> plans = new ArrayList<>();
        Map<String, PhysicalRemotePlan> physicalRemotePlansByService = physicalRemotePlans == null
                ? Map.of()
                : physicalRemotePlans.stream()
                .collect(Collectors.toMap(PhysicalRemotePlan::serviceName,
                        plan -> plan, (first, second) -> first, LinkedHashMap::new));
        for (AppDdlCatalog.Table table : appDdlCatalog.tables()) {
            if (!table.objectBackedPrimaryKeys().isEmpty()) {
                plans.add(new AppSemanticMigrationPlan("OBJECT_BACKED_PRIMARY_KEY", "APP_DDL_TABLE",
                        table.name(), table.name(), null, table.businessType(), null,
                        null, false, false,
                        null, null, false, false, false, false,
                        null, null, false, false, List.of(), List.of(), false, List.of(),
                        table.objectBackedPrimaryKeys(),
                        "Keep only business facts in the SPP object; migrate technical identity to APP DDL platform primary keys."));
            }
            if (!table.objectBackedIndexPaths().isEmpty()) {
                plans.add(new AppSemanticMigrationPlan("OBJECT_BACKED_INDEX", "APP_DDL_TABLE",
                        table.name(), table.name(), null, table.businessType(), null,
                        null, false, false,
                        null, null, false, false, false, false,
                        null, null, false, false, List.of(), List.of(), false, List.of(),
                        table.objectBackedIndexPaths(),
                        "Keep only business lookup fields in the SPP object; migrate technical lookup keys to APP DDL platform columns or indexes."));
            }
        }
        for (RepositoryQueryPlan plan : repositoryQueryPlans) {
            if (plan.escapeHatch()) {
                plans.add(new AppSemanticMigrationPlan("REPOSITORY_ESCAPE_HATCH", "REPOSITORY_QUERY",
                        plan.serviceName(), plan.appDdlTableName(), plan.serviceName(), plan.objectType(),
                        plan.repositoryAdapterName(), null, false, false,
                        null, null, false, false, false, false,
                        plan.source(), plan.appDdlIndexName(), plan.appDdlDerived(), plan.escapeHatch(),
                        plan.repositoryPaths(), plan.repositoryColumns(), plan.appDdlColumnPushdown(),
                        plan.externalAggregateRoots(), plan.repositoryPaths(),
                        "Prefer APP DDL primary keys, foreign keys or named indexes over explicit repository argument paths."));
            }
        }
        for (ObjectSnapshotPlan plan : objectSnapshotPlans) {
            if (plan.escapeHatch() || plan.objectKeyEscapeHatch()) {
                plans.add(new AppSemanticMigrationPlan("SNAPSHOT_ESCAPE_HATCH", "OBJECT_SNAPSHOT",
                        plan.serviceName(), plan.appDdlTableName(), plan.serviceName(), plan.objectType(),
                        plan.repositoryAdapterName(), null, false, false,
                        plan.snapshotBoundary(), plan.recoveryRole(), plan.transactionEvidence(), plan.currentObject(),
                        plan.argumentRecoveryEvidence(), plan.rollbackRecoveryEvidence(),
                        plan.objectKeySource(), plan.objectKeyAppDdlIndexName(), plan.objectKeyAppDdlDerived(),
                        plan.objectKeyEscapeHatch(), plan.appDdlObjectKeyPaths(), plan.objectKeyColumns(),
                        plan.appDdlObjectKeyPushdown(), plan.externalObjectKeyRoots(), plan.objectIdPaths(),
                        "Prefer APP DDL primary keys or named indexes over explicit snapshot object key paths."));
            }
            if (plan.currentObject()) {
                plans.add(new AppSemanticMigrationPlan("CURRENT_SNAPSHOT_CONTEXT", "OBJECT_SNAPSHOT",
                        plan.serviceName(), plan.appDdlTableName(), plan.serviceName(), plan.objectType(),
                        plan.repositoryAdapterName(), null, false, false,
                        plan.snapshotBoundary(), plan.recoveryRole(), plan.transactionEvidence(), plan.currentObject(),
                        plan.argumentRecoveryEvidence(), plan.rollbackRecoveryEvidence(),
                        plan.objectKeySource(), plan.objectKeyAppDdlIndexName(), plan.objectKeyAppDdlDerived(),
                        plan.objectKeyEscapeHatch(), plan.appDdlObjectKeyPaths(), plan.objectKeyColumns(),
                        plan.appDdlObjectKeyPushdown(), plan.externalObjectKeyRoots(), plan.objectIdPaths(),
                        "Treat current(...) as a scenario context locator; prefer APP DDL aggregate relations or named indexes when the object identity can be modeled statically."));
            }
        }
        for (RemoteServiceAssignment assignment : remoteAssignments) {
            PhysicalRemotePlan remotePlan = physicalRemotePlansByService.get(assignment.serviceName());
            if (assignment.referenceImplementation()) {
                plans.add(new AppSemanticMigrationPlan("REMOTE_REFERENCE_ADAPTER", "REMOTE_SERVICE",
                        assignment.serviceName(), null, assignment.serviceName(), null,
                        assignment.adapterImplementationType(), assignment.adapterRole(),
                        assignment.referenceImplementation(), assignment.externalImplementation(),
                        null, null, false, false, false, false,
                        null, null, false, false, List.of(), List.of(), false, List.of(), List.of(),
                        "Replace the reference adapter with a real external domain adapter for production deployment.",
                        remotePlan == null ? null : remotePlan.repositoryName(),
                        remotePlan == null ? null : remotePlan.repositoryAdapterName(),
                        remotePlan == null ? null : remotePlan.repositoryStorageTableName(),
                        remotePlan == null ? null : remotePlan.repositoryDatasourceUrl(),
                        remotePlan == null ? null : remotePlan.repositoryDriverClassName()));
            } else if (assignment.externalImplementation()) {
                plans.add(new AppSemanticMigrationPlan("REMOTE_EXTERNAL_ADAPTER", "REMOTE_SERVICE",
                        assignment.serviceName(), null, assignment.serviceName(), null,
                        assignment.adapterImplementationType(), assignment.adapterRole(),
                        assignment.referenceImplementation(), assignment.externalImplementation(),
                        null, null, false, false, false, false,
                        null, null, false, false, List.of(), List.of(), false, List.of(), List.of(),
                        "Remote service is bound to an external domain adapter.",
                        remotePlan == null ? null : remotePlan.repositoryName(),
                        remotePlan == null ? null : remotePlan.repositoryAdapterName(),
                        remotePlan == null ? null : remotePlan.repositoryStorageTableName(),
                        remotePlan == null ? null : remotePlan.repositoryDatasourceUrl(),
                        remotePlan == null ? null : remotePlan.repositoryDriverClassName()));
            }
        }
        if (quantumAccessPlans != null) {
            for (QuantumAccessPlan plan : quantumAccessPlans) {
                if (!"QUANTUM_SERVICE".equals(plan.idempotencyOwner())) {
                    continue;
                }
                List<String> migrationSources = quantumServiceInternalProtocolSources(plan);
                if (migrationSources.isEmpty()) {
                    continue;
                }
                plans.add(new AppSemanticMigrationPlan("QUANTUM_SERVICE_INTERNAL_PROTOCOL",
                        "QUANTUM_ACCESS", plan.serviceName(), null, plan.serviceName(), null,
                        String.join("+", plan.adapterNames()), String.join("+", plan.executionOwners()),
                        false, true,
                        plan.snapshotBoundary(), plan.idempotencyBoundary(), false, false,
                        false, false,
                        null, null, false, false, List.of(), List.of(), false, List.of(),
                        plan.attributeIds(),
                        migrationSources,
                        "Move the listed framework responsibilities for this quantum resource to the quantum service internal protocol."));
            }
        }
        return List.copyOf(plans);
    }

    private List<String> quantumServiceInternalProtocolSources(QuantumAccessPlan plan) {
        if (plan == null) {
            return List.of();
        }
        List<String> sources = new ArrayList<>();
        if (plan.objectSnapshotManaged()) {
            sources.add("objectSnapshot");
        }
        if (plan.objectCompensationManaged()) {
            sources.add("objectCompensation");
        }
        return sources;
    }

    private List<AppSemanticMigrationSummaryPlan> appSemanticMigrationSummaryPlans(
            List<AppSemanticMigrationPlan> plans) {
        Map<String, AppSemanticMigrationSummaryPlanBuilder> builders = new LinkedHashMap<>();
        for (AppSemanticMigrationPlan plan : plans) {
            builders.computeIfAbsent(plan.migrationType(), AppSemanticMigrationSummaryPlanBuilder::new)
                    .add(plan);
        }
        return builders.values().stream()
                .map(AppSemanticMigrationSummaryPlanBuilder::build)
                .toList();
    }

    private Map<String, List<AppSemanticMigrationPlan>> appSemanticMigrationPlansBySingleKey(
            List<AppSemanticMigrationPlan> plans, Function<AppSemanticMigrationPlan, String> keyMapper) {
        Map<String, List<AppSemanticMigrationPlan>> plansByKey = new LinkedHashMap<>();
        for (AppSemanticMigrationPlan plan : plans) {
            plansByKey.computeIfAbsent(catalogIndexKey(keyMapper.apply(plan)), ignored -> new ArrayList<>())
                    .add(plan);
        }
        return copyPlanListMap(plansByKey);
    }

    private Map<String, List<AppSemanticMigrationPlan>> appSemanticMigrationPlansByParticipantCategory(
            List<AppSemanticMigrationPlan> plans) {
        Map<String, List<AppSemanticMigrationPlan>> plansByKey = new LinkedHashMap<>();
        for (AppSemanticMigrationPlan plan : plans) {
            List<String> participantCategories = plan.participantCategories().isEmpty()
                    ? List.of("NO_PARTICIPANT_CATEGORY")
                    : plan.participantCategories();
            for (String participantCategory : participantCategories) {
                plansByKey.computeIfAbsent(catalogIndexKey(participantCategory), ignored -> new ArrayList<>())
                        .add(plan);
            }
        }
        return copyPlanListMap(plansByKey);
    }

    private Map<String, List<AppSemanticMigrationPlan>> appSemanticMigrationPlansByRoleOnlyReadiness(
            List<AppSemanticMigrationPlan> plans,
            List<ServiceParticipantRoleOnlyMigrationActionPlan> roleOnlyMigrationActionPlans) {
        Map<String, List<AppSemanticMigrationPlan>> plansByKey = new LinkedHashMap<>();
        for (AppSemanticMigrationPlan plan : plans) {
            plansByKey.computeIfAbsent(appSemanticMigrationRoleOnlyReadiness(plan, roleOnlyMigrationActionPlans),
                    ignored -> new ArrayList<>()).add(plan);
        }
        return copyPlanListMap(plansByKey);
    }

    private String appSemanticMigrationRoleOnlyReadiness(
            AppSemanticMigrationPlan plan,
            List<ServiceParticipantRoleOnlyMigrationActionPlan> roleOnlyMigrationActionPlans) {
        if (plan == null || !"SERVICE_NON_ROLE_PARTICIPANT".equals(plan.migrationType())) {
            return "NO_ROLE_ONLY_BOUNDARY";
        }
        List<ServiceParticipantRoleOnlyMigrationActionPlan> matchingActionPlans =
                (roleOnlyMigrationActionPlans == null ? List.<ServiceParticipantRoleOnlyMigrationActionPlan>of()
                        : roleOnlyMigrationActionPlans).stream()
                        .filter(actionPlan -> actionPlan != null
                                && Objects.equals(plan.serviceName(), actionPlan.serviceName()))
                        .filter(actionPlan -> plan.paths().isEmpty()
                                || plan.paths().contains(actionPlan.path()))
                        .toList();
        if (!matchingActionPlans.isEmpty()
                && matchingActionPlans.stream().allMatch(ServiceParticipantRoleOnlyMigrationActionPlan::roleOnlyReady)) {
            return "ROLE_ONLY_READY";
        }
        return "ROLE_ONLY_BLOCKED";
    }

