    private Map<String, List<String>> reversalRulesByTarget(Map<String, List<String>> rules) {
        Map<String, List<String>> rulesByTarget = new LinkedHashMap<>();
        for (Map.Entry<String, List<String>> entry : rules.entrySet()) {
            String source = catalogIndexKey(entry.getKey());
            for (String target : entry.getValue()) {
                rulesByTarget.computeIfAbsent(catalogIndexKey(target), ignored -> new ArrayList<>())
                        .add(source);
            }
        }
        Map<String, List<String>> copy = new LinkedHashMap<>();
        for (Map.Entry<String, List<String>> entry : rulesByTarget.entrySet()) {
            copy.put(entry.getKey(), List.copyOf(entry.getValue()));
        }
        return copy;
    }

    private Map<String, List<String>> tccLifecycleRulesByTarget(Map<String, List<String>> rules) {
        Map<String, List<String>> rulesByTarget = new LinkedHashMap<>();
        for (Map.Entry<String, List<String>> entry : rules.entrySet()) {
            List<String> lifecycleServices = entry.getValue();
            addTccLifecycleRuleTarget(rulesByTarget, entry.getKey(), lifecycleServices, 0, "confirm");
            addTccLifecycleRuleTarget(rulesByTarget, entry.getKey(), lifecycleServices, 1, "cancel");
        }
        Map<String, List<String>> copy = new LinkedHashMap<>();
        for (Map.Entry<String, List<String>> entry : rulesByTarget.entrySet()) {
            copy.put(entry.getKey(), List.copyOf(entry.getValue()));
        }
        return copy;
    }

    private void addTccLifecycleRuleTarget(Map<String, List<String>> rulesByTarget,
                                           String tryServiceName,
                                           List<String> lifecycleServices,
                                           int serviceIndex,
                                           String phaseName) {
        if (lifecycleServices == null || lifecycleServices.size() <= serviceIndex) {
            return;
        }
        String targetServiceName = lifecycleServices.get(serviceIndex);
        rulesByTarget.computeIfAbsent(catalogIndexKey(targetServiceName), ignored -> new ArrayList<>())
                .add(catalogIndexKey(tryServiceName) + ":" + phaseName);
    }

    private List<TransactionReversalRule> transactionReversalRules(
            Map<String, List<String>> compensationRules,
            Map<String, List<String>> remoteCompensationRules,
            Map<String, List<String>> tccLifecycleRules) {
        List<TransactionReversalRule> rules = new ArrayList<>();
        for (Map.Entry<String, List<String>> entry : compensationRules.entrySet()) {
            addTransactionReversalRules(rules, "OBJECT_COMPENSATION", entry.getKey(), entry.getValue(),
                    "compensate");
        }
        for (Map.Entry<String, List<String>> entry : remoteCompensationRules.entrySet()) {
            addTransactionReversalRules(rules, "REMOTE_COMPENSATION", entry.getKey(), entry.getValue(),
                    "remoteCompensate");
        }
        for (Map.Entry<String, List<String>> entry : tccLifecycleRules.entrySet()) {
            List<String> lifecycleServices = entry.getValue();
            boolean lifecycleComplete = lifecycleServices != null && lifecycleServices.size() >= 2
                    && hasText(lifecycleServices.get(0))
                    && hasText(lifecycleServices.get(1));
            addTransactionReversalRule(rules, "TCC_LIFECYCLE", entry.getKey(),
                    lifecycleServices == null || lifecycleServices.isEmpty() ? null : lifecycleServices.get(0),
                    "confirm", 0, lifecycleComplete);
            addTransactionReversalRule(rules, "TCC_LIFECYCLE", entry.getKey(),
                    lifecycleServices == null || lifecycleServices.size() < 2 ? null : lifecycleServices.get(1),
                    "cancel", 1, lifecycleComplete);
        }
        return List.copyOf(rules);
    }

    private void addTransactionReversalRules(List<TransactionReversalRule> rules,
                                             String ruleKind,
                                             String sourceServiceName,
                                             List<String> targetServiceNames,
                                             String phaseName) {
        if (targetServiceNames == null || targetServiceNames.isEmpty()) {
            addTransactionReversalRule(rules, ruleKind, sourceServiceName, null, phaseName, 0, false);
            return;
        }
        for (int i = 0; i < targetServiceNames.size(); i++) {
            addTransactionReversalRule(rules, ruleKind, sourceServiceName, targetServiceNames.get(i),
                    phaseName, i, true);
        }
    }

    private void addTransactionReversalRule(List<TransactionReversalRule> rules,
                                            String ruleKind,
                                            String sourceServiceName,
                                            String targetServiceName,
                                            String phaseName,
                                            int targetIndex,
                                            boolean lifecycleComplete) {
        boolean targetDeclared = hasText(targetServiceName);
        String source = catalogIndexKey(sourceServiceName);
        String target = catalogIndexKey(targetServiceName);
        String phase = catalogIndexKey(phaseName);
        String readiness = transactionReversalReadiness(ruleKind, targetDeclared, lifecycleComplete);
        List<String> missingReasons = transactionReversalMissingReasons(ruleKind, source, target, phase,
                targetDeclared, lifecycleComplete);
        List<String> readyReasons = missingReasons.isEmpty()
                ? transactionReversalReadyReasons(ruleKind, source, target, phase, targetDeclared,
                        lifecycleComplete)
                : List.of();
        List<String> actions = transactionReversalActions(missingReasons);
        String reversalPath = transactionReversalPath(source, target, phase);
        String executionContract = transactionReversalExecutionContract(ruleKind, phase, readiness);
        rules.add(new TransactionReversalRule(ruleKind, source, target, phase, targetIndex, targetDeclared,
                lifecycleComplete, readiness, readyReasons, missingReasons, actions, reversalPath,
                executionContract));
    }

    private String transactionReversalReadiness(String ruleKind,
                                                boolean targetDeclared,
                                                boolean lifecycleComplete) {
        if (!targetDeclared) {
            return "REVERSAL_TARGET_MISSING";
        }
        if ("TCC_LIFECYCLE".equals(ruleKind) && !lifecycleComplete) {
            return "TCC_LIFECYCLE_INCOMPLETE";
        }
        if ("REMOTE_COMPENSATION".equals(ruleKind)) {
            return "REMOTE_REVERSAL_DECLARED";
        }
        if ("OBJECT_COMPENSATION".equals(ruleKind)) {
            return "OBJECT_REVERSAL_DECLARED";
        }
        if ("TCC_LIFECYCLE".equals(ruleKind)) {
            return "TCC_LIFECYCLE_DECLARED";
        }
        return "REVERSAL_DECLARED";
    }

    private List<String> transactionReversalReadyReasons(String ruleKind,
                                                         String sourceServiceName,
                                                         String targetServiceName,
                                                         String phaseName,
                                                         boolean targetDeclared,
                                                         boolean lifecycleComplete) {
        List<String> reasons = new ArrayList<>();
        if (hasText(ruleKind)) {
            reasons.add("kind:" + ruleKind);
        }
        if (hasText(sourceServiceName)) {
            reasons.add("source");
        }
        if (targetDeclared && hasText(targetServiceName)) {
            reasons.add("targetDeclared");
        }
        if (hasText(phaseName)) {
            reasons.add("phase");
        }
        if (!"TCC_LIFECYCLE".equals(ruleKind) || lifecycleComplete) {
            reasons.add("reversalLifecycleReady");
        }
        if ("OBJECT_COMPENSATION".equals(ruleKind)) {
            reasons.add("objectServiceReversal");
        } else if ("REMOTE_COMPENSATION".equals(ruleKind)) {
            reasons.add("remoteServiceReversal");
        } else if ("TCC_LIFECYCLE".equals(ruleKind)) {
            reasons.add("tccLifecycleReversal");
        }
        return List.copyOf(reasons);
    }

    private List<String> transactionReversalMissingReasons(String ruleKind,
                                                           String sourceServiceName,
                                                           String targetServiceName,
                                                           String phaseName,
                                                           boolean targetDeclared,
                                                           boolean lifecycleComplete) {
        List<String> missing = new ArrayList<>();
        if (!hasText(ruleKind)) {
            missing.add("kind");
        }
        if (!hasText(sourceServiceName)) {
            missing.add("source");
        }
        if (!targetDeclared || !hasText(targetServiceName)) {
            missing.add("target");
        }
        if (!hasText(phaseName)) {
            missing.add("phase");
        }
        if ("TCC_LIFECYCLE".equals(ruleKind) && !lifecycleComplete) {
            missing.add("tccLifecycle");
        }
        return List.copyOf(missing);
    }

    private List<String> transactionReversalActions(List<String> missingReasons) {
        if (missingReasons == null || missingReasons.isEmpty()) {
            return List.of("NO_ACTION_REQUIRED");
        }
        LinkedHashSet<String> actions = new LinkedHashSet<>();
        for (String reason : missingReasons) {
            switch (reason) {
                case "rule" -> actions.add("declareTransactionReversalRule");
                case "kind" -> actions.add("classifyTransactionReversalKind");
                case "source" -> actions.add("bindReversalSourceService");
                case "target" -> actions.add("declareObjectCompensationOrLifecycleTarget");
                case "phase" -> actions.add("declareReversalPhase");
                case "tccLifecycle" -> actions.add("declareTccConfirmAndCancelLifecycle");
                default -> actions.add("resolveTransactionReversalReadiness");
            }
        }
        return List.copyOf(actions);
    }

    private String transactionReversalPath(String sourceServiceName,
                                           String targetServiceName,
                                           String phaseName) {
        return catalogIndexKey(sourceServiceName) + "->" + catalogIndexKey(targetServiceName)
                + ":" + catalogIndexKey(phaseName);
    }

    private String transactionReversalExecutionContract(String ruleKind,
                                                        String phaseName,
                                                        String readiness) {
        return catalogIndexKey(ruleKind) + "+" + catalogIndexKey(phaseName)
                + "+" + catalogIndexKey(readiness);
    }

