    private static String physicalQuantumImplementationReadiness(PhysicalQuantumPlan plan) {
        if ("QUANTUM_SERVICE".equals(plan.implementationStrategy())) {
            if (!hasText(plan.endpoint())) {
                return "QUANTUM_SERVICE_ENDPOINT_MISSING";
            }
            if (!isAbsoluteHttpEndpoint(plan.endpoint())) {
                return "QUANTUM_SERVICE_ENDPOINT_INVALID";
            }
            if (!quantumServiceExternalImplementationReady(plan)) {
                return "QUANTUM_SERVICE_CONTRACT_ONLY";
            }
            return "QUANTUM_SERVICE_PRODUCTION_READY";
        }
        if ("TCC_OBJECT_STORE".equals(plan.implementationStrategy())) {
            return plan.backendSupportedTransactions().contains("tcc")
                    && plan.backendSupportedTransactions().contains("quantum")
                    ? "TCC_OBJECT_STORE_READY"
                    : "TCC_OBJECT_STORE_BACKEND_INCOMPLETE";
        }
        if ("GLOBAL_QUANTUM_STORE".equals(plan.implementationStrategy())) {
            return hasText(plan.datasourceUrl())
                    && hasText(plan.driverClassName())
                    && hasText(plan.journalTableName())
                    && hasText(plan.valueTableName())
                    ? "LOCAL_JDBC_QUANTUM_READY"
                    : "LOCAL_JDBC_QUANTUM_INCOMPLETE";
        }
        return "QUANTUM_IMPLEMENTATION_UNCLASSIFIED";
    }

