    private static boolean idempotencyBoundaryReady(IdempotencyPlan plan) {
        if (!plan.idempotencyKeyAvailable() || !plan.adapterAvailable()
                || !plan.adapterSupportsTransaction()) {
            return false;
        }
        String owner = plan.idempotencyOwner() == null ? "" : plan.idempotencyOwner();
        if ("FRAMEWORK".equals(owner)) {
            return idempotencyRuntimeStoreAvailable(plan);
        }
        return hasText(plan.idempotencyOwnerStoreNames())
                || hasText(plan.idempotencyOwnerAdapterNames())
                || hasText(plan.idempotencyOwnerAccessModes())
                || hasText(plan.idempotencyOwnerAttributeIds());
    }

    private static boolean idempotencyRuntimeStoreAvailable(IdempotencyPlan plan) {
        return hasText(plan.idempotencyStoreName())
                && hasText(plan.idempotencyTableName())
                && hasText(plan.idempotencyDatasourceUrl())
                && hasText(plan.idempotencyDriverClassName());
    }

