    private List<SagaRecoveryEvidenceReview> sagaRecoveryEvidencePlans(
            List<SagaTransactionCallPlan> callPlans) {
        List<SagaRecoveryEvidenceReview> reviews = new ArrayList<>();
        for (SagaTransactionCallPlan callPlan : callPlans) {
            addSagaRecoveryEvidencePlans(reviews, callPlan, "ARGUMENT",
                    callPlan.argumentRecoveryEvidencePlans());
            addSagaRecoveryEvidencePlans(reviews, callPlan, "ROLLBACK",
                    callPlan.rollbackRecoveryEvidencePlans());
        }
        return List.copyOf(reviews);
    }

    private void addSagaRecoveryEvidencePlans(List<SagaRecoveryEvidenceReview> reviews,
                                              SagaTransactionCallPlan callPlan,
                                              String evidenceRole,
                                              List<SagaRecoveryEvidencePlan> evidencePlans) {
        for (SagaRecoveryEvidencePlan evidencePlan : evidencePlans) {
            List<String> missingReasons = sagaRecoveryEvidenceMissingReasons(callPlan, evidenceRole, evidencePlan);
            String readiness = missingReasons.isEmpty()
                    ? "SAGA_RECOVERY_EVIDENCE_READY"
                    : "SAGA_RECOVERY_EVIDENCE_INCOMPLETE";
            List<String> readyReasons = missingReasons.isEmpty()
                    ? sagaRecoveryEvidenceReadyReasons(callPlan, evidenceRole, evidencePlan)
                    : List.of();
            List<String> normalizedMissingReasons = missingReasons.isEmpty()
                    ? List.of("NO_MISSING_SAGA_RECOVERY_EVIDENCE_REASON")
                    : missingReasons;
            List<String> actions = sagaRecoveryEvidenceActions(missingReasons);
            String evidencePath = sagaRecoveryEvidencePath(callPlan.sagaServiceName(),
                    callPlan.targetServiceName(), evidenceRole, evidencePlan.objectType());
            reviews.add(new SagaRecoveryEvidenceReview(
                    callPlan.sagaServiceName(),
                    callPlan.targetServiceName(),
                    evidenceRole,
                    evidencePlan.objectType(),
                    evidencePlan.ruleSource(),
                    evidencePlan.timing(),
                    evidencePlan.effectiveSavePhases(),
                    evidencePlan.snapshotBoundary(),
                    evidencePlan.recoveryRole(),
                    evidencePlan.objectIdPaths(),
                    evidencePlan.repositoryName(),
                    evidencePlan.resolvedRepositoryName(),
                    evidencePlan.repositoryAdapterName(),
                    evidencePlan.repositoryAppDdlTables(),
                    evidencePlan.snapshotStorageTableName(),
                    readiness,
                    readyReasons,
                    normalizedMissingReasons,
                    actions,
                    evidencePath,
                    sagaRecoveryEvidenceContract(evidencePath, evidencePlan.snapshotBoundary(),
                            evidencePlan.recoveryRole(),
                            firstNonBlank(evidencePlan.resolvedRepositoryName(), evidencePlan.repositoryName()),
                            evidencePlan.repositoryAdapterName(),
                            evidencePlan.repositoryAppDdlTables(),
                            evidencePlan.snapshotStorageTableName(),
                            readiness)));
        }
    }

    private List<String> sagaRecoveryEvidenceReadyReasons(SagaTransactionCallPlan callPlan,
                                                          String evidenceRole,
                                                          SagaRecoveryEvidencePlan evidencePlan) {
        List<String> reasons = new ArrayList<>();
        if (!isBlank(callPlan.sagaServiceName())) {
            reasons.add("saga");
        }
        if (!isBlank(callPlan.targetServiceName())) {
            reasons.add("targetService");
        }
        if (!isBlank(evidenceRole)) {
            reasons.add("evidenceRole:" + evidenceRole);
        }
        if (!isBlank(evidencePlan.objectType())) {
            reasons.add("objectType");
        }
        if (!isBlank(evidencePlan.ruleSource())) {
            reasons.add("ruleSource");
        }
        if (!evidencePlan.effectiveSavePhases().isEmpty()) {
            reasons.add("savePhase");
        }
        if (!isBlank(evidencePlan.snapshotBoundary())) {
            reasons.add("snapshotBoundary");
        }
        if (!isBlank(evidencePlan.recoveryRole())) {
            reasons.add("recoveryRole");
        }
        if (!evidencePlan.objectIdPaths().isEmpty()) {
            reasons.add("objectKey");
        }
        if (!isBlank(firstNonBlank(evidencePlan.resolvedRepositoryName(), evidencePlan.repositoryName()))) {
            reasons.add("repository");
        }
        if (!isBlank(evidencePlan.repositoryAdapterName())) {
            reasons.add("repositoryAdapter");
        }
        if (evidencePlan.repositoryAppDdlTables()) {
            reasons.add("repositoryAppDdl");
        }
        if (!isBlank(evidencePlan.snapshotStorageTableName())) {
            reasons.add("snapshotStorageTable");
        }
        return List.copyOf(reasons);
    }

    private List<String> sagaRecoveryEvidenceMissingReasons(SagaTransactionCallPlan callPlan,
                                                            String evidenceRole,
                                                            SagaRecoveryEvidencePlan evidencePlan) {
        List<String> missing = new ArrayList<>();
        if (isBlank(callPlan.sagaServiceName())) {
            missing.add("saga");
        }
        if (isBlank(callPlan.targetServiceName())) {
            missing.add("targetService");
        }
        if (isBlank(evidenceRole)) {
            missing.add("evidenceRole");
        }
        if (isBlank(evidencePlan.objectType())) {
            missing.add("objectType");
        }
        if (isBlank(evidencePlan.ruleSource())) {
            missing.add("ruleSource");
        }
        if (evidencePlan.effectiveSavePhases().isEmpty()) {
            missing.add("savePhase");
        }
        if (isBlank(evidencePlan.snapshotBoundary())) {
            missing.add("snapshotBoundary");
        }
        if (isBlank(evidencePlan.recoveryRole())) {
            missing.add("recoveryRole");
        }
        if (evidencePlan.objectIdPaths().isEmpty()) {
            missing.add("objectKey");
        }
        if (isBlank(firstNonBlank(evidencePlan.resolvedRepositoryName(), evidencePlan.repositoryName()))) {
            missing.add("repository");
        }
        if (isBlank(evidencePlan.repositoryAdapterName())) {
            missing.add("repositoryAdapter");
        }
        if (!evidencePlan.repositoryAppDdlTables()) {
            missing.add("repositoryAppDdl");
        }
        if (isBlank(evidencePlan.snapshotStorageTableName())) {
            missing.add("snapshotStorageTable");
        }
        return List.copyOf(missing);
    }

    private List<String> sagaRecoveryEvidenceActions(List<String> missingReasons) {
        if (missingReasons == null || missingReasons.isEmpty()) {
            return List.of("NO_ACTION_REQUIRED");
        }
        LinkedHashSet<String> actions = new LinkedHashSet<>();
        for (String reason : missingReasons) {
            switch (reason) {
                case "saga", "targetService", "evidenceRole" ->
                        actions.add("bindSagaTransactionRecoveryEvidence");
                case "objectType", "ruleSource", "savePhase", "snapshotBoundary", "recoveryRole" ->
                        actions.add("declareSnapshotArgumentRecovery");
                case "objectKey" -> actions.add("pushSagaRecoveryObjectKeyToAppDdl");
                case "repository" -> actions.add("bindSagaRecoveryEvidenceRepository");
                case "repositoryAdapter" -> actions.add("configureSagaRecoveryRepositoryAdapter");
                case "repositoryAppDdl" -> actions.add("enableRepositoryAppDdlTables");
                case "snapshotStorageTable" -> actions.add("configureSnapshotStorageTable");
                default -> actions.add("resolveSagaRecoveryEvidenceReadiness");
            }
        }
        return List.copyOf(actions);
    }

    private String sagaRecoveryEvidencePath(String sagaServiceName, String targetServiceName, String evidenceRole,
                                            String objectType) {
        return valueOrDash(sagaServiceName) + "->" + valueOrDash(targetServiceName)
                + ":" + valueOrDash(evidenceRole) + ":" + valueOrDash(objectType);
    }

    private String sagaRecoveryEvidenceContract(String evidencePath,
                                                String snapshotBoundary,
                                                String recoveryRole,
                                                String repositoryName,
                                                String repositoryAdapterName,
                                                boolean repositoryAppDdlTables,
                                                String snapshotStorageTableName,
                                                String readiness) {
        return valueOrDash(evidencePath)
                + "->" + valueOrDash(snapshotBoundary)
                + "+" + valueOrDash(recoveryRole)
                + "+" + valueOrDash(repositoryName)
                + "+" + valueOrDash(repositoryAdapterName)
                + "+" + (repositoryAppDdlTables ? "APP_DDL_TABLES" : "NO_APP_DDL_TABLES")
                + "+" + valueOrDash(snapshotStorageTableName)
                + ":" + valueOrDash(readiness);
    }

