    private Map<String, TransactionSnapshotRetentionExecutionPlan>
            transactionSnapshotRetentionExecutionPlansByResource(
                    List<TransactionSnapshotRetentionExecutionPlan> plans) {
        Map<String, TransactionSnapshotRetentionExecutionPlan> plansByResource = new LinkedHashMap<>();
        for (TransactionSnapshotRetentionExecutionPlan plan : plans) {
            plansByResource.put(catalogIndexKey(plan.resourceName()), plan);
        }
        return Map.copyOf(plansByResource);
    }

    private boolean transactionSnapshotRetentionExecutionReady(
            TransactionSnapshotRetentionExecutionPlan plan) {
        return hasText(plan.retentionPlanName())
                && hasText(plan.automationPlanName())
                && hasText(firstNonBlank(plan.resolvedRepositoryName(), plan.repositoryName()))
                && hasText(plan.serviceName())
                && hasText(plan.resourceName())
                && plan.retentionMillis() > 0
                && plan.archiveRetentionMillis() > 0
                && hasText(plan.cutoffSource())
                && hasText(plan.archiveCutoffSource())
                && hasText(plan.archiveRuntimeOperation())
                && hasText(plan.pruneArchiveRuntimeOperation())
                && hasText(plan.hotHistoryTableName())
                && hasText(plan.coldArchiveTableName())
                && hasText(plan.schedulerPropertyPrefix())
                && hasText(plan.retentionMillisPropertyName())
                && hasText(plan.archiveRetentionMillisPropertyName());
    }

