    private List<String> objectRepositoryRoles(ObjectRepositoryPlan plan) {
        List<String> roles = new ArrayList<>();
        if (plan.repositoryQuery()) {
            roles.add("REPOSITORY_QUERY");
        }
        if (plan.objectSnapshot()) {
            roles.add("OBJECT_SNAPSHOT");
        }
        if (plan.transactionEvidence()) {
            roles.add("TRANSACTION_EVIDENCE");
        }
        if (plan.collectionQuery()) {
            roles.add("COLLECTION_QUERY");
        }
        if (roles.isEmpty()) {
            roles.add("UNUSED_REPOSITORY_PLAN");
        }
        return roles;
    }

    private boolean objectRepositoryReady(ObjectRepositoryPlan plan) {
        boolean physicalReady = hasText(plan.resolvedRepositoryName())
                && hasText(plan.adapterName())
                && hasText(plan.storageTableName())
                && hasText(plan.datasourceUrl())
                && hasText(plan.driverClassName());
        if (!physicalReady) {
            return false;
        }
        if (plan.repositoryQuery()) {
            return plan.appDdlTables()
                    && plan.appDdlColumnPushdown()
                    && !plan.keySources().isEmpty()
                    && !plan.objectKeyColumns().isEmpty();
        }
        return true;
    }

