    private boolean repositoryMigrationColumnPushdownComplete(RepositoryMigrationPlan plan) {
        return plan.totalQueryCount() > 0 && plan.appDdlColumnPushdownCount() == plan.totalQueryCount();
    }

    private boolean repositoryMigrationReady(RepositoryMigrationPlan plan) {
        return plan.totalQueryCount() > 0
                && plan.appDdlDerivedQueryCount() == plan.totalQueryCount()
                && repositoryMigrationColumnPushdownComplete(plan)
                && plan.escapeHatchQueryCount() == 0
                && hasText(firstNonBlank(plan.resolvedRepositoryName(), plan.repositoryName()))
                && hasText(plan.repositoryAdapterName())
                && hasText(plan.storageTableName())
                && hasText(plan.datasourceUrl())
                && hasText(plan.driverClassName());
    }

