    private String currentResolutionKey(CurrentSnapshotContextPlan plan) {
        if (plan.ambiguousSagaParameter()) {
            return "AMBIGUOUS_SAGA_PARAMETER";
        }
        if (plan.resolvedFromSagaParameter()) {
            return "RESOLVED_FROM_SAGA_PARAMETER";
        }
        return "MISSING_SAGA_PARAMETER";
    }

    private boolean currentContextClosed(CurrentSnapshotContextPlan plan) {
        return plan.resolvedFromSagaParameter()
                && !plan.ambiguousSagaParameter()
                && plan.objectKeyAppDdlDerived()
                && plan.appDdlObjectKeyPushdown();
    }

    private String quantumServiceProtocolReadiness(QuantumAccessPlan plan) {
        if (!plan.implementationStrategies().contains("QUANTUM_SERVICE")) {
            return "QUANTUM_SERVICE_PROTOCOL_NOT_REQUIRED";
        }
        if (plan.serviceInternalIdempotencyManaged()
                && plan.serviceInternalSnapshotManaged()
                && plan.serviceInternalReversalManaged()
                && plan.negativeDeltaReversal()
                && plan.accessContractAvailable()) {
            return "QUANTUM_SERVICE_PROTOCOL_READY";
        }
        return "QUANTUM_SERVICE_PROTOCOL_INCOMPLETE";
    }

