    private Map<String, List<ScopeHeaderPlan>> scopeHeaderPlansByListKey(
            List<ScopeHeaderPlan> plans,
            Function<ScopeHeaderPlan, List<String>> keyMapper,
            String emptyKey) {
        Map<String, List<ScopeHeaderPlan>> plansByKey = new LinkedHashMap<>();
        for (ScopeHeaderPlan plan : plans) {
            List<String> keys = keyMapper.apply(plan);
            if ((keys == null || keys.isEmpty()) && emptyKey != null && !emptyKey.isBlank()) {
                plansByKey.computeIfAbsent(emptyKey, ignored -> new ArrayList<>()).add(plan);
            }
            if (keys == null) {
                continue;
            }
            for (String key : keys) {
                plansByKey.computeIfAbsent(catalogIndexKey(key), ignored -> new ArrayList<>()).add(plan);
            }
        }
        return copyPlanListMap(plansByKey);
    }

    private <T> Map<String, List<T>> copyPlanListMap(Map<String, List<T>> plansByKey) {
        Map<String, List<T>> copy = new LinkedHashMap<>();
        for (Map.Entry<String, List<T>> entry : plansByKey.entrySet()) {
            copy.put(entry.getKey(), List.copyOf(entry.getValue()));
        }
        return copy;
    }

    private String catalogIndexKey(String value) {
        return value == null || value.isBlank() ? "UNASSIGNED" : value;
    }

    private static boolean hasText(String value) {
        return value != null && !value.isBlank();
    }

    private String summaryIndexKey(String value) {
        return catalogIndexKey(value);
    }

    private List<TransactionSnapshotPlan> transactionSnapshotPlans(List<GeneratedServiceMetadata> metadata,
                                                                   List<ObjectSnapshotPlan> objectSnapshotPlans) {
        Map<String, String> resourceByServiceName = metadata.stream()
                .filter(service -> service.serviceName() != null && !service.serviceName().isBlank())
                .collect(Collectors.toMap(GeneratedServiceMetadata::serviceName,
                        service -> nullToBlank(service.transactionResourceId()),
                        (left, right) -> left, LinkedHashMap::new));
        return objectSnapshotPlans.stream()
                .filter(ObjectSnapshotPlan::transactionEvidence)
                .map(plan -> {
                    String storageTableName = nullToBlank(plan.snapshotStorageTableName());
                    String historyTableName = nullToBlank(plan.transactionHistoryTableName());
                    String archiveTableName = nullToBlank(plan.transactionArchiveTableName());
                    return new TransactionSnapshotPlan(plan.serviceName(),
                            resourceByServiceName.getOrDefault(plan.serviceName(), ""),
                            plan.objectType(),
                            plan.repositoryName(), plan.resolvedRepositoryName(), plan.repositoryAdapterName(),
                            storageTableName, historyTableName, archiveTableName,
                            plan.repositoryAdapterConfiguration().getOrDefault("datasourceUrl", ""),
                            plan.repositoryAdapterConfiguration().getOrDefault("driverClassName", ""),
                            plan.repositoryAdapterConfiguration(),
                            plan.objectIdPaths(), plan.effectiveSavePhases(), plan.snapshotBoundary(),
                            plan.recoveryRole(), "trace_id", "transaction_id", "resource_id", "phase",
                            !storageTableName.isBlank(), !historyTableName.isBlank(), !archiveTableName.isBlank(),
                            !historyTableName.isBlank(), !historyTableName.isBlank(), !historyTableName.isBlank(),
                            !historyTableName.isBlank(), !archiveTableName.isBlank());
                })
                .toList();
    }

