    public Optional<RoleParticipantIdentity> resolveRoleParticipantIdentity(String roleType, Object roleValue) {
        if (roleValue == null) {
            return Optional.empty();
        }
        Optional<List<Object>> contextPerformers = roleContextPerformers(roleType, roleValue);
        List<RoleParticipantPlan> plans = roleParticipantPlans(roleType);
        return contextPerformers
                .flatMap(performers -> roleParticipantPlan(roleType, performers.toArray()))
                .or(() -> plans.stream().findFirst())
                .map(plan -> roleIdentityFromContext(plan, contextPerformers)
                        .orElseGet(() -> roleParticipantIdentity(plan, plan.roleSourceKeyPaths(),
                                plan.roleSourceKeyPaths().stream()
                                        .map(path -> readPath(roleValue, path))
                                        .toList(),
                                // Runtime may still consume generated compatibility fields, while
                                // roleKeyComplete remains a semantic catalog signal.
                                "ROLE", true)));
    }

    private Optional<List<Object>> roleContextPerformers(String roleType, Object roleValue) {
        return RoleIdentityContext.performers(roleValue, roleType)
                .or(() -> CurrentObjectContext.findAll(roleType).stream()
                        .filter(candidate -> candidate != roleValue)
                        .filter(candidate -> Objects.equals(candidate, roleValue))
                        .map(candidate -> RoleIdentityContext.performers(candidate, roleType))
                        .flatMap(Optional::stream)
                        .findFirst());
    }

    private Optional<RoleParticipantIdentity> roleIdentityFromContext(RoleParticipantPlan plan,
                                                                     Optional<List<Object>> contextPerformers) {
        return contextPerformers
                .map(performers -> roleParticipantIdentity(plan, plan.performerKeyPaths(),
                        plan.performerKeyPaths().stream()
                                .map(path -> readPerformerPath(plan, path, performers.toArray()))
                                .toList(),
                        "ROLE_CONTEXT", plan.performerKeyComplete()));
    }

    public Optional<RoleParticipantIdentity> resolveRoleParticipantIdentityFromPerformers(String roleType,
                                                                                         Object... performers) {
        return roleParticipantPlan(roleType, performers)
                .map(plan -> roleParticipantIdentity(plan, plan.performerKeyPaths(),
                        plan.performerKeyPaths().stream()
                                .map(path -> readPerformerPath(plan, path, performers))
                                .toList(),
                        "PERFORMER", plan.performerKeyComplete()));
    }

    public <T> List<T> findRepositoryComposition(String scenarioName,
                                                 String contractType,
                                                 Object contractContext,
                                                 String roleType,
                                                 String namedIndexName,
                                                 Class<T> resultType,
                                                 Object... rolePerformers) {
        install();
        RepositoryCompositionQueryPlan plan = repositoryCompositionQueryPlan(scenarioName, contractType,
                roleType, namedIndexName)
                .orElseThrow(() -> new IllegalStateException("Repository composition query is not ready"
                        + " for role=" + blankAsDash(roleType)
                        + ", index=" + blankAsDash(namedIndexName)
                        + ", contract=" + blankAsDash(contractType)
                        + ", scenario=" + blankAsDash(scenarioName)));
        List<Object> compositionValues = repositoryCompositionValues(plan, contractContext);
        RoleParticipantIdentity performerIdentity = resolveRoleParticipantIdentityFromPerformers(roleType,
                rolePerformers)
                .filter(RoleParticipantIdentity::complete)
                .orElseThrow(() -> new IllegalStateException("Cannot resolve Role performer identity for "
                        + blankAsDash(roleType)
                        + " repository composition query " + blankAsDash(namedIndexName)));
        if (!samePaths(performerIdentity.platformColumns(), plan.rolePerformerColumns())) {
            throw new IllegalStateException("Role performer identity columns "
                    + String.join("+", performerIdentity.platformColumns())
                    + " do not match repository composition query columns "
                    + String.join("+", plan.rolePerformerColumns()));
        }
        List<String> columns = Stream.concat(plan.compositionColumns().stream(),
                        plan.rolePerformerColumns().stream())
                .toList();
        List<Object> values = Stream.concat(compositionValues.stream(),
                        performerIdentity.keyValues().stream())
                .toList();
        return getRepository().findBy(plan.roleType(), columns, values, resultType);
    }

    private Optional<RepositoryCompositionQueryPlan> repositoryCompositionQueryPlan(String scenarioName,
                                                                                   String contractType,
                                                                                   String roleType,
                                                                                   String namedIndexName) {
        return catalogGeneratedServices().repositoryCompositionQueryPlans().stream()
                .filter(RepositoryCompositionQueryPlan::executable)
                .filter(plan -> isBlankStatic(scenarioName) || scenarioName.equals(plan.scenarioName()))
                .filter(plan -> isBlankStatic(contractType) || contractType.equals(plan.contractType()))
                .filter(plan -> isBlankStatic(roleType) || roleType.equals(plan.roleType()))
                .filter(plan -> isBlankStatic(namedIndexName) || namedIndexName.equals(plan.namedIndexName()))
                .findFirst();
    }

    private List<Object> repositoryCompositionValues(RepositoryCompositionQueryPlan plan, Object contractContext) {
        if (plan == null || contractContext == null) {
            return List.of();
        }
        AppDdlCatalog.Table contractTable = appDdlCatalog.tableForBusinessType(plan.contractType())
                .orElseThrow(() -> new IllegalStateException("APP DDL contract table is missing for "
                        + blankAsDash(plan.contractType())));
        List<Object> values = new ArrayList<>();
        for (String column : plan.compositionColumns()) {
            Object value = repositoryCompositionValue(contractTable, column, contractContext)
                    .orElseThrow(() -> new IllegalStateException("Cannot resolve composition column "
                            + blankAsDash(column)
                            + " from contract " + blankAsDash(plan.contractType())));
            values.add(value);
        }
        return List.copyOf(values);
    }

    private Optional<Object> repositoryCompositionValue(AppDdlCatalog.Table contractTable,
                                                       String compositionColumn,
                                                       Object contractContext) {
        for (String primaryKey : contractTable.primaryKeys()) {
            Optional<String> column = columnForPath(contractTable, primaryKey);
            if (column.isPresent()
                    && normalizeColumnPath(column.orElseThrow()).equals(normalizeColumnPath(compositionColumn))) {
                Object value = readPath(contractContext, normalizeRepositoryPath(primaryKey,
                        contractTable.businessType()));
                if (value != null) {
                    return Optional.of(value);
                }
            }
        }
        String normalizedCompositionColumn = normalizeColumnPath(compositionColumn);
        for (AppDdlCatalog.Column column : contractTable.columns()) {
            if (normalizeColumnPath(column.name()).equals(normalizedCompositionColumn)) {
                Object value = readPath(contractContext, normalizeRepositoryPath(column.name(),
                        contractTable.businessType()));
                if (value != null) {
                    return Optional.of(value);
                }
            }
        }
        Object directValue = readPath(contractContext, compositionColumn);
        return directValue == null ? Optional.empty() : Optional.of(directValue);
    }

    private Optional<RoleParticipantPlan> roleParticipantPlan(String roleType, Object... performers) {
        List<RoleParticipantPlan> plans = roleParticipantPlans(roleType);
        Optional<RoleParticipantPlan> matchingPlan = plans.stream()
                .filter(plan -> roleParticipantPlanMatchesPerformers(plan, performers))
                .findFirst();
        if (matchingPlan.isPresent()) {
            return matchingPlan;
        }
        boolean hasPerformer = performers != null && java.util.Arrays.stream(performers)
                .anyMatch(Objects::nonNull);
        return hasPerformer ? Optional.empty() : plans.stream().findFirst();
    }

    private boolean roleParticipantPlanMatchesPerformers(RoleParticipantPlan plan, Object... performers) {
        List<Object> safePerformers = performers == null ? List.of() : java.util.Arrays.stream(performers)
                .filter(Objects::nonNull)
                .toList();
        List<String> performerTypes = plan.performerTypes();
        if (performerTypes.size() != safePerformers.size()) {
            return false;
        }
        for (int index = 0; index < performerTypes.size(); index++) {
            if (!performerTypes.get(index).equals(simpleName(safePerformers.get(index).getClass().getName()))) {
                return false;
            }
        }
        return true;
    }

    private Optional<RoleIdentity> resolveRepositoryRoleIdentity(String roleType, Object[] arguments) {
        if (arguments == null || arguments.length == 0) {
            return Optional.empty();
        }
        Optional<RoleParticipantIdentity> roleArgumentIdentity = java.util.Arrays.stream(arguments)
                .filter(Objects::nonNull)
                .filter(argument -> roleType.equals(simpleName(argument.getClass().getName())))
                .findFirst()
                .flatMap(argument -> resolveRoleParticipantIdentity(roleType, argument));
        Optional<RoleParticipantIdentity> identity = roleArgumentIdentity
                .or(() -> resolveRoleParticipantIdentityFromPerformers(roleType, arguments));
        Optional<RoleIdentity> roleIdentity = identity
                .filter(RoleParticipantIdentity::complete)
                .map(item -> new RoleIdentity(item.roleType(), item.keyPaths(), item.keyValues(),
                        item.platformColumns(), item.source(), item.complete()));
        return roleIdentity.or(() -> resolveAppDdlObjectIdentity(roleType, arguments));
    }

    private Optional<String> resolveQuantumObjectIdentity(String objectType, Object[] arguments) {
        if (arguments != null) for (Object participant : arguments) {
            if (participant == null || !objectType.equals(simpleName(participant.getClass().getName()))) continue;
            var loaded = com.servpp.service.repository.RepositoryParticipantSnapshots.objectIdentity(participant, objectType);
            if (loaded.isPresent()) return loaded;
        }
        AppDdlCatalog.Table table = appDdlCatalog.tableForBusinessType(objectType).orElse(null);
        if (table != null && !table.platformPrimaryKeys().isEmpty() && arguments != null) {
            for (Object participant : arguments) {
                if (participant == null || !objectType.equals(simpleName(participant.getClass().getName()))) continue;
                Map<String, Object> platform = com.servpp.service.repository.RepositoryParticipantSnapshots.platformFacts(participant);
                List<Object> values = table.platformPrimaryKeys().stream().map(platform::get).toList();
                if (values.stream().allMatch(this::usableIdentityValue)) return encodedObjectIdentity(values);
            }
        }
        Optional<RoleIdentity> identity = resolveRepositoryRoleIdentity(objectType, arguments);
        if (identity.isEmpty()) {
            if (table != null && !table.platformPrimaryKeys().isEmpty()) {
                throw incompleteQuantumPlatformIdentity(objectType, table, table.platformPrimaryKeys());
            }
            return Optional.empty();
        }
        RoleIdentity resolvedIdentity = identity.orElseThrow();
        if (table == null || table.platformPrimaryKeys().isEmpty()) {
            return encodedObjectIdentity(resolvedIdentity.keyValues());
        }
        Map<String, Object> valuesByColumn = new LinkedHashMap<>();
        if (resolvedIdentity.platformColumns().size() == resolvedIdentity.keyValues().size()) {
            for (int index = 0; index < resolvedIdentity.platformColumns().size(); index++) {
                valuesByColumn.put(normalizeColumnPath(resolvedIdentity.platformColumns().get(index)),
                        resolvedIdentity.keyValues().get(index));
            }
        }
        for (String primaryKeyColumn : table.platformPrimaryKeys()) {
            String normalizedColumn = normalizeColumnPath(primaryKeyColumn);
            if (!valuesByColumn.containsKey(normalizedColumn)) {
                quantumCompositionValue(primaryKeyColumn).ifPresent(value ->
                        valuesByColumn.put(normalizedColumn, value));
            }
        }
        List<Object> orderedValues = table.platformPrimaryKeys().stream()
                .map(column -> valuesByColumn.get(normalizeColumnPath(column)))
                .toList();
        if (orderedValues.stream().allMatch(this::usableIdentityValue)) {
            return encodedObjectIdentity(orderedValues);
        }
        List<String> missingColumns = table.platformPrimaryKeys().stream()
                .filter(column -> !usableIdentityValue(valuesByColumn.get(normalizeColumnPath(column))))
                .toList();
        throw incompleteQuantumPlatformIdentity(objectType, table, missingColumns);
    }

    private IllegalStateException incompleteQuantumPlatformIdentity(String objectType, AppDdlCatalog.Table table,
                                                                    List<String> missingColumns) {
        return new IllegalStateException("Quantum object identity for " + objectType
                + " is incomplete: APP DDL table " + table.name()
                + " requires platform primary key " + table.platformPrimaryKeys()
                + ", missing " + missingColumns
                + ". Bind the Role performer identity and current Contract composition before execution.");
    }

    private Optional<Object> quantumCompositionValue(String compositionColumn) {
        List<Object> candidates = new ArrayList<>();
        for (AppDdlCatalog.Table contractTable : appDdlCatalog.tables()) {
            if (!"contracts".equals(contractTable.category())) {
                continue;
            }
            Object contract = generatedServiceRuntime.findCurrentObject(contractTable.businessType()).orElse(null);
            if (contract == null) {
                continue;
            }
            for (String primaryKey : contractTable.primaryKeys()) {
                Optional<String> contractColumn = columnForPath(contractTable, primaryKey);
                if (contractColumn.isEmpty()
                        || !normalizeColumnPath(contractColumn.orElseThrow())
                        .equals(normalizeColumnPath(compositionColumn))) {
                    continue;
                }
                Object value = readPath(contract,
                        normalizeRepositoryPath(primaryKey, contractTable.businessType()));
                if (usableIdentityValue(value)) {
                    candidates.add(value);
                }
            }
        }
        if (candidates.size() > 1) {
            throw new IllegalStateException("Quantum composition column " + compositionColumn
                    + " is ambiguous in the current contract context.");
        }
        return candidates.stream().findFirst();
    }

    private Optional<String> encodedObjectIdentity(List<?> values) {
        if (values == null || values.isEmpty() || values.stream().anyMatch(value -> !usableIdentityValue(value))) {
            return Optional.empty();
        }
        List<String> encodedValues = values.stream().map(Object::toString).toList();
        return Optional.of(encodedValues.size() == 1
                ? encodedValues.get(0)
                : CompositeObjectId.encode(encodedValues));
    }

    private boolean usableIdentityValue(Object value) {
        return value != null && !value.toString().isBlank();
    }

    private Optional<RoleIdentity> resolveAppDdlObjectIdentity(String objectType, Object[] arguments) {
        if (objectType == null || objectType.isBlank() || arguments == null || arguments.length == 0) {
            return Optional.empty();
        }
        AppDdlCatalog.Table table = appDdlCatalog.tableForBusinessType(objectType).orElse(null);
        if (table == null) {
            return Optional.empty();
        }
        return java.util.Arrays.stream(arguments)
                .filter(Objects::nonNull)
                .filter(argument -> objectType.equals(simpleName(argument.getClass().getName())))
                .map(argument -> appDdlObjectIdentity(table, argument))
                .flatMap(Optional::stream)
                .findFirst();
    }

    private Optional<RoleIdentity> appDdlObjectIdentity(AppDdlCatalog.Table table, Object argument) {
        List<List<String>> candidatePaths = new ArrayList<>();
        if (!table.primaryKeys().isEmpty()) {
            candidatePaths.add(normalizeRepositoryPaths(table.primaryKeys(), table.businessType()));
        }
        table.indexPathsByName().values().stream()
                .map(paths -> normalizeRepositoryPaths(paths, table.businessType()))
                .forEach(candidatePaths::add);
        table.indexes().stream()
                .map(path -> normalizeRepositoryPaths(List.of(path), table.businessType()))
                .forEach(candidatePaths::add);
        for (List<String> paths : candidatePaths) {
            List<Object> values = paths.stream()
                    .map(path -> readPath(argument, path))
                    .toList();
            if (values.size() == paths.size()
                    && values.stream().allMatch(value -> value != null && !value.toString().isBlank())) {
                return Optional.of(new RoleIdentity(table.businessType(), paths, values,
                        repositoryColumns(table, paths), "APP_DDL_OBJECT_KEY", true));
            }
        }
        return Optional.empty();
    }

    private RoleParticipantIdentity roleParticipantIdentity(RoleParticipantPlan plan, List<String> keyPaths,
                                                           List<Object> keyValues, String source,
                                                           boolean keyComplete) {
        boolean complete = plan.complete()
                && keyComplete
                && !keyPaths.isEmpty()
                && keyPaths.size() == keyValues.size()
                && keyValues.stream().allMatch(Objects::nonNull);
        return new RoleParticipantIdentity(plan.roleType(),
                plan.roleTableName(),
                plan.mapperName(),
                plan.performerTypes(),
                keyPaths,
                plan.platformColumns(),
                keyValues,
                source,
                complete,
                plan.binding());
    }

    private Object readPerformerPath(RoleParticipantPlan plan, String path, Object... performers) {
        if (path == null || path.isBlank()) {
            return null;
        }
        int dot = path.indexOf('.');
        String performerType = dot < 0 ? path : path.substring(0, dot);
        String nestedPath = dot < 0 ? "" : path.substring(dot + 1);
        Object performer = findPerformer(plan, performerType, performers);
        return nestedPath.isBlank() ? performer : readPath(performer, nestedPath);
    }

    private Object findPerformer(RoleParticipantPlan plan, String performerType, Object... performers) {
        if (performerType == null || performerType.isBlank() || performers == null) {
            return null;
        }
        for (Object performer : performers) {
            if (performer == null) {
                continue;
            }
            if (performerType.equals(simpleName(performer.getClass().getName()))) {
                return performer;
            }
        }
        int index = plan.performerTypes().indexOf(performerType);
        return index >= 0 && index < performers.length ? performers[index] : null;
    }

    private String simpleName(String typeName) {
        if (typeName == null || typeName.isBlank()) {
            return "";
        }
        int dot = Math.max(typeName.lastIndexOf('.'), typeName.lastIndexOf('$'));
        return dot < 0 ? typeName : typeName.substring(dot + 1);
    }

    private Object readPath(Object value, String path) {
        Object current = value;
        if (path == null || path.isBlank()) {
            return current;
        }
        for (String segment : path.split("\\.")) {
            if (current == null || segment.isBlank()) {
                return null;
            }
            current = readProperty(current, segment);
        }
        return current;
    }

    private Object readProperty(Object value, String property) {
        Class<?> current = value.getClass();
        for (String methodName : List.of("get" + Character.toUpperCase(property.charAt(0)) + property.substring(1),
                property)) {
            try {
                Method method = current.getMethod(methodName);
                if (method.getParameterCount() == 0) {
                    return method.invoke(value);
                }
            } catch (ReflectiveOperationException ignored) {
                // Fall through to declared fields and superclasses.
            }
        }
        while (current != null) {
            try {
                Field field = current.getDeclaredField(property);
                field.setAccessible(true);
                return field.get(value);
            } catch (ReflectiveOperationException ignored) {
                current = current.getSuperclass();
            }
        }
        return null;
    }

    public List<String> loadAppSemanticMigrationWarnings(String resourceName) {
        ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
        InputStream stream = classLoader == null
                ? LocalGeneratedServiceRuntime.class.getResourceAsStream(addLeadingSlash(resourceName))
                : classLoader.getResourceAsStream(stripLeadingSlash(resourceName));
        if (stream == null) {
            throw new IllegalStateException("Cannot find generated APP semantic migration catalog " + resourceName);
        }
        return loadAppSemanticMigrationWarnings(stream);
    }

    public List<String> loadAppSemanticMigrationWarnings(InputStream stream) {
        Properties properties = new Properties();
        try (InputStream input = stream) {
            properties.load(input);
        } catch (IOException e) {
            throw new IllegalStateException("Cannot load generated APP semantic migration catalog", e);
        }
        generatedAppSemanticMigrationWarnings = parseAppSemanticMigrationWarnings(properties);
        generatedAppSemanticMigrationPlans = parseGeneratedAppSemanticMigrationPlans(properties);
        generatedAppSemanticMigrationSummary = parseGeneratedAppSemanticMigrationSummary(properties);
        return generatedAppSemanticMigrationWarnings;
    }

