    public LocalGeneratedServiceRuntime registerRemoteServiceAdapter(RemoteServiceAdapter adapter) {
        remoteServiceAdapters.add(adapter);
        return this;
    }

    private List<String> validatePhysicalBackendAssignments(List<PhysicalBackendAssignment> assignments) {
        List<String> errors = new ArrayList<>(physicalBackendRegistry.validate(assignments));
        validateRegisteredPhysicalBackendAdapterAmbiguity(assignments, errors);
        return List.copyOf(errors);
    }

    private void validateRegisteredPhysicalBackendAdapterAmbiguity(List<PhysicalBackendAssignment> assignments,
                                                                   List<String> errors) {
        Set<String> adapterNames = new LinkedHashSet<>();
        for (PhysicalRuntimeCatalog.PhysicalBackend backend : physicalRuntimeCatalog.backends()) {
            adapterNames.add(backend.adapterName());
        }
        for (PhysicalBackendAssignment assignment : assignments) {
            if (assignment.adapterName() != null && !assignment.adapterName().isBlank()) {
                adapterNames.add(assignment.adapterName());
            }
        }
        for (String adapterName : adapterNames) {
            List<String> matchingAdapters = new ArrayList<>();
            for (PhysicalBackendAdapter adapter : physicalBackendAdapters) {
                if (adapter.supportsBackend(adapterName)) {
                    matchingAdapters.add(adapter.implementationType());
                }
            }
            if (matchingAdapters.size() > 1) {
                errors.add("Physical backend adapter " + adapterName
                        + " has multiple registered adapters: " + String.join(", ", matchingAdapters) + ".");
            }
        }
    }

    private List<RemoteServiceAssignment> resolveRemoteServices(List<GeneratedServiceMetadata> metadata) {
        List<RemoteServiceAssignment> assignments = new ArrayList<>();
        for (GeneratedServiceMetadata service : metadata) {
            if (service.remote()) {
                Optional<RemoteServiceAdapter> adapter = remoteServiceAdapterFor(service.serviceName());
                String implementationType = adapter.map(RemoteServiceAdapter::implementationType).orElse(null);
                String adapterRole = remoteAdapterRole(service.serviceName(), implementationType, adapter.isPresent());
                assignments.add(new RemoteServiceAssignment(service.serviceName(), adapter.isPresent(),
                        adapter.map(RemoteServiceAdapter::executable).orElse(false),
                        implementationType,
                        adapterRole,
                        isRemoteReferenceImplementation(implementationType),
                        isRemoteExternalImplementation(implementationType),
                        adapter.map(RemoteServiceAdapter::configuration).orElse(Map.of())));
            }
        }
        return List.copyOf(assignments);
    }

    private String remoteAdapterRole(String serviceName, String implementationType, boolean adapterAvailable) {
        if (!adapterAvailable) {
            return "UNBOUND";
        }
        if (isRemoteReferenceImplementation(implementationType)) {
            return "OBJECT_REPOSITORY_REFERENCE";
        }
        if (isRemoteExternalImplementation(implementationType)) {
            return "HTTP_JSON_EXTERNAL";
        }
        return physicalRuntimeCatalog.remoteAdapterFor(serviceName).isPresent()
                ? "CATALOG_REMOTE"
                : "REGISTERED_REMOTE";
    }

    private boolean isRemoteReferenceImplementation(String implementationType) {
        return isObjectRepositoryRemoteAdapter(implementationType);
    }

    private boolean isRemoteExternalImplementation(String implementationType) {
        return "httpJson".equals(implementationType);
    }

    private List<String> validateRemoteServices(List<GeneratedServiceMetadata> metadata,
                                                List<RemoteServiceAssignment> assignments) {
        List<String> errors = new ArrayList<>();
        Set<String> validatedAdapters = new LinkedHashSet<>();
        Map<String, GeneratedServiceMetadata> metadataByName = new LinkedHashMap<>();
        for (GeneratedServiceMetadata service : metadata) {
            metadataByName.put(service.serviceName(), service);
        }
        validateDuplicateNames(physicalRuntimeCatalog.remoteAdapters(),
                PhysicalRuntimeCatalog.RemoteAdapter::serviceName,
                "Remote service ", " physical adapter is declared multiple times.", errors);
        validateRegisteredRemoteAdapterAmbiguity(assignments, errors);
        validateDeclaredRemoteServiceAdapters(assignments, errors, validatedAdapters);
        for (RemoteServiceAssignment assignment : assignments) {
            if (!assignment.adapterAvailable()) {
                errors.add("Remote service " + assignment.serviceName() + " has no registered adapter.");
            } else if (!assignment.adapterExecutable()) {
                errors.add("Remote service " + assignment.serviceName()
                        + " has registered adapter " + assignment.adapterImplementationType()
                        + " but the adapter is not executable.");
            } else {
                remoteServiceAdapterFor(assignment.serviceName())
                        .ifPresent(adapter -> {
                            String validationKey = assignment.serviceName() + ":" + adapter.implementationType();
                            if (validatedAdapters.add(validationKey)) {
                                errors.addAll(adapter.validationErrors(assignment.serviceName()));
                            }
                            GeneratedServiceMetadata service = metadataByName.get(assignment.serviceName());
                            if (service != null) {
                                validateRemoteServiceAdapterShape(service, adapter, errors);
                            }
                        });
            }
        }
        return List.copyOf(errors);
    }

    private void validateRemoteServiceAdapterShape(GeneratedServiceMetadata service,
                                                   RemoteServiceAdapter adapter,
                                                   List<String> errors) {
        if (!isObjectRepositoryRemoteAdapter(adapter.implementationType())) {
            return;
        }
        Optional<Method> method = remoteBusinessMethod(service);
        if (method.isEmpty()) {
            return;
        }
        validateObjectRepositoryRemoteRequestShape(service, adapter, method.orElseThrow(), errors);
        validateObjectRepositoryRemoteReturnShape(service, adapter, method.orElseThrow(), errors);
        validateObjectRepositoryRemoteRepositoryPaths(service, adapter, method.orElseThrow(), errors);
    }

    private void validateObjectRepositoryRemoteRequestShape(GeneratedServiceMetadata service,
                                                            RemoteServiceAdapter adapter,
                                                            Method method,
                                                            List<String> errors) {
        List<String> objectIdPaths = configuredRemoteObjectIdPaths(adapter.configuration());
        if (objectIdPaths.isEmpty()) {
            return;
        }
        if (method.getParameterCount() != 1) {
            errors.add("Remote service " + service.serviceName()
                    + " objectRepositoryRemote adapter requires exactly one request parameter, but "
                    + method.getName() + " declares " + method.getParameterCount() + ".");
            return;
        }
        Class<?> requestType = method.getParameterTypes()[0];
        for (String objectIdPath : objectIdPaths) {
            if (!hasReadablePath(requestType, objectIdPath)) {
                errors.add("Remote service " + service.serviceName()
                        + " objectRepositoryRemote adapter object id path "
                        + requestType.getSimpleName() + "." + objectIdPath
                        + " is not readable.");
            }
        }
    }

    private void validateObjectRepositoryRemoteReturnShape(GeneratedServiceMetadata service,
                                                           RemoteServiceAdapter adapter,
                                                           Method method,
                                                           List<String> errors) {
        int objectIdPathCount = configuredRemoteObjectIdPaths(adapter.configuration()).size();
        if (objectIdPathCount <= 1) {
            return;
        }
        Class<?> returnType = method.getReturnType();
        if (!returnType.isArray() && !List.class.isAssignableFrom(returnType)) {
            errors.add("Remote service " + service.serviceName()
                    + " objectRepositoryRemote adapter config objectIdPaths"
                    + " requires the remote method to return List or array, but "
                    + method.getName() + " returns " + returnType.getName() + ".");
        }
    }

    private void validateObjectRepositoryRemoteRepositoryPaths(GeneratedServiceMetadata service,
                                                               RemoteServiceAdapter adapter,
                                                               Method method,
                                                               List<String> errors) {
        List<String> repositoryObjectIdPaths =
                configuredPathList(adapter.configuration().get("repositoryObjectIdPaths"));
        if (repositoryObjectIdPaths.isEmpty()) {
            return;
        }
        Class<?> elementType = remoteCollectionElementType(method);
        if (elementType == null) {
            return;
        }
        for (String repositoryObjectIdPath : repositoryObjectIdPaths) {
            if (!hasReadablePath(elementType, repositoryObjectIdPath)) {
                errors.add("Remote service " + service.serviceName()
                        + " objectRepositoryRemote adapter repository object id path "
                        + elementType.getSimpleName() + "." + repositoryObjectIdPath
                        + " is not readable.");
            }
        }
    }

    private Class<?> remoteCollectionElementType(Method method) {
        Class<?> returnType = method.getReturnType();
        if (returnType.isArray()) {
            return returnType.getComponentType();
        }
        if (!List.class.isAssignableFrom(returnType)) {
            return null;
        }
        Type genericReturnType = method.getGenericReturnType();
        if (genericReturnType instanceof ParameterizedType parameterizedType) {
            Type elementType = parameterizedType.getActualTypeArguments()[0];
            if (elementType instanceof Class<?> elementClass) {
                return elementClass;
            }
        }
        return null;
    }

    private List<String> configuredRemoteObjectIdPaths(Map<String, String> configuration) {
        List<String> objectIdPaths = configuredPathList(configuration.get("objectIdPaths"));
        if (!objectIdPaths.isEmpty()) {
            return objectIdPaths;
        }
        String objectIdPath = configuration.get("objectIdPath");
        if (objectIdPath == null || objectIdPath.isBlank()) {
            return List.of();
        }
        return List.of(objectIdPath.trim());
    }

    private List<String> configuredPathList(String value) {
        if (value == null || value.isBlank()) {
            return List.of();
        }
        List<String> values = new ArrayList<>();
        for (String item : value.split(",")) {
            String trimmed = item.trim();
            if (!trimmed.isEmpty()) {
                values.add(trimmed);
            }
        }
        return List.copyOf(values);
    }

    private Optional<Method> remoteBusinessMethod(GeneratedServiceMetadata service) {
        try {
            Class<?> serviceClass = Class.forName(service.serviceClassName());
            List<Method> methods = new ArrayList<>();
            for (Method method : serviceClass.getMethods()) {
                if (isRemoteBusinessMethod(method)) {
                    methods.add(method);
                }
            }
            return methods.size() == 1 ? Optional.of(methods.get(0)) : Optional.empty();
        } catch (ClassNotFoundException e) {
            return Optional.empty();
        }
    }

    private boolean isRemoteBusinessMethod(Method method) {
        if (method.isSynthetic() || method.isBridge()
                || method.getDeclaringClass() == Object.class
                || method.getParameterCount() == 0) {
            return false;
        }
        String name = method.getName();
        return !Set.of("execute", "getName", "startTransaction", "endTransaction",
                "getDelegateService", "getRemoteServiceNames",
                "getRemoteCompensationServiceNames", "getRemoteCompensationMaxAttempts",
                "getRemoteCompensationBackoffMillis",
                "isRemoteCompensationManualInterventionRequired").contains(name);
    }

    private void validateRegisteredRemoteAdapterAmbiguity(List<RemoteServiceAssignment> assignments,
                                                          List<String> errors) {
        for (RemoteServiceAssignment assignment : assignments) {
            List<String> matchingAdapters = new ArrayList<>();
            for (RemoteServiceAdapter adapter : remoteServiceAdapters) {
                if (adapter.supportsService(assignment.serviceName())) {
                    matchingAdapters.add(adapter.implementationType());
                }
            }
            if (matchingAdapters.size() > 1) {
                errors.add("Remote service " + assignment.serviceName()
                        + " has multiple registered adapters: " + String.join(", ", matchingAdapters) + ".");
            }
        }
    }

    private void validateDeclaredRemoteServiceAdapters(List<RemoteServiceAssignment> assignments, List<String> errors,
                                                       Set<String> validatedAdapters) {
        Set<String> assignedRemoteServices = new LinkedHashSet<>();
        for (RemoteServiceAssignment assignment : assignments) {
            assignedRemoteServices.add(assignment.serviceName());
        }
        for (PhysicalRuntimeCatalog.RemoteAdapter declared : physicalRuntimeCatalog.remoteAdapters()) {
            validateRemoteCompensationPolicyConfig(declared, errors);
            validateObjectRepositoryRemoteRepositoryReference(declared, errors);
            if (!assignedRemoteServices.contains(declared.serviceName())) {
                errors.add("Remote service " + declared.serviceName()
                        + " declares a physical adapter but is not registered as a generated remote service.");
            }
            remoteServiceAdapterFor(declared.serviceName())
                    .filter(RemoteServiceAdapter::executable)
                    .ifPresent(adapter -> {
                        String validationKey = declared.serviceName() + ":" + adapter.implementationType();
                        if (validatedAdapters.add(validationKey)) {
                            errors.addAll(adapter.validationErrors(declared.serviceName()));
                        }
                    });
        }
    }

    private void validateObjectRepositoryRemoteRepositoryReference(PhysicalRuntimeCatalog.RemoteAdapter declared,
                                                                  List<String> errors) {
        if (!isObjectRepositoryRemoteAdapter(declared.adapterName())) {
            return;
        }
        String repositoryName = declared.configuration().get("repository");
        if (repositoryName == null) {
            return;
        }
        if (repositoryName.isBlank()) {
            errors.add("Remote service " + declared.serviceName()
                    + " objectRepositoryRemote adapter config repository must not be blank.");
            return;
        }
        if (physicalRuntimeCatalog.repositoryAdapter(repositoryName).isEmpty()) {
            errors.add("Remote service " + declared.serviceName()
                    + " objectRepositoryRemote adapter config repository references undefined repository "
                    + repositoryName + ".");
        }
    }

    private Optional<RemoteServiceAdapter> remoteServiceAdapterFor(String serviceName) {
        Optional<RemoteServiceAdapter> registered = remoteServiceAdapters.stream()
                .filter(adapter -> adapter.supportsService(serviceName))
                .findFirst();
        if (registered.isPresent()) {
            return registered;
        }
        return physicalRuntimeCatalog.remoteAdapterFor(serviceName)
                .map(this::createCatalogRemoteServiceAdapter);
    }

    private RemoteServiceAdapter createCatalogRemoteServiceAdapter(PhysicalRuntimeCatalog.RemoteAdapter adapter) {
        if ("httpJson".equals(adapter.adapterName())) {
            return new HttpJsonRemoteServiceAdapter(adapter);
        }
        if (isObjectRepositoryRemoteAdapter(adapter.adapterName())) {
            return new ObjectRepositoryRemoteServiceAdapter(adapter, this::getRepository);
        }
        return new CatalogRemoteServiceAdapter(adapter);
    }

    private boolean isObjectRepositoryRemoteAdapter(String adapterName) {
        return "objectRepositoryRemote".equals(adapterName)
                || "object-repository-remote".equals(adapterName);
    }

    private Service decorateRuntimeService(Service service) {
        Service decorated = decoratePhysicalBackendParticipant(service);
        return RemoteServiceProxy.decorate(decorated, this::remoteServiceAdapterFor,
                this::remoteCompensationPolicyFor);
    }

    private Optional<RemoteCompensationPolicyProvider> remoteCompensationPolicyFor(String serviceName) {
        return physicalRuntimeCatalog.remoteAdapterFor(serviceName)
                .flatMap(this::remoteCompensationPolicyFrom);
    }

    private Optional<RemoteCompensationPolicyProvider> remoteCompensationPolicyFrom(
            PhysicalRuntimeCatalog.RemoteAdapter adapter) {
        Map<String, String> config = adapter.configuration();
        String maxAttempts = config.get("compensationMaxAttempts");
        String backoffMillis = config.get("compensationBackoffMillis");
        String manual = config.get("compensationManualInterventionRequired");
        if (isBlank(maxAttempts) && isBlank(backoffMillis) && isBlank(manual)) {
            return Optional.empty();
        }
        int parsedMaxAttempts = parsePositiveInt(maxAttempts, 1);
        long parsedBackoffMillis = parseNonNegativeLong(backoffMillis, 0L);
        boolean parsedManual = parseRemoteCompensationManual(adapter.serviceName(), manual, false);
        return Optional.of(new RemoteCompensationPolicyProvider() {
            @Override
            public int getRemoteCompensationMaxAttempts() {
                return parsedMaxAttempts;
            }

            @Override
            public long getRemoteCompensationBackoffMillis() {
                return parsedBackoffMillis;
            }

            @Override
            public boolean isRemoteCompensationManualInterventionRequired() {
                return parsedManual;
            }
        });
    }

    private List<String> validateObjectSnapshotRules(List<GeneratedServiceMetadata> metadata) {
        List<String> errors = new ArrayList<>();
        for (GeneratedServiceMetadata service : metadata) {
            if (service.objectSnapshotRules().isEmpty()) {
                continue;
            }
            if (service.remote()) {
                errors.add("Object snapshot service " + service.serviceName()
                        + " cannot be a remote generated service.");
            }
            if (!service.scopeLocal()) {
                errors.add("Object snapshot service " + service.serviceName()
                        + " must be declared in local APP scope.");
            }
            if (service.transactionMode() == null) {
                errors.add("Object snapshot service " + service.serviceName()
                        + " must declare a transaction mode.");
            } else if (service.transactionMode() == TransactionMode.SAGA) {
                errors.add("Object snapshot service " + service.serviceName()
                        + " cannot declare SAGA transaction mode; snapshot rules must be on local atomic transaction services.");
            }
            if (hasKnownServiceKind(service)
                    && service.serviceKind() != GeneratedServiceKind.ATOMIC_UPDATE) {
                errors.add("Object snapshot service " + service.serviceName()
                        + " must be an atomic update service.");
            }
            validateObjectSnapshotPhysicalBindings(service, errors);
            validateObjectSnapshotAppDdlObjectTypes(service, errors);
            validateObjectSnapshotArgumentPaths(service, errors);
        }
        return List.copyOf(errors);
    }

    private void validateObjectSnapshotPhysicalBindings(GeneratedServiceMetadata service, List<String> errors) {
        Set<String> repositoryNames = physicalRuntimeCatalog.repositoryAdapters().stream()
                .map(PhysicalRuntimeCatalog.RepositoryAdapter::repositoryName)
                .collect(Collectors.toCollection(LinkedHashSet::new));
        for (ObjectSnapshotRule rule : service.objectSnapshotRules()) {
            if (rule.repositoryName() == null || rule.repositoryName().isBlank()) {
                if (repositoryNames.size() > 1 && physicalRuntimeCatalog.defaultRepositoryAdapter().isEmpty()) {
                    errors.add("Object snapshot service " + service.serviceName()
                            + " rule for object type " + rule.objectType()
                            + " must declare repositoryName when no unique default repository adapter exists.");
                }
                continue;
            }
            if (!repositoryNames.contains(rule.repositoryName())) {
                errors.add("Object snapshot service " + service.serviceName()
                        + " rule for object type " + rule.objectType()
                        + " references undefined repository adapter " + rule.repositoryName() + ".");
            }
        }
    }

    private void validateObjectSnapshotAppDdlObjectTypes(GeneratedServiceMetadata service, List<String> errors) {
        for (ObjectSnapshotRule rule : service.objectSnapshotRules()) {
            Optional<PhysicalRuntimeCatalog.RepositoryAdapter> adapter = snapshotRepositoryAdapter(rule);
            if (adapter.isEmpty() || !isJdbcObjectRepositoryAdapter(adapter.get().adapterName())
                    || !isAppDdlTablesEnabled(adapter.get())) {
                continue;
            }
            if (rule.source() == ObjectSnapshotRule.Source.TRANSACTION) {
                continue;
            }
            if (appDdlCatalog.tableForBusinessType(rule.objectType()).isEmpty()) {
                errors.add("Object snapshot service " + service.serviceName()
                        + " rule for object type " + rule.objectType()
                        + " uses repository " + adapter.get().repositoryName()
                        + " with appDdlTables but no APP DDL table exists for that business type.");
            }
        }
    }

    private List<String> validateSagaTransactionCallSnapshots(List<GeneratedServiceMetadata> metadata) {
        Map<String, GeneratedServiceMetadata> servicesByName = new LinkedHashMap<>();
        for (GeneratedServiceMetadata service : metadata) {
            servicesByName.put(service.serviceName(), service);
        }
        List<String> errors = new ArrayList<>();
        for (GeneratedServiceMetadata saga : metadata) {
            if (saga.sagaTransactionCallServiceNames().isEmpty()) {
                continue;
            }
            if (saga.transactionMode() != TransactionMode.SAGA) {
                errors.add("Saga transaction call provider " + saga.serviceName()
                        + " must declare SAGA transaction mode.");
            }
            if (hasKnownServiceKind(saga) && saga.serviceKind() != GeneratedServiceKind.SCENARIO) {
                errors.add("Saga transaction call provider " + saga.serviceName()
                        + " must be a scenario service.");
            }
            for (String targetName : saga.sagaTransactionCallServiceNames()) {
                GeneratedServiceMetadata target = servicesByName.get(targetName);
                if (target == null) {
                    errors.add("Saga service " + saga.serviceName()
                            + " transaction block call " + targetName
                            + " is not registered as a generated service.");
                    continue;
                }
                validateSagaTransactionCallTarget(saga, target, errors);
            }
        }
        return List.copyOf(errors);
    }

    private void validateSagaTransactionCallTarget(GeneratedServiceMetadata saga,
                                                   GeneratedServiceMetadata target,
                                                   List<String> errors) {
        if (target.remote()) {
            errors.add("Saga service " + saga.serviceName()
                    + " transaction block can only call local atomic update transaction services, but calls remote service "
                    + target.serviceName() + ".");
        }
        if (!target.scopeLocal()) {
            errors.add("Saga service " + saga.serviceName()
                    + " transaction block call " + target.serviceName()
                    + " must be declared in local APP scope.");
        }
        if (target.transactionMode() == null) {
            errors.add("Saga service " + saga.serviceName()
                    + " transaction block call " + target.serviceName()
                    + " must declare a local transaction mode or resource.");
        } else if (target.transactionMode() == TransactionMode.SAGA) {
            errors.add("Saga service " + saga.serviceName()
                    + " transaction block call " + target.serviceName()
                    + " cannot call another SAGA service.");
        }
        if (hasKnownServiceKind(target) && target.serviceKind() != GeneratedServiceKind.ATOMIC_UPDATE) {
            errors.add("Saga service " + saga.serviceName()
                    + " transaction block can only call local atomic update transaction services, but calls "
                    + target.serviceName() + ".");
        }
        if (target.transactionMode() != TransactionMode.QUANTUM && !hasArgumentSnapshot(target)) {
            errors.add("Saga service " + saga.serviceName()
                    + " transaction block call " + target.serviceName()
                    + " must declare argument object snapshot rules for recovery evidence.");
        }
    }

    private void validateRemoteCompensationPolicyConfig(PhysicalRuntimeCatalog.RemoteAdapter adapter,
                                                        List<String> errors) {
        Map<String, String> config = adapter.configuration();
        validatePositiveInteger(config, "compensationMaxAttempts", errors,
                "Remote service " + adapter.serviceName()
                        + " compensationMaxAttempts must be a positive integer.");
        validateNonNegativeInteger(config, "compensationBackoffMillis", errors,
                "Remote service " + adapter.serviceName()
                        + " compensationBackoffMillis must be a non-negative integer.");
        String manual = config.get("compensationManualInterventionRequired");
        if (config.containsKey("compensationManualInterventionRequired")
                && (isBlank(manual) || !Set.of("true", "false").contains(manual.trim()))) {
            errors.add("Remote service " + adapter.serviceName()
                    + " compensationManualInterventionRequired must be true or false.");
        }
    }

    private void validatePositiveInteger(Map<String, String> config, String key, List<String> errors, String message) {
        if (!config.containsKey(key)) {
            return;
        }
        String value = config.get(key);
        try {
            if (Integer.parseInt(value.trim()) <= 0) {
                errors.add(message);
            }
        } catch (NullPointerException | NumberFormatException e) {
            errors.add(message);
        }
    }

    private void validatePositiveLong(Map<String, String> config, String key, List<String> errors, String message) {
        if (!config.containsKey(key)) {
            return;
        }
        String value = config.get(key);
        try {
            if (Long.parseLong(value.trim()) <= 0) {
                errors.add(message);
            }
        } catch (NullPointerException | NumberFormatException e) {
            errors.add(message);
        }
    }

    private void validateNonNegativeInteger(Map<String, String> config, String key, List<String> errors,
                                            String message) {
        if (!config.containsKey(key)) {
            return;
        }
        String value = config.get(key);
        try {
            if (Long.parseLong(value.trim()) < 0) {
                errors.add(message);
            }
        } catch (NullPointerException | NumberFormatException e) {
            errors.add(message);
        }
    }

    private int parsePositiveInt(String value, int defaultValue) {
        if (isBlank(value)) {
            return defaultValue;
        }
        int parsed = Integer.parseInt(value.trim());
        return parsed <= 0 ? defaultValue : parsed;
    }

    private long parseNonNegativeLong(String value, long defaultValue) {
        if (isBlank(value)) {
            return defaultValue;
        }
        try {
            long parsed = Long.parseLong(value.trim());
            return parsed < 0 ? defaultValue : parsed;
        } catch (NumberFormatException ex) {
            return defaultValue;
        }
    }

    private String nonNegativeLongValue(String value, String defaultValue) {
        if (isBlank(value)) {
            return defaultValue;
        }
        return String.valueOf(parseNonNegativeLong(value, 0L));
    }

    private long parsePositiveLong(String value, long defaultValue) {
        if (isBlank(value)) {
            return defaultValue;
        }
        try {
            long parsed = Long.parseLong(value.trim());
            return parsed <= 0 ? defaultValue : parsed;
        } catch (NumberFormatException ex) {
            return defaultValue;
        }
    }

    private boolean parseBoolean(String value, boolean defaultValue) {
        return isBlank(value) ? defaultValue : Boolean.parseBoolean(value.trim());
    }

    private boolean parseRemoteCompensationManual(String serviceName, String value, boolean defaultValue) {
        if (isBlank(value)) {
            return defaultValue;
        }
        String normalized = value.trim();
        if ("true".equals(normalized)) {
            return true;
        }
        if ("false".equals(normalized)) {
            return false;
        }
        throw new IllegalStateException("Remote service " + serviceName
                + " compensationManualInterventionRequired must be true or false, but was " + value + ".");
    }

    private boolean isBlank(String value) {
        return value == null || value.isBlank();
    }

    private String valueOrDash(String value) {
        return isBlank(value) ? "-" : value;
    }

    private boolean appDdlPlatformPrimaryKeyClosedIdentity(String identityKind) {
        return "ROLE_PERFORMER_IDENTITY".equals(identityKind)
                || "COMPOSITION_IDENTITY".equals(identityKind)
                || "BUSINESS_FIELD_IDENTITY".equals(identityKind);
    }

    private String joinNonBlank(List<String> values, String delimiter) {
        if (values == null || values.isEmpty()) {
            return "-";
        }
        String joined = values.stream()
                .filter(value -> value != null && !value.isBlank())
                .collect(Collectors.joining(delimiter == null ? "," : delimiter));
        return joined.isBlank() ? "-" : joined;
    }

    private void validateObjectSnapshotArgumentPaths(GeneratedServiceMetadata service, List<String> errors) {
        Class<?> serviceClass = serviceClass(service, errors, "Object snapshot service ");
        if (serviceClass == null) {
            return;
        }
        Method serviceMethod = findMethod(serviceClass, service.serviceName());
        if (serviceMethod == null) {
            return;
        }
        for (ObjectSnapshotRule rule : service.objectSnapshotRules()) {
            if (rule.source() != ObjectSnapshotRule.Source.ARGUMENT) {
                continue;
            }
            validateObjectSnapshotArgumentPath(service, rule, serviceMethod, errors);
        }
    }

    private void validateObjectSnapshotArgumentPath(GeneratedServiceMetadata service, ObjectSnapshotRule rule,
                                                    Method serviceMethod, List<String> errors) {
        if (rule.argumentIndex() < 0 || rule.argumentIndex() >= serviceMethod.getParameterCount()) {
            errors.add("Object snapshot service " + service.serviceName()
                    + " method " + serviceMethod.getName()
                    + " argument index " + rule.argumentIndex() + " is outside parameter list.");
            return;
        }
        Class<?> argumentType = serviceMethod.getParameterTypes()[rule.argumentIndex()];
        for (String objectIdPath : rule.objectIdPaths()) {
            if (!hasReadablePath(argumentType, objectIdPath)
                    && !isRoleParticipantSnapshotPath(rule, argumentType, objectIdPath)) {
                errors.add("Object snapshot service " + service.serviceName()
                        + " method " + serviceMethod.getName()
                        + " object id path " + argumentType.getSimpleName() + "." + objectIdPath
                        + " is not readable.");
            }
        }
    }

    private boolean isRoleParticipantSnapshotPath(ObjectSnapshotRule rule, Class<?> argumentType, String objectIdPath) {
        if (rule == null || argumentType == null || objectIdPath == null || objectIdPath.isBlank()) {
            return false;
        }
        if (!rule.objectType().equals(argumentType.getSimpleName())) {
            return false;
        }
        return roleParticipantPlans(rule.objectType()).stream()
                .filter(RoleParticipantPlan::performerKeyComplete)
                .filter(plan -> plan.roleSourceKeyPaths().contains(objectIdPath)
                        || plan.compatRoleKeyPaths().contains(objectIdPath)
                        || plan.platformColumns().contains(objectIdPath)
                        || roleParticipantRuntimeIdentityPaths(plan).contains(leafPath(objectIdPath)))
                .findAny()
                .isPresent();
    }

    private List<String> validateTccReservationRules(List<GeneratedServiceMetadata> metadata) {
        List<String> errors = new ArrayList<>();
        for (GeneratedServiceMetadata service : metadata) {
            for (TccReservationRule rule : service.tccReservationRules()) {
                validateTccReservationSource(service, rule, errors);
                validateTccReservationTarget(service, rule, errors);
            }
        }
        return List.copyOf(errors);
    }

    private void validateTccReservationSource(GeneratedServiceMetadata service, TccReservationRule rule,
                                              List<String> errors) {
        String source = rule.sourceAttributeId();
        if (source == null || source.isBlank() || quantumStoreNameForAttribute(source).isBlank()) {
            errors.add("TCC reservation source attribute " + source + " on service " + service.serviceName()
                    + " must be assigned to a PHY quantumStore before it can reserve platform column "
                    + rule.reservationAttributeId() + ".");
        }
    }

    private void validateTccReservationTarget(GeneratedServiceMetadata service, TccReservationRule rule,
                                              List<String> errors) {
        String target = rule.reservationAttributeId();
        String objectType = objectType(target);
        String objectPath = objectPath(target);
        Optional<AppDdlCatalog.Table> maybeTable = appDdlCatalog.tableForBusinessType(objectType);
        if (objectType.isBlank() || objectPath.isBlank() || maybeTable.isEmpty()) {
            errors.add("TCC reservation target attribute " + target + " on service " + service.serviceName()
                    + " must be declared as an APP DDL platform column, not a .spp business field.");
            return;
        }
        AppDdlCatalog.Table table = maybeTable.orElseThrow();
        Optional<String> columnName = columnForPath(table, objectPath);
        Optional<AppDdlCatalog.Column> column = columnName.flatMap(name -> table.columns().stream()
                .filter(item -> item.name().equals(name))
                .findFirst());
        if (column.isEmpty()) {
            errors.add("TCC reservation target attribute " + target + " on service " + service.serviceName()
                    + " must be declared as an APP DDL platform column, not a .spp business field.");
            return;
        }
        if (isPrimaryKeyPath(table, target)) {
            errors.add("TCC reservation target attribute " + target + " on service " + service.serviceName()
                    + " must not be an APP DDL primary key column.");
        }
        if (column.orElseThrow().objectBacked()) {
            errors.add("TCC reservation target attribute " + target + " on service " + service.serviceName()
                    + " must be an APP DDL platform column, but column " + column.orElseThrow().name()
                    + " is object-backed.");
        }
    }

    private boolean isPrimaryKeyPath(AppDdlCatalog.Table table, String path) {
        String normalizedPath = canonicalRepositoryPath(normalizeRepositoryPath(path, table.businessType()));
        for (String primaryKey : table.primaryKeys()) {
            if (normalizedPath.equals(canonicalRepositoryPath(normalizeRepositoryPath(primaryKey,
                    table.businessType())))) {
                return true;
            }
        }
        return false;
    }

    private String objectType(String attributeId) {
        int separator = attributeId == null ? -1 : attributeId.indexOf('.');
        return separator <= 0 ? "" : attributeId.substring(0, separator);
    }

    private String objectPath(String attributeId) {
        int separator = attributeId == null ? -1 : attributeId.indexOf('.');
        return separator < 0 || separator == attributeId.length() - 1 ? "" : attributeId.substring(separator + 1);
    }

    private List<String> validateTccLifecycleRules(List<GeneratedServiceMetadata> metadata) {
        Map<String, GeneratedServiceMetadata> servicesByName = new LinkedHashMap<>();
        for (GeneratedServiceMetadata service : metadata) {
            servicesByName.put(service.serviceName(), service);
        }
        List<String> errors = new ArrayList<>();
        for (GeneratedServiceMetadata service : metadata) {
            if (service.tccConfirmServiceName() == null && service.tccCancelServiceName() == null) {
                continue;
            }
            validateTccLifecycleSource(service, errors);
            validateTccLifecycleTarget(service, service.tccConfirmServiceName(), "confirm", servicesByName, errors);
            validateTccLifecycleTarget(service, service.tccCancelServiceName(), "cancel", servicesByName, errors);
            if (Objects.equals(service.tccConfirmServiceName(), service.tccCancelServiceName())) {
                errors.add("TCC lifecycle service " + service.serviceName()
                        + " must declare different confirm and cancel services.");
            }
        }
        return List.copyOf(errors);
    }

    private void validateTccLifecycleSource(GeneratedServiceMetadata service, List<String> errors) {
        if (service.remote()) {
            errors.add("TCC lifecycle service " + service.serviceName()
                    + " cannot be a remote generated service.");
        }
        if (!service.scopeLocal()) {
            errors.add("TCC lifecycle service " + service.serviceName()
                    + " must be declared in local APP scope.");
        }
        if (service.transactionMode() != TransactionMode.TCC) {
            errors.add("TCC lifecycle service " + service.serviceName()
                    + " must declare TCC transaction mode.");
        }
        if (hasKnownServiceKind(service)
                && service.serviceKind() != GeneratedServiceKind.ATOMIC_UPDATE) {
            errors.add("TCC lifecycle service " + service.serviceName()
                    + " must be an atomic update service.");
        }
        if (!hasArgumentSnapshot(service)) {
            errors.add("TCC try service " + service.serviceName()
                    + " must declare argument object snapshot rules for recovery evidence.");
        }
    }

    private void validateTccLifecycleTarget(GeneratedServiceMetadata source, String targetServiceName, String role,
                                            Map<String, GeneratedServiceMetadata> servicesByName,
                                            List<String> errors) {
        if (targetServiceName == null || targetServiceName.isBlank()) {
            errors.add("TCC " + role + " service referenced by " + source.serviceName()
                    + " must be declared.");
            return;
        }
        GeneratedServiceMetadata target = servicesByName.get(targetServiceName);
        if (target == null) {
            errors.add("TCC " + role + " service " + targetServiceName
                    + " referenced by " + source.serviceName()
                    + " is not registered as a generated service.");
            return;
        }
        if (Objects.equals(source.serviceName(), target.serviceName())) {
            errors.add("TCC " + role + " service " + targetServiceName
                    + " cannot be the same as " + source.serviceName() + ".");
        }
        if (target.remote()) {
            errors.add("TCC " + role + " service " + targetServiceName
                    + " referenced by " + source.serviceName()
                    + " cannot be a remote generated service.");
        }
        if (!target.scopeLocal()) {
            errors.add("TCC " + role + " service " + targetServiceName
                    + " referenced by " + source.serviceName()
                    + " must be declared in local APP scope.");
        }
        if (target.transactionMode() != TransactionMode.TCC) {
            errors.add("TCC " + role + " service " + targetServiceName
                    + " referenced by " + source.serviceName()
                    + " must declare TCC transaction mode.");
        }
        if (hasKnownServiceKind(target)
                && target.serviceKind() != GeneratedServiceKind.ATOMIC_UPDATE) {
            errors.add("TCC " + role + " service " + targetServiceName
                    + " referenced by " + source.serviceName()
                    + " must be an atomic update service.");
        }
        if (!Objects.equals(source.transactionResourceId(), target.transactionResourceId())) {
            errors.add("TCC " + role + " service " + targetServiceName
                    + " referenced by " + source.serviceName()
                    + " must use the same TCC resource " + source.transactionResourceId() + ".");
        }
        if (target.tccConfirmServiceName() != null || target.tccCancelServiceName() != null) {
            errors.add("TCC " + role + " service " + targetServiceName
                    + " referenced by " + source.serviceName()
                    + " cannot declare nested TCC lifecycle services.");
        }
        validateMatchingServiceParameters(source, target,
                "TCC " + role + " service " + target.serviceName(), source.serviceName(), errors);
        if (!hasArgumentSnapshot(target)) {
            errors.add("TCC " + role + " service " + targetServiceName
                    + " referenced by " + source.serviceName()
                    + " must declare argument object snapshot rules for recovery evidence.");
            return;
        }
        validateMatchingTccLifecycleSnapshots(source, target, role, errors);
    }

    private void validateMatchingTccLifecycleSnapshots(GeneratedServiceMetadata source, GeneratedServiceMetadata target,
                                                       String role, List<String> errors) {
        Set<String> targetRules = new LinkedHashSet<>();
        for (ObjectSnapshotRule rule : target.objectSnapshotRules()) {
            if (rule.source() == ObjectSnapshotRule.Source.ARGUMENT) {
                targetRules.add(argumentSnapshotRuleKey(rule));
            }
        }
        for (ObjectSnapshotRule sourceRule : source.objectSnapshotRules()) {
            if (sourceRule.source() != ObjectSnapshotRule.Source.ARGUMENT) {
                continue;
            }
            if (!targetRules.contains(argumentSnapshotRuleKey(sourceRule))) {
                errors.add("TCC " + role + " service " + target.serviceName()
                        + " referenced by " + source.serviceName()
                        + " must declare matching argument object snapshot rule "
                        + objectSnapshotRuleName(sourceRule) + ".");
            }
        }
    }

    private boolean hasArgumentSnapshot(GeneratedServiceMetadata service) {
        return service.objectSnapshotRules().stream()
                .anyMatch(rule -> rule.source() == ObjectSnapshotRule.Source.ARGUMENT);
    }

    private boolean hasAfterExecutionArgumentSnapshot(GeneratedServiceMetadata service) {
        return service.objectSnapshotRules().stream()
                .anyMatch(rule -> rule.source() == ObjectSnapshotRule.Source.ARGUMENT
                        && snapshotSavesAfterExecution(rule.timing()));
    }

    private boolean snapshotSavesAfterExecution(ObjectSnapshotRule.Timing timing) {
        return timing == ObjectSnapshotRule.Timing.AFTER
                || timing == ObjectSnapshotRule.Timing.AFTER_COMMIT;
    }

    private String argumentSnapshotRuleKey(ObjectSnapshotRule rule) {
        return rule.argumentIndex() + ":" + rule.objectType() + ":" + String.join(",", rule.objectIdPaths());
    }

    private String objectSnapshotRuleName(ObjectSnapshotRule rule) {
        if (rule.objectIdPaths().size() == 1) {
            return rule.objectType() + "." + rule.objectIdPath();
        }
        return rule.objectType() + ".(" + String.join(", ", rule.objectIdPaths()) + ")";
    }

    private List<String> validateRepositoryHydrationRules(List<GeneratedServiceMetadata> metadata) {
        List<String> errors = new ArrayList<>();
        for (GeneratedServiceMetadata service : metadata) {
            if (service.repositoryHydrationRules().isEmpty()) {
                continue;
            }
            if (service.remote()) {
                errors.add("Repository hydration service " + service.serviceName()
                        + " cannot be a remote generated service.");
            }
            if (!service.scopeLocal()) {
                errors.add("Repository hydration service " + service.serviceName()
                        + " must be declared in local APP scope.");
            }
            if (hasKnownServiceKind(service)
                    && service.serviceKind() != GeneratedServiceKind.ATOMIC_QUERY) {
                errors.add("Repository hydration service " + service.serviceName()
                        + " must be an atomic query service.");
            }
            validateRepositoryHydrationDuplicateResponseTargets(service, errors);
            validateRepositoryHydrationResponseTargets(service, errors);
            validateRepositoryHydrationPhysicalBindings(service, errors);
            validateRepositoryHydrationAppDdlObjectTypes(service, errors);
        }
        return List.copyOf(errors);
    }

    private void validateRepositoryHydrationAppDdlObjectTypes(GeneratedServiceMetadata service, List<String> errors) {
        if (physicalRuntimeCatalog.repositoryAdapters().isEmpty()) {
            return;
        }
        for (HydrationRule rule : service.repositoryHydrationRules()) {
            Optional<PhysicalRuntimeCatalog.RepositoryAdapter> adapter = repositoryAdapterFor(rule);
            if (adapter.isEmpty() || !isJdbcObjectRepositoryAdapter(adapter.get().adapterName())
                    || !isAppDdlTablesEnabled(adapter.get())) {
                continue;
            }
            if (appDdlCatalog.tableForBusinessType(rule.objectType()).isEmpty()) {
                errors.add("Repository hydration service " + service.serviceName()
                        + " rule for target " + rule.responseMethodName()
                        + " uses object type " + rule.objectType()
                        + " but repository " + adapter.get().repositoryName()
                        + " enables appDdlTables without an APP DDL table for that business type.");
            }
        }
    }

    private Optional<PhysicalRuntimeCatalog.RepositoryAdapter> repositoryAdapterFor(HydrationRule rule) {
        if (rule.repositoryName() != null && !rule.repositoryName().isBlank()) {
            return physicalRuntimeCatalog.repositoryAdapter(rule.repositoryName());
        }
        return physicalRuntimeCatalog.defaultRepositoryAdapter();
    }

    private void validateRepositoryHydrationPhysicalBindings(GeneratedServiceMetadata service, List<String> errors) {
        if (physicalRuntimeCatalog.repositoryAdapters().isEmpty()) {
            for (HydrationRule rule : service.repositoryHydrationRules()) {
                if (rule.repositoryName() != null && !rule.repositoryName().isBlank()) {
                    errors.add("Repository hydration service " + service.serviceName()
                            + " rule for target " + rule.responseMethodName()
                            + " references undefined repository adapter " + rule.repositoryName() + ".");
                }
            }
            return;
        }
        Set<String> repositoryAdapterNames = new LinkedHashSet<>();
        for (PhysicalRuntimeCatalog.RepositoryAdapter adapter : physicalRuntimeCatalog.repositoryAdapters()) {
            repositoryAdapterNames.add(adapter.repositoryName());
        }
        for (HydrationRule rule : service.repositoryHydrationRules()) {
            if (rule.repositoryName() == null || rule.repositoryName().isBlank()) {
                if (repositoryAdapterNames.size() > 1 && physicalRuntimeCatalog.defaultRepositoryAdapter().isEmpty()) {
                    errors.add("Repository hydration service " + service.serviceName()
                            + " rule for target " + rule.responseMethodName()
                            + " must declare repositoryName when no unique default repository adapter exists.");
                }
                continue;
            }
            if (!repositoryAdapterNames.contains(rule.repositoryName())) {
                errors.add("Repository hydration service " + service.serviceName()
                        + " rule for target " + rule.responseMethodName()
                        + " references undefined repository adapter " + rule.repositoryName() + ".");
            }
        }
    }

    private void validateRepositoryHydrationDuplicateResponseTargets(GeneratedServiceMetadata service,
                                                                     List<String> errors) {
        Set<String> responseTargets = new LinkedHashSet<>();
        Set<String> duplicateTargets = new LinkedHashSet<>();
        for (HydrationRule rule : service.repositoryHydrationRules()) {
            if (rule.responseMethodName() == null || rule.responseMethodName().isBlank()) {
                continue;
            }
            if (!responseTargets.add(rule.responseMethodName())) {
                duplicateTargets.add(rule.responseMethodName());
            }
        }
        for (String duplicateTarget : duplicateTargets) {
            errors.add("Repository hydration service " + service.serviceName()
                    + " declares duplicate response target " + duplicateTarget + ".");
        }
    }

    private void validateRepositoryHydrationResponseTargets(GeneratedServiceMetadata service, List<String> errors) {
        Class<?> serviceClass = serviceClass(service, errors, "Repository hydration service ");
        if (serviceClass == null) {
            return;
        }
        for (HydrationRule rule : service.repositoryHydrationRules()) {
            Method serviceMethod = findMethod(serviceClass, rule.methodName());
            if (serviceMethod == null) {
                errors.add("Repository hydration service " + service.serviceName()
                        + " must declare method " + rule.methodName() + ".");
                continue;
            }
            validateRepositoryHydrationArgumentPath(service, rule, serviceMethod, errors);
            if (rule.responseMethodName() == null || rule.responseMethodName().isBlank()) {
                continue;
            }
            Class<?> responseType = serviceMethod.getReturnType();
            if (responseType == Void.TYPE) {
                errors.add("Repository hydration service " + service.serviceName()
                        + " method " + rule.methodName()
                        + " must return a response object for target " + rule.responseMethodName() + ".");
                continue;
            }
            Method responseWriter = findSingleArgumentMethod(responseType, rule.responseMethodName()).orElse(null);
            if (responseWriter == null) {
                errors.add("Repository hydration service " + service.serviceName()
                        + " response type " + responseType.getSimpleName()
                        + " must declare write method " + rule.responseMethodName() + "(...).");
                continue;
            }
            if (!isCollectionWriter(responseWriter)) {
                for (HydrationRule.KeyTarget target : rule.keyTargets()) {
                    if (!rule.objectType().equals(target.objectType())
                            && !isRoleTakePrimaryHydrationRule(rule)) {
                        errors.add("Repository hydration service " + service.serviceName()
                                + " rule for target " + rule.responseMethodName()
                                + " must write a collection when query key " + target.objectType()
                                + "." + target.objectIdPath()
                                + " differs from repository object type " + rule.objectType() + ".");
                    }
                }
            }
        }
    }

    private boolean isRoleTakePrimaryHydrationRule(HydrationRule rule) {
        if (rule == null || rule.keyTargets() == null || rule.keyTargets().isEmpty()) {
            return false;
        }
        return roleParticipantPlans(rule.objectType()).stream()
                .filter(RoleParticipantPlan::complete)
                .anyMatch(plan -> samePaths(plan.platformColumns(),
                        rule.keyTargets().stream()
                                .map(HydrationRule.KeyTarget::repositoryObjectIdPath)
                                .map(this::leafPath)
                                .toList())
                        && samePaths(roleParticipantRuntimeIdentityPaths(plan),
                        rule.keyTargets().stream()
                                .map(HydrationRule.KeyTarget::objectIdPath)
                                .map(this::leafPath)
                                .toList()));
    }

    private void validateRepositoryHydrationArgumentPath(GeneratedServiceMetadata service, HydrationRule rule,
                                                         Method serviceMethod, List<String> errors) {
        for (HydrationRule.KeyTarget target : rule.keyTargets()) {
            if (target.argumentIndex() < 0 || target.argumentIndex() >= serviceMethod.getParameterCount()) {
                errors.add("Repository hydration service " + service.serviceName()
                        + " method " + rule.methodName()
                        + " argument index " + target.argumentIndex() + " is outside parameter list.");
                continue;
            }
            Class<?> argumentType = serviceMethod.getParameterTypes()[target.argumentIndex()];
            if (!hasReadablePath(argumentType, target.objectIdPath())
                    && !isRoleParticipantHydrationPath(rule, target, argumentType)) {
                errors.add("Repository hydration service " + service.serviceName()
                        + " method " + rule.methodName()
                        + " object id path " + argumentType.getSimpleName() + "." + target.objectIdPath()
                        + " is not readable.");
            }
        }
    }

    private boolean isRoleParticipantHydrationPath(HydrationRule rule, HydrationRule.KeyTarget target,
                                                   Class<?> argumentType) {
        if (rule == null || target == null || argumentType == null) {
            return false;
        }
        String argumentTypeName = argumentType.getSimpleName();
        if (target.objectType().equals(argumentTypeName)) {
            return roleParticipantPlans(target.objectType()).stream()
                    .filter(RoleParticipantPlan::performerKeyComplete)
                    .filter(plan -> plan.roleSourceKeyPaths().contains(target.objectIdPath())
                            || plan.compatRoleKeyPaths().contains(target.objectIdPath())
                            || roleParticipantRuntimeIdentityPaths(plan).contains(leafPath(target.objectIdPath()))
                            || plan.platformColumns().contains(target.repositoryObjectIdPath()))
                    .findAny()
                    .isPresent();
        }
        String performerPath = target.objectType() + "." + target.objectIdPath();
        String rolePath = decapitalize(target.objectType()) + "." + target.objectIdPath();
        return roleParticipantPlans(argumentTypeName).stream()
                .filter(RoleParticipantPlan::performerKeyComplete)
                .filter(plan -> plan.performerTypes().contains(target.objectType()))
                .filter(plan -> plan.performerKeyPaths().contains(performerPath)
                        || plan.roleSourceKeyPaths().contains(rolePath)
                        || plan.compatRoleKeyPaths().contains(rolePath)
                        || plan.platformColumns().contains(target.repositoryObjectIdPath()))
                .findAny()
                .isPresent();
    }

    private static String decapitalize(String value) {
        if (value == null || value.isBlank()) {
            return "";
        }
        return Character.toLowerCase(value.charAt(0)) + value.substring(1);
    }

    private Class<?> serviceClass(GeneratedServiceMetadata service, List<String> errors, String prefix) {
        try {
            return Class.forName(service.serviceClassName());
        } catch (ClassNotFoundException e) {
            errors.add(prefix + service.serviceName()
                    + " class " + service.serviceClassName() + " is not available.");
            return null;
        }
    }

    private Method findMethod(Class<?> type, String methodName) {
        for (Method method : type.getMethods()) {
            if (method.getName().equals(methodName)) {
                return method;
            }
        }
        return null;
    }

    private boolean hasSingleArgumentMethod(Class<?> type, String methodName) {
        return findSingleArgumentMethod(type, methodName).isPresent();
    }

    private Optional<Method> findSingleArgumentMethod(Class<?> type, String methodName) {
        for (Method method : type.getMethods()) {
            if (method.getName().equals(methodName) && method.getParameterCount() == 1) {
                return Optional.of(method);
            }
        }
        return Optional.empty();
    }

    private boolean isCollectionWriter(Method method) {
        Class<?> parameterType = method.getParameterTypes()[0];
        return parameterType.isArray() || List.class.isAssignableFrom(parameterType);
    }

    private boolean hasReadablePath(Class<?> type, String path) {
        if (hasDirectReadablePath(type, path)) {
            return true;
        }
        return hasRolePerformerReadablePath(type, path);
    }

    private boolean hasDirectReadablePath(Class<?> type, String path) {
        if (type == null || path == null || path.isBlank()) {
            return false;
        }
        Class<?> current = type;
        for (String property : path.split("\\.")) {
            current = readablePropertyType(current, property);
            if (current == null) {
                return false;
            }
        }
        return true;
    }

    private boolean hasRolePerformerReadablePath(Class<?> type, String path) {
        if (type == null || path == null || !path.contains(".")) {
            return false;
        }
        String[] segments = path.split("\\.", 2);
        if (segments.length != 2 || segments[0].isBlank() || segments[1].isBlank()) {
            return false;
        }
        String roleType = type.getSimpleName();
        String performerRuntimeName = segments[0];
        String performerPath = segments[1];
        for (RoleParticipantPlan plan : roleParticipantPlans(roleType)) {
            for (String performerType : plan.performerTypes()) {
                if (!performerRuntimeName.equals(runtimeName(performerType))) {
                    continue;
                }
                Class<?> performerClass = resolveGeneratedModelClass(type, performerType);
                if (hasDirectReadablePath(performerClass, performerPath)
                        || plan.compatRoleKeyPaths().contains(path)) {
                    return true;
                }
            }
        }
        return false;
    }

    private Class<?> resolveGeneratedModelClass(Class<?> siblingType, String typeName) {
        if (siblingType == null || typeName == null || typeName.isBlank()) {
            return null;
        }
        try {
            return Class.forName(siblingType.getPackageName() + "." + typeName,
                    false, siblingType.getClassLoader());
        } catch (ClassNotFoundException ignored) {
            return null;
        }
    }

    private Class<?> resolveGeneratedModelClassByName(String typeName) {
        if (typeName == null || typeName.isBlank()) {
            return null;
        }
        LinkedHashSet<String> packageNames = new LinkedHashSet<>();
        for (Service service : registeredGeneratedServices) {
            if (service == null || service.getClass().getPackageName() == null) {
                continue;
            }
            String packageName = service.getClass().getPackageName();
            packageNames.add(packageName);
            if (packageName.endsWith(".service")) {
                packageNames.add(packageName.substring(0, packageName.length() - ".service".length())
                        + ".model");
            }
        }
        for (String packageName : packageNames) {
            try {
                return Class.forName(packageName + "." + typeName, false,
                        Thread.currentThread().getContextClassLoader());
            } catch (ClassNotFoundException ignored) {
                // Try the next generated package candidate.
            }
        }
        return null;
    }

    private Class<?> resolveGeneratedModelClassByName(GeneratedServiceMetadata service, String typeName) {
        if (typeName == null || typeName.isBlank()) {
            return null;
        }
        if (service != null && service.serviceClassName() != null && !service.serviceClassName().isBlank()) {
            String serviceClassName = service.serviceClassName();
            int lastDot = serviceClassName.lastIndexOf('.');
            if (lastDot > 0) {
                String packageName = serviceClassName.substring(0, lastDot);
                Class<?> resolved = resolveGeneratedModelClassInPackage(packageName, typeName);
                if (resolved != null) {
                    return resolved;
                }
                if (packageName.endsWith(".service")) {
                    resolved = resolveGeneratedModelClassInPackage(
                            packageName.substring(0, packageName.length() - ".service".length()) + ".model",
                            typeName);
                    if (resolved != null) {
                        return resolved;
                    }
                }
            }
        }
        return resolveGeneratedModelClassByName(typeName);
    }

    private Class<?> resolveGeneratedModelClassInPackage(String packageName, String typeName) {
        if (packageName == null || packageName.isBlank() || typeName == null || typeName.isBlank()) {
            return null;
        }
        try {
            return Class.forName(packageName + "." + typeName, false,
                    Thread.currentThread().getContextClassLoader());
        } catch (ClassNotFoundException ignored) {
            return null;
        }
    }

    private String runtimeName(String typeName) {
        if (typeName == null || typeName.isBlank()) {
            return "";
        }
        return Character.toLowerCase(typeName.charAt(0)) + typeName.substring(1);
    }

    private Class<?> readablePropertyType(Class<?> type, String property) {
        if (type == null || property == null || property.isBlank()) {
            return null;
        }
        String accessorSuffix = Character.toUpperCase(property.charAt(0)) + property.substring(1);
        for (String methodName : List.of("get" + accessorSuffix, "is" + accessorSuffix, property)) {
            try {
                Method method = type.getMethod(methodName);
                if (method.getParameterCount() == 0) {
                    return method.getReturnType();
                }
            } catch (ReflectiveOperationException ignored) {
                // Try the next JavaBean style before falling back to field access.
            }
        }
        Class<?> current = type;
        while (current != null && current != Object.class) {
            try {
                Field field = current.getDeclaredField(property);
                return field.getType();
            } catch (ReflectiveOperationException ignored) {
                current = current.getSuperclass();
            }
        }
        return null;
    }

    private List<String> validateRepositoryAdapters(List<GeneratedServiceMetadata> metadata) {
        if (physicalRuntimeCatalog.repositoryAdapters().isEmpty()) {
            return List.of();
        }
        List<String> errors = new ArrayList<>();
        validateDuplicateNames(physicalRuntimeCatalog.repositoryAdapters(),
                PhysicalRuntimeCatalog.RepositoryAdapter::repositoryName,
                "Repository ", " is declared multiple times.", errors);
        if (physicalRuntimeCatalog.hasAmbiguousDefaultRepositoryAdapters()) {
            errors.add("Multiple repository adapters declare config default=true.");
        }
        boolean repositoryAccessUsed = metadata.stream()
                .anyMatch(service -> !service.repositoryHydrationRules().isEmpty()
                        || !service.objectSnapshotRules().isEmpty())
                || physicalRuntimeCatalog.remoteAdapters().stream()
                        .anyMatch(adapter -> isObjectRepositoryRemoteAdapter(adapter.adapterName())
                                && adapter.configuration().containsKey("repository"));
        ObjectRepository repository = generatedServiceRuntime.getRepository();
        for (PhysicalRuntimeCatalog.RepositoryAdapter adapter : physicalRuntimeCatalog.repositoryAdapters()) {
            if (!isSupportedRepositoryAdapter(adapter.adapterName())) {
                errors.add("Repository " + adapter.repositoryName()
                        + " declares unsupported adapter " + adapter.adapterName()
                        + "; supported repository adapters are objectSnapshot, objectRepository,"
                        + " jdbcObjectRepository and jdbc-object-repository.");
                continue;
            }
            if (!repositoryAccessUsed) {
                errors.add("Repository " + adapter.repositoryName()
                        + " declares adapter " + adapter.adapterName()
                        + " but no registered generated service uses repository hydration or object snapshots.");
            }
            if ("objectSnapshot".equals(adapter.adapterName())) {
                validateOptionalRepositoryConfig(adapter, errors, "datasourceUrl");
                validateOptionalRepositoryConfig(adapter, errors, "driverClassName");
                validateOptionalRepositoryConfig(adapter, errors, "table");
                validateRepositoryDatasourceDriver(adapter, errors);
            } else if ("objectRepository".equals(adapter.adapterName())) {
                validateOptionalRepositoryConfig(adapter, errors, "implementationClass");
                validateObjectRepositoryImplementationClass(adapter, repository, errors);
            } else if (isJdbcObjectRepositoryAdapter(adapter.adapterName())) {
                validateOptionalRepositoryConfig(adapter, errors, "datasourceUrl");
                validateOptionalRepositoryConfig(adapter, errors, "driverClassName");
                validateOptionalRepositoryConfig(adapter, errors, "table");
                validateBooleanRepositoryConfig(adapter, errors, "appDdlTables");
                validateOptionalRepositoryConfig(adapter, errors, "nativeUpdateExecutor");
                if (hasNonBlank(adapter.configuration(), "nativeUpdateExecutor") && !isAppDdlTablesEnabled(adapter))
                    errors.add("Repository " + adapter.repositoryName() + " nativeUpdateExecutor requires appDdlTables=true.");
                validateOptionalRepositoryConfig(adapter, errors, "transactionRetentionMode");
                validateTransactionRetentionMode(adapter, errors);
                validateOptionalRepositoryConfig(adapter, errors, "transactionRetentionPropertyPrefix");
                validateOptionalRepositoryConfig(adapter, errors, "transactionRetentionMillisByService");
                validateOptionalRepositoryConfig(adapter, errors, "transactionRetentionMillisByResource");
                validateOptionalRepositoryConfig(adapter, errors, "transactionArchiveRetentionMillisByResource");
                validateBooleanRepositoryConfig(adapter, errors, "transactionRetentionEnabledByDefault");
                validatePositiveLong(adapter.configuration(), "transactionRetentionFixedDelayMillis", errors,
                        "Repository " + adapter.repositoryName()
                                + " " + adapter.adapterName()
                                + " adapter config transactionRetentionFixedDelayMillis"
                                + " must be a positive integer.");
                validatePositiveLong(adapter.configuration(), "transactionRetentionMillis", errors,
                        "Repository " + adapter.repositoryName()
                                + " " + adapter.adapterName()
                                + " adapter config transactionRetentionMillis"
                                + " must be a positive integer.");
                validatePositiveLong(adapter.configuration(), "transactionArchiveRetentionMillis", errors,
                        "Repository " + adapter.repositoryName()
                                + " " + adapter.adapterName()
                                + " adapter config transactionArchiveRetentionMillis"
                                + " must be a positive integer.");
                validateNamedRetentionMillis(adapter, errors, "transactionRetentionMillisByService", "serviceName");
                validateNamedRetentionMillis(adapter, errors, "transactionRetentionMillisByResource", "resourceName");
                validateNamedRetentionMillis(adapter, errors,
                        "transactionArchiveRetentionMillisByResource", "resourceName");
                validateRepositoryDatasourceDriver(adapter, errors);
                if (isAppDdlTablesEnabled(adapter) && appDdlCatalog.tables().isEmpty()) {
                    errors.add("Repository " + adapter.repositoryName()
                            + " adapter " + adapter.adapterName()
                            + " config appDdlTables requires a loaded APP DDL catalog.");
                }
            }
            validateBooleanRepositoryConfig(adapter, errors, "default");
            if ("objectSnapshot".equals(adapter.adapterName())
                    && !(repository instanceof JsonObjectSnapshotRepository)) {
                errors.add("Repository " + adapter.repositoryName()
                        + " adapter objectSnapshot requires JsonObjectSnapshotRepository, but runtime uses "
                        + repository.getClass().getName() + ".");
            }
            if (isJdbcObjectRepositoryAdapter(adapter.adapterName())
                    && !(repository instanceof JdbcObjectRepository)) {
                errors.add("Repository " + adapter.repositoryName()
                        + " adapter " + adapter.adapterName()
                        + " requires JdbcObjectRepository, but runtime uses "
                        + repository.getClass().getName() + ".");
            }
        }
        return List.copyOf(errors);
    }

    private boolean isSupportedRepositoryAdapter(String adapterName) {
        return "objectSnapshot".equals(adapterName)
                || "objectRepository".equals(adapterName)
                || isJdbcObjectRepositoryAdapter(adapterName);
    }

    private boolean isJdbcObjectRepositoryAdapter(String adapterName) {
        return Set.of("jdbcObjectRepository", "jdbc-object-repository").contains(adapterName);
    }

    private void validateOptionalRepositoryConfig(PhysicalRuntimeCatalog.RepositoryAdapter adapter,
                                                  List<String> errors, String key) {
        String value = adapter.configuration().get(key);
        if (value != null && value.isBlank()) {
            errors.add("Repository " + adapter.repositoryName()
                    + " " + adapter.adapterName() + " adapter config " + key
                    + " must not be blank when declared.");
        }
    }

    private void validateNamedRetentionMillis(PhysicalRuntimeCatalog.RepositoryAdapter adapter,
                                              List<String> errors,
                                              String key,
                                              String label) {
        String value = adapter.configuration().get(key);
        if (value == null || value.isBlank()) {
            return;
        }
        for (String entry : value.split(",", -1)) {
            if (entry.isBlank()) {
                errors.add("Repository " + adapter.repositoryName()
                        + " " + adapter.adapterName()
                        + " adapter config " + key
                        + " entries must use " + label + ":positiveMillis.");
                continue;
            }
            String[] parts = entry.split(":", 2);
            if (parts.length != 2 || parts[0].trim().isBlank()) {
                errors.add("Repository " + adapter.repositoryName()
                        + " " + adapter.adapterName()
                        + " adapter config " + key
                        + " entries must use " + label + ":positiveMillis.");
                continue;
            }
            try {
                if (Long.parseLong(parts[1].trim()) <= 0) {
                    errors.add("Repository " + adapter.repositoryName()
                            + " " + adapter.adapterName()
                            + " adapter config " + key
                            + " entry " + parts[0].trim() + " must be a positive integer.");
                }
            } catch (NumberFormatException e) {
                errors.add("Repository " + adapter.repositoryName()
                        + " " + adapter.adapterName()
                        + " adapter config " + key
                        + " entry " + parts[0].trim() + " must be a positive integer.");
            }
        }
    }

    private void validateTransactionRetentionMode(PhysicalRuntimeCatalog.RepositoryAdapter adapter,
                                                  List<String> errors) {
        String value = adapter.configuration().get("transactionRetentionMode");
        if (value == null || value.isBlank()) {
            return;
        }
        if (!Set.of("MANUAL_API", "PHYSICAL_SCHEDULED_ARCHIVE").contains(value)) {
            errors.add("Repository " + adapter.repositoryName()
                    + " " + adapter.adapterName()
                    + " adapter config transactionRetentionMode must be MANUAL_API"
                    + " or PHYSICAL_SCHEDULED_ARCHIVE.");
        }
    }

    private void validateObjectRepositoryImplementationClass(PhysicalRuntimeCatalog.RepositoryAdapter adapter,
                                                             ObjectRepository repository,
                                                             List<String> errors) {
        String implementationClass = adapter.configuration().get("implementationClass");
        if (implementationClass == null || implementationClass.isBlank()) {
            return;
        }
        try {
            Class<?> expectedType = Class.forName(implementationClass);
            if (!expectedType.isInstance(repository)) {
                errors.add("Repository " + adapter.repositoryName()
                        + " adapter objectRepository requires implementationClass " + implementationClass
                        + ", but runtime uses " + repository.getClass().getName() + ".");
            }
        } catch (ClassNotFoundException e) {
            errors.add("Repository " + adapter.repositoryName()
                    + " adapter objectRepository implementationClass " + implementationClass
                    + " is not available.");
        }
    }

    private void validateRepositoryDatasourceDriver(PhysicalRuntimeCatalog.RepositoryAdapter adapter,
                                                    List<String> errors) {
        String datasourceUrl = adapter.configuration().get("datasourceUrl");
        String driverClassName = adapter.configuration().get("driverClassName");
        if (datasourceUrl != null && !datasourceUrl.isBlank()
                && (driverClassName == null || driverClassName.isBlank())) {
            errors.add("Repository " + adapter.repositoryName()
                    + " " + adapter.adapterName() + " adapter config driverClassName"
                    + " must be declared when datasourceUrl is declared.");
        }
    }

    private void validateBooleanRepositoryConfig(PhysicalRuntimeCatalog.RepositoryAdapter adapter,
                                                 List<String> errors, String key) {
        String value = adapter.configuration().get(key);
        if (value != null && !Set.of("true", "false").contains(value.trim())) {
            errors.add("Repository " + adapter.repositoryName()
                    + " " + adapter.adapterName() + " adapter config " + key
                    + " must be true or false.");
        }
    }

    private void applyCatalogFrameworkBackend(PhysicalRuntimeCatalog catalog) {
        findRuntimeFrameworkBackend(catalog).ifPresent(backend -> {
            Map<String, String> config = backend.configuration();
            if (!hasNonBlank(config, "datasourceUrl")) {
                return;
            }
            if (hasMalformedPhysicalConfigPlaceholder(config)) {
                return;
            }
            DataSource dataSource = physicalDataSource("framework", backend.name(), config, Optional.of(backend));
            physicalRuntime.setIdempotencyStore(new JdbcBusinessIdempotencyStore(
                    dataSource, config.get("idempotencyTable")));
            physicalRuntime.setSagaLogStore(new JdbcSagaLogStore(dataSource, config.get("sagaLogTable")));
            physicalRuntime.setTccBranchStore(new JdbcTccBranchStore(dataSource, config.get("tccBranchTable")));
            physicalRuntime.setTccReservationStore(new JdbcTccReservationStore(
                    dataSource, config.get("tccReservationTable")));
            physicalRuntime.setTccReservationTtlMillis(parseNonNegativeLong(
                    config.get("tccReservationTtlMillis"), 0L));
        });
    }

    private Optional<PhysicalRuntimeCatalog.PhysicalBackend> findRuntimeFrameworkBackend(
            PhysicalRuntimeCatalog catalog) {
        for (PhysicalRuntimeCatalog.PhysicalBackend backend : catalog.backends()) {
            if ("localJdbc".equals(backend.adapterName()) || "local-jdbc".equals(backend.adapterName())) {
                return Optional.of(backend);
            }
        }
        for (PhysicalRuntimeCatalog.PhysicalBackend backend : catalog.backends()) {
            if ("true".equalsIgnoreCase(backend.configuration().get("frameworkStores"))) {
                return Optional.of(backend);
            }
        }
        return Optional.empty();
    }

    private void applyCatalogRepositoryAdapters(PhysicalRuntimeCatalog catalog) {
        findRuntimeObjectSnapshotRepository(catalog).ifPresent(adapter -> {
            Map<String, String> config = adapter.configuration();
            if (!hasNonBlank(config, "datasourceUrl")
                    || !hasNonBlank(config, "driverClassName")) {
                return;
            }
            if (hasMalformedPhysicalConfigPlaceholder(config)) {
                return;
            }
            DataSource dataSource = physicalDataSource("repository", adapter.repositoryName(), config,
                    catalog.backendFor("repository", adapter.repositoryName()));
            generatedServiceRuntime.installJsonSnapshotRepository(
                    new JdbcObjectSnapshotStore(dataSource, value -> toJson(value), config.get("table")),
                    objectMapper);
        });
        findRuntimeJdbcObjectRepository(catalog).ifPresent(adapter -> {
            Map<String, String> config = adapter.configuration();
            if (!hasNonBlank(config, "datasourceUrl")
                    || !hasNonBlank(config, "driverClassName")) {
                return;
            }
            if (hasMalformedPhysicalConfigPlaceholder(config)) {
                return;
            }
            DataSource dataSource = physicalDataSource("repository", adapter.repositoryName(), config,
                    catalog.backendFor("repository", adapter.repositoryName()));
            generatedServiceRuntime.installObjectRepository(
                    new JdbcObjectSnapshotStore(dataSource, value -> toJson(value), config.get("table")),
                    objectMapper);
        });
    }

    private void applyCatalogAppDdlSchemas() {
        if (appDdlCatalog.tables().isEmpty()) {
            return;
        }
        findRuntimeJdbcObjectRepository(physicalRuntimeCatalog).ifPresent(adapter -> {
            if (!isAppDdlTablesEnabled(adapter)) {
                return;
            }
            Map<String, String> config = adapter.configuration();
            if (!hasNonBlank(config, "datasourceUrl")
                    || !hasNonBlank(config, "driverClassName")) {
                return;
            }
            if (hasMalformedPhysicalConfigPlaceholder(config)) {
                return;
            }
            DataSource dataSource = physicalDataSource("repository", adapter.repositoryName(), config,
                    physicalRuntimeCatalog.backendFor("repository", adapter.repositoryName()));
            new JdbcAppDdlSchemaManager(dataSource).ensureTables(appDdlCatalog);
            ObjectRepository repository = generatedServiceRuntime.getRepository();
            if (repository instanceof JdbcObjectRepository jdbcObjectRepository) {
                jdbcObjectRepository.useAppDdlCatalog(appDdlCatalog);
                jdbcObjectRepository.useNativeUpdateExecutor(com.servpp.service.repository.NativeUpdateExecutor.load(
                        PhysicalRuntimeCatalog.resolveConfigValue(config.getOrDefault("nativeUpdateExecutor","")),
                        Thread.currentThread().getContextClassLoader()));
                var quantumAttributes = physicalRuntimeCatalog.quantumStores().stream()
                        .flatMap(store -> store.attributeIds().stream()).distinct().toList();
                if (!quantumAttributes.isEmpty()) {
                    if (physicalRuntimeCatalog.quantumStores().stream().anyMatch(store ->
                            !Set.of("jdbcQuantum", "jdbc-quantum").contains(store.adapterName())))
                        throw new IllegalStateException("REPOSITORY_QUANTUM_FACT_PROJECTION_BACKEND_UNSUPPORTED");
                    jdbcObjectRepository.useQuantumFacts(physicalRuntime.getQuantumJournalStore(), quantumAttributes);
                }
            }
        });
    }

    private boolean isAppDdlTablesEnabled(PhysicalRuntimeCatalog.RepositoryAdapter adapter) {
        String value = adapter.configuration().get("appDdlTables");
        return value != null && "true".equals(value.trim());
    }

    private Optional<PhysicalRuntimeCatalog.RepositoryAdapter> findRuntimeObjectSnapshotRepository(
            PhysicalRuntimeCatalog catalog) {
        for (PhysicalRuntimeCatalog.RepositoryAdapter adapter : catalog.repositoryAdapters()) {
            if ("objectSnapshot".equals(adapter.adapterName())) {
                return Optional.of(adapter);
            }
        }
        return Optional.empty();
    }

    private Optional<PhysicalRuntimeCatalog.RepositoryAdapter> findRuntimeJdbcObjectRepository(
            PhysicalRuntimeCatalog catalog) {
        for (PhysicalRuntimeCatalog.RepositoryAdapter adapter : catalog.repositoryAdapters()) {
            if (isJdbcObjectRepositoryAdapter(adapter.adapterName())) {
                return Optional.of(adapter);
            }
        }
        return Optional.empty();
    }

    private List<String> validateQuantumStores(List<GeneratedServiceMetadata> metadata) {
        if (physicalRuntimeCatalog.quantumStores().isEmpty()) {
            return validateQuantumServiceStoreCoverage(metadata);
        }
        List<String> errors = new ArrayList<>();
        validateDuplicateNames(physicalRuntimeCatalog.quantumStores(),
                PhysicalRuntimeCatalog.QuantumStore::name,
                "Quantum store ", " is declared multiple times.", errors);
        for (PhysicalRuntimeCatalog.QuantumStore store : physicalRuntimeCatalog.quantumStores()) {
            if (store.attributeIds().isEmpty()) {
                errors.add("Quantum store " + store.name()
                        + " must declare at least one APP quantum attribute.");
            }
            validateDuplicateQuantumStoreAttributes(store, errors);
            if (store.adapterName() == null || store.adapterName().isBlank()) {
                errors.add("Quantum store " + store.name()
                        + " must declare a PHY adapter.");
                continue;
            }
            if (!isSupportedRuntimeQuantumStoreAdapter(store.adapterName())) {
                errors.add("Quantum store " + store.name()
                        + " declares unsupported adapter " + store.adapterName()
                        + "; supported quantum store adapters are jdbcQuantum, jdbc-quantum,"
                        + " tccObjectStore and quantumService.");
                continue;
            }
            validateRuntimeQuantumAccessContract(store, errors);
            if (isLocalJdbcQuantumStore(store.adapterName())) {
                validateQuantumStoreConfig(store, errors, "datasourceUrl");
                validateQuantumStoreConfig(store, errors, "driverClassName");
                validateQuantumStoreConfig(store, errors, "journalStore");
                validateQuantumStoreConfig(store, errors, "journalTable");
                validateQuantumStoreConfig(store, errors, "valueTable");
                String decimalStorage = store.configuration().get("decimalStorage");
                if (decimalStorage != null && !Set.of("decimal", "text").contains(decimalStorage)) {
                    errors.add("PHY quantumStore " + store.name() + " has unsupported decimalStorage " + decimalStorage);
                }
                validateQuantumStoreSupportedClass(store, errors, "journalStore",
                        JdbcQuantumJournalStore.class.getName());
            } else if ("quantumService".equals(store.adapterName())) {
                validateQuantumServiceProtocol(store, errors);
                validateQuantumServiceEndpoint(store, errors);
                validateQuantumServiceTimeout(store, errors);
                if (usesLogicalQuantumServiceProtocol(store)) {
                    validateQuantumServiceLogicalBindings(store, errors);
                } else if (usesHttpJsonQuantumServiceProtocol(store)) {
                    validateQuantumServiceHttpJsonBindings(store, errors);
                }
            }
        }
        validateRuntimeQuantumImplementationStrategyExclusivity(errors);
        validateQuantumStoreAttributeOwnership(errors);
        validateBackendQuantumStoreSelection(errors);
        validateQuantumServiceStoreCoverage(metadata, errors);
        return List.copyOf(errors);
    }

    private boolean isSupportedRuntimeQuantumStoreAdapter(String adapterName) {
        return isLocalJdbcQuantumStore(adapterName)
                || "tccObjectStore".equals(adapterName)
                || "quantumService".equals(adapterName);
    }

    private void validateRuntimeQuantumAccessContract(PhysicalRuntimeCatalog.QuantumStore store,
                                                      List<String> errors) {
        validateRuntimeQuantumContractValue(store, errors, "implementationStrategy",
                physicalQuantumImplementationStrategy(store.adapterName(), Map.of()));
        validateRuntimeQuantumContractValue(store, errors, "accessMode",
                physicalQuantumAccessMode(physicalQuantumImplementationStrategy(store.adapterName(), Map.of()),
                        Map.of()));
        validateRuntimeQuantumContractValue(store, errors, "idempotencyMode",
                physicalQuantumIdempotencyMode(physicalQuantumImplementationStrategy(store.adapterName(), Map.of()),
                        Map.of()));
        validateRuntimeQuantumContractValue(store, errors, "reversalMode",
                usesLogicalQuantumServiceProtocol(store)
                        ? "SERVICE_REVERSAL"
                        : physicalQuantumReversalMode(Map.of()));
        String reversalMode = store.configuration().get("reversalMode");
        String normalizedReversalMode = reversalMode == null ? null : reversalMode.trim();
        if (reversalMode != null && !reversalMode.isBlank()
                && !"NEGATIVE_DELTA".equals(normalizedReversalMode)
                && !"SERVICE_REVERSAL".equals(normalizedReversalMode)) {
            errors.add("Quantum store " + store.name()
                    + " config reversalMode declares unsupported mode " + reversalMode
                    + "; supported modes are NEGATIVE_DELTA and SERVICE_REVERSAL.");
        }
    }

    private void validateRuntimeQuantumContractValue(PhysicalRuntimeCatalog.QuantumStore store,
                                                     List<String> errors,
                                                     String key,
                                                     String expectedValue) {
        String value = store.configuration().get(key);
        String normalizedValue = value == null ? null : value.trim();
        if (value == null || value.isBlank() || expectedValue == null || expectedValue.equals(normalizedValue)) {
            return;
        }
        errors.add("Quantum store " + store.name()
                + " config " + key + " must be " + expectedValue
                + " when adapter is " + store.adapterName()
                + ", but was " + value + ".");
    }

    private void validateQuantumServiceEndpoint(PhysicalRuntimeCatalog.QuantumStore store,
                                                List<String> errors) {
        String endpoint = store.configuration().get("endpoint");
        if (endpoint == null || endpoint.isBlank()) {
            errors.add("Quantum store " + store.name()
                    + " quantumService adapter config endpoint must not be blank.");
            return;
        }
        try {
            URI uri = URI.create(endpoint.trim());
            String scheme = uri.getScheme();
            if (scheme == null || uri.getHost() == null
                    || (!"http".equalsIgnoreCase(scheme) && !"https".equalsIgnoreCase(scheme))) {
                errors.add("Quantum store " + store.name()
                        + " quantumService adapter config endpoint must be an absolute http or https URI.");
            }
        } catch (IllegalArgumentException e) {
            errors.add("Quantum store " + store.name()
                    + " quantumService adapter config endpoint is invalid: " + endpoint + ".");
        }
    }

    private void validateQuantumServiceTimeout(PhysicalRuntimeCatalog.QuantumStore store,
                                               List<String> errors) {
        String timeoutMillis = store.configuration().get("timeoutMillis");
        if (timeoutMillis == null || timeoutMillis.isBlank()) {
            return;
        }
        try {
            if (Long.parseLong(timeoutMillis.trim()) <= 0) {
                errors.add("Quantum store " + store.name()
                        + " quantumService adapter config timeoutMillis must be positive.");
            }
        } catch (NumberFormatException e) {
            errors.add("Quantum store " + store.name()
                    + " quantumService adapter config timeoutMillis must be a number.");
        }
    }

    private void validateQuantumServiceProtocol(PhysicalRuntimeCatalog.QuantumStore store,
                                                List<String> errors) {
        String configured = store.configuration().get("serviceProtocol");
        if (store.configuration().containsKey("serviceProtocol")
                && (configured == null || configured.isBlank())) {
            errors.add("Quantum store " + store.name()
                    + " quantumService adapter config serviceProtocol must not be blank when declared.");
            return;
        }
        String protocol = physicalQuantumServiceProtocol(store.adapterName(), store.configuration());
        if (!Set.of("HTTP_JSON", "LOGICAL_QSERVICE").contains(protocol)) {
            errors.add("Quantum store " + store.name()
                    + " quantumService adapter config serviceProtocol declares unsupported protocol "
                    + protocol + "; supported protocols are HTTP_JSON and LOGICAL_QSERVICE.");
        }
    }

    private void validateQuantumServiceLogicalBindings(PhysicalRuntimeCatalog.QuantumStore store,
                                                       List<String> errors) {
        String namespace = store.configuration().get("namespace");
        if (namespace == null || namespace.isBlank()) {
            errors.add("Quantum store " + store.name()
                    + " quantumService adapter config namespace must not be blank.");
        }
        Map<String, PhysicalRuntimeCatalog.QuantumDefinition> definitions = new LinkedHashMap<>();
        for (PhysicalRuntimeCatalog.QuantumDefinition definition : store.definitions()) {
            definitions.put(definition.attributeId(), definition);
            try {
                new QuantumServiceDefinition(definition.attributeId(), definition.numberType(),
                        definition.minValue(), definition.maxValue(), definition.scale());
            } catch (IllegalArgumentException e) {
                errors.add("Quantum store " + store.name() + " definition "
                        + definition.attributeId() + " is invalid: " + e.getMessage() + ".");
            }
        }
        for (String attributeId : store.attributeIds()) {
            if (!definitions.containsKey(attributeId)) {
                errors.add("Quantum store " + store.name()
                        + " quantumService has no binding definition for " + attributeId + ".");
            }
        }
        for (String attributeId : definitions.keySet()) {
            if (!store.attributeIds().contains(attributeId)) {
                errors.add("Quantum store " + store.name()
                        + " quantumService defines unknown attribute " + attributeId + ".");
            }
        }
    }

    private void validateQuantumServiceHttpJsonBindings(PhysicalRuntimeCatalog.QuantumStore store,
                                                        List<String> errors) {
        if (store.configuration().containsKey("namespace")) {
            errors.add("Quantum store " + store.name()
                    + " quantumService adapter config namespace is only supported when serviceProtocol"
                    + " is LOGICAL_QSERVICE.");
        }
        if (!store.definitions().isEmpty()) {
            errors.add("Quantum store " + store.name()
                    + " quantum definitions are only supported when serviceProtocol"
                    + " is LOGICAL_QSERVICE.");
        }
    }

    private boolean usesLogicalQuantumServiceProtocol(PhysicalRuntimeCatalog.QuantumStore store) {
        return store != null
                && "LOGICAL_QSERVICE".equals(
                        physicalQuantumServiceProtocol(store.adapterName(), store.configuration()));
    }

    private boolean usesHttpJsonQuantumServiceProtocol(PhysicalRuntimeCatalog.QuantumStore store) {
        return store != null
                && "HTTP_JSON".equals(
                        physicalQuantumServiceProtocol(store.adapterName(), store.configuration()));
    }

    private void validateRuntimeQuantumImplementationStrategyExclusivity(List<String> errors) {
        Map<String, List<String>> storesByStrategy = new LinkedHashMap<>();
        for (PhysicalRuntimeCatalog.QuantumStore store : physicalRuntimeCatalog.quantumStores()) {
            if (!isSupportedRuntimeQuantumStoreAdapter(store.adapterName())) {
                continue;
            }
            String strategy = physicalQuantumImplementationStrategy(store.adapterName(), store.configuration());
            if (strategy == null || strategy.isBlank()) {
                continue;
            }
            storesByStrategy.computeIfAbsent(strategy, ignored -> new ArrayList<>())
                    .add(store.name() + "=" + store.adapterName());
        }
        if (storesByStrategy.size() <= 1) {
            return;
        }
        errors.add("Runtime quantum implementation strategies are mutually exclusive within one physical profile;"
                + " found "
                + storesByStrategy.entrySet().stream()
                        .map(entry -> entry.getKey() + "[" + String.join(",", entry.getValue()) + "]")
                        .collect(Collectors.joining(";"))
                + ".");
    }

    private List<String> validateQuantumServiceStoreCoverage(List<GeneratedServiceMetadata> metadata) {
        List<String> errors = new ArrayList<>();
        validateQuantumServiceStoreCoverage(metadata, errors);
        return List.copyOf(errors);
    }

    private void validateQuantumServiceStoreCoverage(List<GeneratedServiceMetadata> metadata,
                                                     List<String> errors) {
        Set<String> runtimeAttributes = new LinkedHashSet<>();
        for (PhysicalRuntimeCatalog.QuantumStore store : physicalRuntimeCatalog.quantumStores()) {
            runtimeAttributes.addAll(store.attributeIds());
        }
        for (GeneratedServiceMetadata service : metadata) {
            if (service.transactionMode() != TransactionMode.QUANTUM) {
                continue;
            }
            for (String attributeId : service.quantumAttributeIds()) {
                if (!runtimeAttributes.contains(attributeId)) {
                    errors.add("Quantum service " + service.serviceName()
                            + " resource " + service.transactionResourceId()
                            + " attribute " + attributeId
                            + " is not assigned to any runtime quantum store.");
                }
            }
        }
    }

    private void validateQuantumStoreAttributeOwnership(List<String> errors) {
        Map<String, String> storeByAttribute = new LinkedHashMap<>();
        for (PhysicalRuntimeCatalog.QuantumStore store : physicalRuntimeCatalog.quantumStores()) {
            Set<String> seenInStore = new LinkedHashSet<>();
            for (String attributeId : store.attributeIds()) {
                if (!seenInStore.add(attributeId)) {
                    continue;
                }
                String previousStore = storeByAttribute.putIfAbsent(attributeId, store.name());
                if (previousStore != null && !previousStore.equals(store.name())) {
                    errors.add("Quantum attribute " + attributeId
                            + " is assigned to multiple runtime quantum stores: "
                            + previousStore + " and " + store.name() + ".");
                }
            }
        }
    }

    private void validateDuplicateQuantumStoreAttributes(PhysicalRuntimeCatalog.QuantumStore store,
                                                         List<String> errors) {
        Set<String> seen = new LinkedHashSet<>();
        Set<String> duplicated = new LinkedHashSet<>();
        for (String attributeId : store.attributeIds()) {
            if (!seen.add(attributeId) && duplicated.add(attributeId)) {
                errors.add("Quantum store " + store.name()
                        + " declares duplicate attribute " + attributeId + ".");
            }
        }
    }

    private <T> void validateDuplicateNames(List<T> items, Function<T, String> nameResolver,
                                           String prefix, String suffix, List<String> errors) {
        Set<String> seen = new LinkedHashSet<>();
        Set<String> duplicated = new LinkedHashSet<>();
        for (T item : items) {
            String name = nameResolver.apply(item);
            if (!seen.add(name) && duplicated.add(name)) {
                errors.add(prefix + name + suffix);
            }
        }
    }

    private void validateBackendQuantumStoreSelection(List<String> errors) {
        Set<String> quantumStoreNames = new LinkedHashSet<>();
        for (PhysicalRuntimeCatalog.QuantumStore store : physicalRuntimeCatalog.quantumStores()) {
            quantumStoreNames.add(store.name());
        }
        for (PhysicalRuntimeCatalog.PhysicalBackend backend : physicalRuntimeCatalog.backends()) {
            String quantumStoreName = backend.quantumStoreName();
            if (quantumStoreName != null && !quantumStoreName.isBlank()
                    && !quantumStoreNames.contains(quantumStoreName)) {
                errors.add("Physical backend " + backend.name()
                        + " quantumStore references undefined quantum store " + quantumStoreName + ".");
            }
            if (physicalRuntimeCatalog.quantumStores().size() > 1
                    && isLocalJdbcBackend(backend)
                    && backendHandlesQuantumSemantics(backend)
                    && (quantumStoreName == null || quantumStoreName.isBlank())) {
                errors.add("Physical backend " + backend.name()
                        + " localJdbc adapter must declare quantumStore"
                        + " when multiple quantum stores are declared.");
            }
        }
    }

    private boolean isLocalJdbcBackend(PhysicalRuntimeCatalog.PhysicalBackend backend) {
        return Set.of("localJdbc", "local-jdbc").contains(backend.adapterName());
    }

    private boolean backendHandlesQuantumSemantics(PhysicalRuntimeCatalog.PhysicalBackend backend) {
        for (PhysicalRuntimeCatalog.PhysicalBinding binding : backend.bindings()) {
            if ("quantum".equals(binding.kind())) {
                return true;
            }
        }
        return physicalRuntimeCatalog.backends().size() == 1 && backend.bindings().isEmpty();
    }

    private void applyCatalogQuantumStore(PhysicalRuntimeCatalog catalog) {
        findRuntimeQuantumStore(catalog).ifPresent(store -> {
            if ("tccObjectStore".equals(store.adapterName())) {
                TccObjectStoreQuantumCoordinator coordinator =
                        physicalRuntime.getTccObjectStoreQuantumCoordinator();
                if (!coordinator.executable()
                        || coordinator instanceof JdbcTccObjectStoreQuantumCoordinator) {
                    JdbcTccObjectStoreQuantumCoordinator jdbcCoordinator =
                            createJdbcTccObjectStoreQuantumCoordinator(catalog, store).orElse(null);
                    coordinator = jdbcCoordinator == null
                            ? TccObjectStoreQuantumCoordinator.noop()
                            : jdbcCoordinator;
                    physicalRuntime.setTccObjectStoreQuantumCoordinator(coordinator);
                }
                physicalRuntime.setQuantumAccessAdapter(
                        new TccObjectStoreQuantumAccessAdapter(store.name(), coordinator));
                return;
            }
            Map<String, String> config = store.configuration();
            if ("quantumService".equals(store.adapterName())) {
                if (hasMalformedPhysicalConfigPlaceholder(config)
                        || !validQuantumServiceRuntimeConfig(store)) {
                    return;
                }
                if (!usesLogicalQuantumServiceProtocol(store)) {
                    physicalRuntime.setQuantumAccessAdapter(new QuantumServiceAccessAdapter(store.name(),
                            config.get("endpoint"), physicalQuantumReversalMode(config),
                            new HttpJsonQuantumServiceClient(config.get("endpoint"),
                                    quantumServiceTimeoutMillis(store.name(), config.get("timeoutMillis")))));
                    return;
                }
                physicalRuntime.setQuantumAccessAdapter(new QuantumServiceAccessAdapter(store.name(),
                        config.get("endpoint"), physicalQuantumReversalMode(config),
                        config.get("namespace"), store.definitions().stream()
                                .map(definition -> new QuantumServiceDefinition(
                                        definition.attributeId(), definition.numberType(),
                                        definition.minValue(), definition.maxValue(), definition.scale()))
                                .toList(),
                        new HttpLogicalQuantumServiceClient(config.get("endpoint"),
                                quantumServiceTimeoutMillis(store.name(), config.get("timeoutMillis"))),
                        new HttpLogicalQuantumProvisioningClient(config.get("endpoint"),
                                quantumServiceTimeoutMillis(store.name(), config.get("timeoutMillis")))));
                return;
            }
            if (!Set.of("jdbcQuantum", "jdbc-quantum").contains(store.adapterName())) {
                return;
            }
            if (!hasNonBlank(config, "datasourceUrl")
                    || !hasNonBlank(config, "driverClassName")
                    || !JdbcQuantumJournalStore.class.getName().equals(config.get("journalStore"))
                    || !hasNonBlank(config, "journalTable")
                    || !hasNonBlank(config, "valueTable")) {
                return;
            }
            if (hasMalformedPhysicalConfigPlaceholder(config)) {
                return;
            }
            Optional<PhysicalRuntimeCatalog.PhysicalBackend> backend = catalog.backends().stream()
                    .filter(item -> store.name().equals(item.quantumStoreName()))
                    .findFirst();
            DataSource dataSource = physicalDataSource("quantumStore", store.name(), config, backend);
            physicalRuntime.setQuantumJournalStore(new JdbcQuantumJournalStore(
                    dataSource,
                    config.get("journalTable"),
                    config.get("valueTable"),
                    config.getOrDefault("decimalStorage", "decimal")));
        });
    }

    private Optional<JdbcTccObjectStoreQuantumCoordinator> createJdbcTccObjectStoreQuantumCoordinator(
            PhysicalRuntimeCatalog catalog,
            PhysicalRuntimeCatalog.QuantumStore store) {
        for (PhysicalRuntimeCatalog.PhysicalBackend backend : quantumStoreReferencingBackends(store.name())) {
            String configuredCoordinator = backend.configuration()
                    .getOrDefault("tccObjectStoreQuantumCoordinator", "");
            if (!configuredCoordinator.isBlank()
                    && !JdbcTccObjectStoreQuantumCoordinator.class.getName().equals(configuredCoordinator)) {
                continue;
            }
            Optional<DataSource> repositoryDataSource = tccObjectStoreRepositoryDataSource(catalog, backend);
            Map<String, String> backendConfig = backend.configuration();
            DataSource dataSource = repositoryDataSource.orElseGet(() -> {
                if (!hasNonBlank(backendConfig, "datasourceUrl")
                        || !hasNonBlank(backendConfig, "driverClassName")
                        || hasMalformedPhysicalConfigPlaceholder(backendConfig)) {
                    return null;
                }
                return physicalDataSource("backend", backend.name(), backendConfig, Optional.of(backend));
            });
            if (dataSource == null) {
                continue;
            }
            return Optional.of(new JdbcTccObjectStoreQuantumCoordinator(
                    dataSource,
                    backendConfig.getOrDefault("tccQuantumJournalTable",
                            JdbcTccObjectStoreQuantumCoordinator.DEFAULT_JOURNAL_TABLE),
                    backendConfig.getOrDefault("tccQuantumValueTable",
                            JdbcTccObjectStoreQuantumCoordinator.DEFAULT_VALUE_TABLE)));
        }
        return Optional.empty();
    }

    private Optional<DataSource> tccObjectStoreRepositoryDataSource(
            PhysicalRuntimeCatalog catalog,
            PhysicalRuntimeCatalog.PhysicalBackend backend) {
        for (PhysicalRuntimeCatalog.PhysicalBinding binding : backend.bindings()) {
            if (!"repository".equals(binding.kind()) || "*".equals(binding.targetName())) {
                continue;
            }
            Optional<PhysicalRuntimeCatalog.RepositoryAdapter> adapter =
                    catalog.repositoryAdapter(binding.targetName());
            if (adapter.isEmpty()) {
                continue;
            }
            Map<String, String> config = adapter.get().configuration();
            if (!hasNonBlank(config, "datasourceUrl")
                    || !hasNonBlank(config, "driverClassName")
                    || hasMalformedPhysicalConfigPlaceholder(config)) {
                continue;
            }
            return Optional.of(physicalDataSource("repository", binding.targetName(), config,
                    Optional.of(backend)));
        }
        return Optional.empty();
    }

    private DataSource physicalDataSource(String resourceKind, String resourceName,
                                          Map<String, String> configuration,
                                          Optional<PhysicalRuntimeCatalog.PhysicalBackend> backend) {
        String backendName = backend.map(PhysicalRuntimeCatalog.PhysicalBackend::name).orElse("");
        String cacheKey = resourceKind + ":" + resourceName + ":" + backendName + ":"
                + configuration.getOrDefault("datasourceUrl", "")+":"+configuration.getOrDefault("schema", "");
        // An explicitly shared local JDBC backend denotes one enlistable connection resource.
        if (backend.filter(item -> Set.of("localJdbc", "local-jdbc").contains(item.adapterName())).isPresent()) {
            String connectionConfig = java.util.Arrays.asList(configuration.get("driverClassName"),
                    configuration.get("datasourceUrl"),
                    firstNonBlank(configuration.get("username"), configuration.get("user")),
                    configuration.get("password"),configuration.get("schema")).stream()
                    .map(value -> value == null ? "-1:" : value.length() + ":" + value)
                    .collect(java.util.stream.Collectors.joining());
            try {
                cacheKey = "sharedJdbc:" + java.util.HexFormat.of().formatHex(
                        java.security.MessageDigest.getInstance("SHA-256").digest(
                                connectionConfig.getBytes(java.nio.charset.StandardCharsets.UTF_8)));
            } catch (java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
        }
        return physicalDataSources.computeIfAbsent(cacheKey, ignored -> {
            DataSource rawDataSource = new DriverManagerJdbcDataSource(
                    configuration.get("driverClassName"),
                    configuration.get("datasourceUrl"),
                    firstNonBlank(configuration.get("username"), configuration.get("user")),
                    configuration.get("password"),configuration.get("schema"));
            return backend
                    .flatMap(item -> physicalBackendRegistry.adapterFor(item.adapterName()))
                    .map(adapter -> adapter.wrapDataSource(backendName, resourceKind, resourceName, rawDataSource))
                    .orElse(rawDataSource);
        });
    }

    private boolean validQuantumServiceRuntimeConfig(PhysicalRuntimeCatalog.QuantumStore store) {
        if (store == null) {
            return false;
        }
        Map<String, String> config = store.configuration();
        String configuredProtocol = config.get("serviceProtocol");
        if (config.containsKey("serviceProtocol")
                && (configuredProtocol == null || configuredProtocol.isBlank())) {
            return false;
        }
        String protocol = physicalQuantumServiceProtocol(store.adapterName(), config);
        if (!Set.of("HTTP_JSON", "LOGICAL_QSERVICE").contains(protocol)) {
            return false;
        }
        if ("HTTP_JSON".equals(protocol)
                && (config.containsKey("namespace") || !store.definitions().isEmpty())) {
            return false;
        }
        String endpoint = config.get("endpoint");
        if (endpoint == null || endpoint.isBlank()) {
            return false;
        }
        try {
            URI uri = URI.create(endpoint.trim());
            String scheme = uri.getScheme();
            if (scheme == null || uri.getHost() == null
                    || (!"http".equalsIgnoreCase(scheme) && !"https".equalsIgnoreCase(scheme))) {
                return false;
            }
        } catch (IllegalArgumentException e) {
            return false;
        }
        if (usesLogicalQuantumServiceProtocol(store)
                && (!hasNonBlank(config, "namespace")
                || !"SERVICE_REVERSAL".equals(physicalQuantumReversalMode(config))
                || store.definitions().isEmpty())) {
            return false;
        }
        String timeoutMillis = config.get("timeoutMillis");
        if (timeoutMillis == null || timeoutMillis.isBlank()) {
            return true;
        }
        try {
            return Long.parseLong(timeoutMillis.trim()) > 0;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    private Optional<PhysicalRuntimeCatalog.QuantumStore> findRuntimeQuantumStore(PhysicalRuntimeCatalog catalog) {
        for (PhysicalRuntimeCatalog.PhysicalBackend backend : catalog.backends()) {
            String quantumStoreName = backend.quantumStoreName();
            if (quantumStoreName == null || quantumStoreName.isBlank()) {
                continue;
            }
            for (PhysicalRuntimeCatalog.QuantumStore store : catalog.quantumStores()) {
                if (store.name().equals(quantumStoreName)) {
                    return Optional.of(store);
                }
            }
        }
        if (catalog.quantumStores().size() == 1) {
            return Optional.of(catalog.quantumStores().get(0));
        }
        return Optional.empty();
    }

    private static String firstNonBlank(String first, String second) {
        if (first != null && !first.isBlank()) {
            return first;
        }
        return second;
    }

    private static long parseLong(String value, long fallback) {
        if (value == null || value.isBlank()) {
            return fallback;
        }
        try {
            return Long.parseLong(value.trim());
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    private static long quantumServiceTimeoutMillis(String storeName, String value) {
        if (value == null || value.isBlank()) {
            return 5000L;
        }
        try {
            long timeoutMillis = Long.parseLong(value.trim());
            if (timeoutMillis <= 0) {
                throw new IllegalStateException("Quantum store " + storeName
                        + " quantumService adapter config timeoutMillis must be positive.");
            }
            return timeoutMillis;
        } catch (NumberFormatException e) {
            throw new IllegalStateException("Quantum store " + storeName
                    + " quantumService adapter config timeoutMillis must be a number.", e);
        }
    }

    private static boolean hasTransactionRetentionConfig(Map<String, String> config) {
        if (config == null || config.isEmpty()) {
            return false;
        }
        return config.containsKey("transactionRetentionMode")
                || config.containsKey("transactionRetentionPropertyPrefix")
                || config.containsKey("transactionRetentionEnabledByDefault")
                || config.containsKey("transactionRetentionFixedDelayMillis")
                || config.containsKey("transactionRetentionMillis")
                || config.containsKey("transactionRetentionMillisByService")
                || config.containsKey("transactionRetentionMillisByResource")
                || config.containsKey("transactionArchiveRetentionMillis")
                || config.containsKey("transactionArchiveRetentionMillisByResource");
    }

    private boolean hasNonBlank(Map<String, String> config, String key) {
        String value = config.get(key);
        return value != null && !value.isBlank();
    }

    private static boolean hasMalformedPhysicalConfigPlaceholder(Map<String, String> config) {
        if (config == null || config.isEmpty()) {
            return false;
        }
        return config.values().stream()
                .filter(Objects::nonNull)
                .anyMatch(value -> value.contains("${") || value.contains("}"));
    }

    private void validateQuantumStoreConfig(PhysicalRuntimeCatalog.QuantumStore store, List<String> errors,
                                            String key) {
        String value = store.configuration().get(key);
        if (value == null || value.isBlank()) {
            errors.add("Quantum store " + store.name()
                    + " jdbcQuantum adapter config " + key + " must not be blank.");
        }
    }

    private void validateQuantumStoreSupportedClass(PhysicalRuntimeCatalog.QuantumStore store, List<String> errors,
                                                    String key, String supportedClass) {
        String declaredClass = store.configuration().get(key);
        if (declaredClass == null || declaredClass.isBlank() || supportedClass.equals(declaredClass)) {
            return;
        }
        errors.add("Quantum store " + store.name()
                + " jdbcQuantum adapter config " + key
                + " declares unsupported implementation " + declaredClass
                + "; supported implementation is " + supportedClass + ".");
    }

    private String toJson(Object value) {
        try {
            return objectMapper.writeValueAsString(value);
        } catch (Exception e) {
            throw new IllegalStateException("Cannot serialize object snapshot", e);
        }
    }

    private Service decoratePhysicalBackendParticipant(Service service) {
        if (!(service instanceof TransactionalService)
                || originalService(service) instanceof RemoteGeneratedService
                || (service instanceof ScopeMetadataProvider metadata && !metadata.requiresPhysicalBackendBinding())) {
            return service;
        }
        return TransactionParticipantProxy.decorate(service, participant -> {
            PhysicalBackendTransactionParticipant physicalParticipant =
                    new PhysicalBackendTransactionParticipant(participant.getResourceId(),
                            () -> resolveExecutablePhysicalBackend(service));
            if (((TransactionalService) service).getTransactionMode() == TransactionMode.TCC) {
                return new PhysicalCoordinatedTccTransactionParticipant(
                        participant.getResourceId(), participant, physicalParticipant);
            }
            return new ChainedTransactionParticipant(
                    participant.getResourceId(), participant, physicalParticipant);
        });
    }

    private Optional<PhysicalBackendTransactionParticipant.ResolvedBackend> resolveExecutablePhysicalBackend(
            Service service) {
        if (physicalRuntimeCatalog.backends().isEmpty()) {
            return Optional.empty();
        }
        GeneratedServiceMetadata metadata = describeGeneratedService(service);
        if (metadata.remote() || metadata.transactionMode() == null || !metadata.physicalBindingRequired()) {
            return Optional.empty();
        }
        PhysicalBackendAssignment assignment = physicalBackendRegistry.resolve(metadata);
        if (!assignment.resolved()) {
            throw new IllegalStateException("Physical backend is not resolved for "
                    + assignment.transactionKind() + " " + assignment.targetName()
                    + " used by service " + assignment.serviceName() + ".");
        }
        if (!assignment.adapterAvailable()) {
            throw new IllegalStateException("Physical backend " + assignment.backendName()
                    + " has no registered adapter for " + assignment.transactionKind()
                    + " " + assignment.targetName() + " used by service " + assignment.serviceName() + ".");
        }
        if (!assignment.adapterSupportsTransaction()) {
            throw new IllegalStateException("Physical backend " + assignment.backendName()
                    + " adapter " + assignment.adapterImplementationType()
                    + " does not support " + assignment.transactionKind()
                    + " " + assignment.targetName() + " used by service " + assignment.serviceName() + ".");
        }
        return physicalBackendRegistry.adapterFor(assignment.adapterName())
                .map(adapter -> new PhysicalBackendTransactionParticipant.ResolvedBackend(assignment, adapter));
    }

    private List<String> validateCompensationRules(List<GeneratedServiceMetadata> metadata) {
        Map<String, GeneratedServiceMetadata> servicesByName = new LinkedHashMap<>();
        for (GeneratedServiceMetadata service : metadata) {
            servicesByName.put(service.serviceName(), service);
        }
        List<String> errors = new ArrayList<>();
        for (GeneratedServiceMetadata service : metadata) {
            if (!service.compensationServiceNames().isEmpty()) {
                if (service.remote()) {
                    errors.add("Compensated service " + service.serviceName()
                            + " cannot be a remote generated service.");
                }
                if (!service.scopeLocal()) {
                    errors.add("Compensated service " + service.serviceName()
                            + " must be declared in local APP scope.");
                }
                if (service.transactionMode() == null) {
                    errors.add("Compensated service " + service.serviceName()
                            + " must declare a transaction mode.");
                }
                if (hasKnownServiceKind(service)
                        && service.serviceKind() != GeneratedServiceKind.ATOMIC_UPDATE
                        && service.serviceKind() != GeneratedServiceKind.SCENARIO) {
                    errors.add("Compensated service " + service.serviceName()
                            + " must be an atomic update service or saga scenario service.");
                }
                boolean hasArgumentSnapshot = hasArgumentSnapshot(service);
                if (service.transactionMode() != null
                        && service.transactionMode() != TransactionMode.SAGA
                        && !hasArgumentSnapshot) {
                    errors.add("Compensated service " + service.serviceName()
                            + " must declare argument object snapshot rules for recovery evidence.");
                }
                if (service.transactionMode() != null
                        && service.transactionMode() != TransactionMode.SAGA
                        && hasArgumentSnapshot
                        && !hasAfterExecutionArgumentSnapshot(service)) {
                    errors.add("Compensated service " + service.serviceName()
                            + " must declare after-execution argument object snapshot rules for rollback evidence.");
                }
                validateDuplicateCompensationServices(service, errors);
            }
            for (String compensationServiceName : service.compensationServiceNames()) {
                GeneratedServiceMetadata compensation = servicesByName.get(compensationServiceName);
                if (compensation == null) {
                    errors.add("Compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " is not registered as a generated service.");
                    continue;
                }
                if (Objects.equals(service.serviceName(), compensation.serviceName())) {
                    errors.add("Compensation service " + compensationServiceName
                            + " cannot compensate itself.");
                    continue;
                }
                if (compensation.remote()) {
                    errors.add("Compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " cannot be a remote generated service.");
                }
                if (!compensation.scopeLocal()) {
                    errors.add("Compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " must be declared in local APP scope.");
                }
                if (compensation.transactionMode() == null) {
                    errors.add("Compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " must declare a transaction mode.");
                }
                if (hasKnownServiceKind(compensation)
                        && compensation.serviceKind() != GeneratedServiceKind.ATOMIC_UPDATE) {
                    errors.add("Compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " must be an atomic update service.");
                }
                if (!compensation.compensationServiceNames().isEmpty()) {
                    errors.add("Compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " cannot declare nested compensation services.");
                }
                validateMatchingServiceParameters(service, compensation,
                        "Compensation service " + compensation.serviceName(), service.serviceName(), errors);
                if (!hasArgumentSnapshot(compensation)) {
                    errors.add("Compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " must declare argument object snapshot rules for recovery evidence.");
                    continue;
                }
                if (!hasAfterExecutionArgumentSnapshot(compensation)) {
                    errors.add("Compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " must declare after-execution argument object snapshot rules for rollback evidence.");
                    continue;
                }
                if (service.transactionMode() != TransactionMode.SAGA) {
                    validateMatchingCompensationSnapshots(service, compensation, errors);
                }
            }
        }
        return List.copyOf(errors);
    }

    private List<String> validateRemoteCompensationRules(List<GeneratedServiceMetadata> metadata,
                                                         List<RemoteServiceAssignment> remoteAssignments) {
        Map<String, GeneratedServiceMetadata> servicesByName = new LinkedHashMap<>();
        for (GeneratedServiceMetadata service : metadata) {
            servicesByName.put(service.serviceName(), service);
        }
        Map<String, RemoteServiceAssignment> remoteAssignmentsByName = new LinkedHashMap<>();
        for (RemoteServiceAssignment assignment : remoteAssignments) {
            remoteAssignmentsByName.putIfAbsent(assignment.serviceName(), assignment);
        }
        List<String> errors = new ArrayList<>();
        for (GeneratedServiceMetadata service : metadata) {
            if (service.remoteCompensationServiceNames().isEmpty()) {
                continue;
            }
            if (!service.remote()) {
                errors.add("Remote compensation source " + service.serviceName()
                        + " must be a remote generated service.");
            }
            if (service.serviceKind() != GeneratedServiceKind.UNKNOWN
                    && service.serviceKind() != GeneratedServiceKind.ATOMIC_UPDATE
                    && service.serviceKind() != GeneratedServiceKind.SCENARIO) {
                errors.add("Remote compensation source " + service.serviceName()
                        + " must be a remote atomic update service or remote scenario service.");
            }
            validateDuplicateRemoteCompensationServices(service, errors);
            for (String compensationServiceName : service.remoteCompensationServiceNames()) {
                GeneratedServiceMetadata compensation = servicesByName.get(compensationServiceName);
                if (compensation == null) {
                    errors.add("Remote compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " is not registered as a generated service.");
                    continue;
                }
                if (Objects.equals(service.serviceName(), compensation.serviceName())) {
                    errors.add("Remote compensation service " + compensationServiceName
                            + " cannot compensate itself.");
                    continue;
                }
                if (!compensation.remote()) {
                    errors.add("Remote compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " must be a remote generated service.");
                }
                if (compensation.serviceKind() != GeneratedServiceKind.UNKNOWN
                        && compensation.serviceKind() != GeneratedServiceKind.ATOMIC_UPDATE) {
                    errors.add("Remote compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " must be a remote atomic update service.");
                }
                if (!compensation.remoteCompensationServiceNames().isEmpty()) {
                    errors.add("Remote compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " cannot declare nested remote compensation services.");
                }
                validateMatchingServiceParameters(service, compensation,
                        "Remote compensation service " + compensation.serviceName(),
                        service.serviceName(), errors);
                RemoteServiceAssignment assignment = remoteAssignmentsByName.get(compensationServiceName);
                if (assignment == null) {
                    continue;
                }
                if (!assignment.adapterAvailable()) {
                    errors.add("Remote compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " has no registered adapter.");
                } else if (!assignment.adapterExecutable()) {
                    errors.add("Remote compensation service " + compensationServiceName
                            + " referenced by " + service.serviceName()
                            + " has registered adapter " + assignment.adapterImplementationType()
                            + " but the adapter is not executable.");
                }
            }
        }
        return List.copyOf(errors);
    }

    private boolean hasKnownServiceKind(GeneratedServiceMetadata service) {
        return service.serviceKind() != null && service.serviceKind() != GeneratedServiceKind.UNKNOWN;
    }

    private void validateDuplicateRemoteCompensationServices(GeneratedServiceMetadata service, List<String> errors) {
        Set<String> seen = new LinkedHashSet<>();
        Set<String> duplicated = new LinkedHashSet<>();
        for (String compensationServiceName : service.remoteCompensationServiceNames()) {
            if (!seen.add(compensationServiceName) && duplicated.add(compensationServiceName)) {
                errors.add("Remote compensation rule on service " + service.serviceName()
                        + " declares duplicate remote compensation service " + compensationServiceName + ".");
            }
        }
    }

    private void validateDuplicateCompensationServices(GeneratedServiceMetadata service, List<String> errors) {
        Set<String> seen = new LinkedHashSet<>();
        Set<String> duplicated = new LinkedHashSet<>();
        for (String compensationServiceName : service.compensationServiceNames()) {
            if (!seen.add(compensationServiceName) && duplicated.add(compensationServiceName)) {
                errors.add("Compensation rule on service " + service.serviceName()
                        + " declares duplicate compensation service " + compensationServiceName + ".");
            }
        }
    }

    private void validateMatchingServiceParameters(GeneratedServiceMetadata source, GeneratedServiceMetadata target,
                                                   String targetLabel, String sourceServiceName,
                                                   List<String> errors) {
        if (source.serviceParameterTypes().isEmpty() || target.serviceParameterTypes().isEmpty()
                || Objects.equals(source.serviceParameterTypes(), target.serviceParameterTypes())) {
            return;
        }
        errors.add(targetLabel + " for " + sourceServiceName + " must accept the same parameter list.");
    }

    private void validateMatchingCompensationSnapshots(GeneratedServiceMetadata source,
                                                       GeneratedServiceMetadata target,
                                                       List<String> errors) {
        Set<String> targetRules = new LinkedHashSet<>();
        for (ObjectSnapshotRule rule : target.objectSnapshotRules()) {
            if (rule.source() == ObjectSnapshotRule.Source.ARGUMENT) {
                targetRules.add(argumentSnapshotRuleKey(rule));
            }
        }
        for (ObjectSnapshotRule sourceRule : source.objectSnapshotRules()) {
            if (sourceRule.source() != ObjectSnapshotRule.Source.ARGUMENT) {
                continue;
            }
            if (!targetRules.contains(argumentSnapshotRuleKey(sourceRule))) {
                errors.add("Compensation service " + target.serviceName()
                        + " referenced by " + source.serviceName()
                        + " must declare matching argument object snapshot rule "
                        + objectSnapshotRuleName(sourceRule) + ".");
            }
        }
    }

    private List<String> validateIdempotencyMetadata(List<GeneratedServiceMetadata> metadata) {
        List<String> errors = new ArrayList<>();
        for (GeneratedServiceMetadata service : metadata) {
            if (!requiresRuntimeIdempotencyKey(service)) {
                continue;
            }
            if (!service.idempotencyKeyRequired()) {
                errors.add("Generated service " + service.serviceName()
                        + " must expose idempotencyKeyRequired=true for local transactional execution.");
            }
            if (!service.idempotencyKeyAvailable()) {
                errors.add("Generated service " + service.serviceName()
                        + " must expose a unique String idempotency key field on input header "
                        + nullToBlank(service.inputHeaderName()) + ".");
                continue;
            }
            String fieldName = service.idempotencyKeyFieldName();
            if (!"globalSerialNumber".equals(fieldName) && !"messageId".equals(fieldName)) {
                errors.add("Generated service " + service.serviceName()
                        + " idempotency key field must be globalSerialNumber or messageId, but was "
                        + nullToBlank(fieldName) + ".");
                continue;
            }
            validateIdempotencyRequestShape(service, fieldName, errors);
        }
        return List.copyOf(errors);
    }

    private void validateIdempotencyRequestShape(GeneratedServiceMetadata service, String fieldName,
                                                 List<String> errors) {
        Class<?> serviceClass = serviceClass(service, errors, "Generated service ");
        if (serviceClass == null) {
            return;
        }
        Method serviceMethod = findMethod(serviceClass, service.serviceName());
        if (serviceMethod == null) {
            errors.add("Generated service " + service.serviceName()
                    + " must declare method " + service.serviceName()
                    + "(...) so idempotency key can be validated.");
            return;
        }
        if (serviceMethod.getParameterCount() == 0) {
            errors.add("Generated service " + service.serviceName()
                    + " must accept a request argument with AppHeader for idempotency.");
            return;
        }
        List<Class<?>> requestTypes = idempotencyRequestTypes(service, serviceClass, serviceMethod);
        List<String> shapeErrors = new ArrayList<>();
        for (Class<?> requestType : requestTypes) {
            Optional<String> shapeError = validateIdempotencyRequestType(service, fieldName, requestType);
            if (shapeError.isEmpty()) {
                return;
            }
            shapeErrors.add(shapeError.orElseThrow());
        }
        if (shapeErrors.isEmpty()) {
            errors.add("Generated service " + service.serviceName()
                    + " must expose a request type with AppHeader for idempotency.");
        } else {
            errors.add(shapeErrors.get(shapeErrors.size() - 1));
        }
    }

    private List<Class<?>> idempotencyRequestTypes(GeneratedServiceMetadata service, Class<?> serviceClass,
                                                   Method serviceMethod) {
        List<Class<?>> requestTypes = new ArrayList<>();
        if (serviceMethod.getParameterCount() > 0) {
            requestTypes.add(serviceMethod.getParameterTypes()[0]);
        }
        inferGeneratedRequestType(service, serviceClass)
                .filter(type -> requestTypes.stream().noneMatch(type::equals))
                .ifPresent(requestTypes::add);
        return List.copyOf(requestTypes);
    }

    private Optional<Class<?>> inferGeneratedRequestType(GeneratedServiceMetadata service, Class<?> serviceClass) {
        Package servicePackage = serviceClass.getPackage();
        if (servicePackage == null) {
            return Optional.empty();
        }
        String packageName = servicePackage.getName();
        String modelPackage = packageName.contains(".service")
                ? packageName.replace(".service", ".model")
                : packageName + ".model";
        String simpleName = serviceClass.getSimpleName();
        String baseName = simpleName.startsWith("Simple") && simpleName.length() > "Simple".length()
                ? simpleName.substring("Simple".length())
                : upperFirst(service.serviceName());
        try {
            return Optional.of(Class.forName(modelPackage + "." + baseName + "Request"));
        } catch (ClassNotFoundException e) {
            return Optional.empty();
        }
    }

    private Optional<String> validateIdempotencyRequestType(GeneratedServiceMetadata service, String fieldName,
                                                            Class<?> requestType) {
        Method appHeaderGetter = findNoArgMethod(requestType, "getAppHeader").orElse(null);
        if (appHeaderGetter == null) {
            return Optional.of("Generated service " + service.serviceName()
                    + " request type " + requestType.getName()
                    + " must expose getAppHeader() for idempotency.");
        }
        Method idempotencyGetter = findNoArgMethod(appHeaderGetter.getReturnType(),
                getterName(fieldName)).orElse(null);
        if (idempotencyGetter == null) {
            return Optional.of("Generated service " + service.serviceName()
                    + " input header " + nullToBlank(service.inputHeaderName())
                    + " must expose " + getterName(fieldName) + "() for idempotency.");
        }
        if (!String.class.equals(idempotencyGetter.getReturnType())) {
            return Optional.of("Generated service " + service.serviceName()
                    + " input header " + nullToBlank(service.inputHeaderName())
                    + " idempotency getter " + getterName(fieldName)
                    + "() must return String, but was " + idempotencyGetter.getReturnType().getName() + ".");
        }
        return Optional.empty();
    }

    private Optional<Method> findNoArgMethod(Class<?> type, String methodName) {
        if (type == null || methodName == null || methodName.isBlank()) {
            return Optional.empty();
        }
        for (Method method : type.getMethods()) {
            if (method.getName().equals(methodName) && method.getParameterCount() == 0) {
                return Optional.of(method);
            }
        }
        return Optional.empty();
    }

    private String getterName(String fieldName) {
        if (fieldName == null || fieldName.isBlank()) {
            return "";
        }
        return "get" + Character.toUpperCase(fieldName.charAt(0)) + fieldName.substring(1);
    }

    private String upperFirst(String value) {
        if (value == null || value.isBlank()) {
            return "";
        }
        return Character.toUpperCase(value.charAt(0)) + value.substring(1);
    }

    private String lowerFirst(String value) {
        if (value == null || value.isBlank()) {
            return "";
        }
        return Character.toLowerCase(value.charAt(0)) + value.substring(1);
    }

    private boolean requiresRuntimeIdempotencyKey(GeneratedServiceMetadata service) {
        if (!service.scopeLocal() || service.remote()) {
            return false;
        }
        boolean hasAppScopeHeader = service.inputHeaderName() != null && !service.inputHeaderName().isBlank();
        return service.idempotencyKeyRequired()
                || (hasAppScopeHeader
                && requiresRuntimeIdempotencyServiceKind(service)
                && (service.physicalBindingRequired()
                || service.transactionMode() == TransactionMode.SAGA
                || service.transactionMode() == TransactionMode.TCC
                || service.transactionMode() == TransactionMode.QUANTUM));
    }

    private boolean requiresRuntimeIdempotencyServiceKind(GeneratedServiceMetadata service) {
        return service.serviceKind() == GeneratedServiceKind.ATOMIC_UPDATE
                || service.serviceKind() == GeneratedServiceKind.SCENARIO;
    }

    private List<IdempotencyPlan> idempotencyPlans(List<GeneratedServiceMetadata> metadata,
                                                   List<PhysicalBackendAssignment> assignments,
                                                   List<PhysicalQuantumPlan> quantumPlans) {
        Map<String, PhysicalBackendAssignment> assignmentsByService = new LinkedHashMap<>();
        for (PhysicalBackendAssignment assignment : assignments) {
            assignmentsByService.putIfAbsent(assignment.serviceName(), assignment);
        }
        List<IdempotencyPlan> plans = new ArrayList<>();
        for (GeneratedServiceMetadata service : metadata) {
            if (!requiresRuntimeIdempotencyKey(service)) {
                continue;
            }
            PhysicalBackendAssignment assignment = assignmentsByService.get(service.serviceName());
            Map<String, String> adapterConfig = assignment == null ? Map.of() : assignment.adapterConfiguration();
            String idempotencyMode = idempotencyModeForService(service, quantumPlans);
            boolean frameworkOwnedIdempotency = "FRAMEWORK_IDEMPOTENCY".equals(idempotencyMode);
            List<PhysicalQuantumPlan> serviceQuantumPlans =
                    service.transactionMode() == TransactionMode.QUANTUM
                            ? quantumPlansForAttributes(quantumPlans, service.quantumAttributeIds())
                            : List.of();
            plans.add(new IdempotencyPlan(service.serviceName(), service.serviceKind(),
                    service.transactionMode(), service.transactionResourceId(), service.inputHeaderName(),
                    service.idempotencyKeyRequired(), service.idempotencyKeyFieldName(),
                    service.idempotencyKeyPath(), service.idempotencyKeyAvailable(),
                    service.physicalBindingRequired(),
                    assignment == null ? "" : nullToBlank(assignment.backendName()),
                    assignment == null ? "" : nullToBlank(assignment.adapterName()),
                    idempotencyMode,
                    idempotencyOwner(idempotencyMode),
                    idempotencyOwnerStoreNames(serviceQuantumPlans, idempotencyMode),
                    idempotencyOwnerAdapterNames(serviceQuantumPlans, idempotencyMode),
                    idempotencyOwnerAccessModes(serviceQuantumPlans, idempotencyMode),
                    idempotencyOwnerAttributeIds(service.quantumAttributeIds(), idempotencyMode),
                    assignment != null && assignment.adapterAvailable(),
                    assignment != null && assignment.adapterSupportsTransaction(),
                    frameworkOwnedIdempotency ? adapterConfig.getOrDefault("idempotencyStore", "") : "",
                    frameworkOwnedIdempotency ? adapterConfig.getOrDefault("idempotencyTable", "") : "",
                    frameworkOwnedIdempotency
                            ? adapterConfig.getOrDefault("localJdbcDatasourceUrl",
                                    adapterConfig.getOrDefault("datasourceUrl", ""))
                            : "",
                    frameworkOwnedIdempotency
                            ? adapterConfig.getOrDefault("localJdbcDriverClassName",
                                    adapterConfig.getOrDefault("driverClassName", ""))
                            : "",
                    "",
                    List.of(),
                    List.of(),
                    List.of(),
                    "",
                    "",
                    ""));
        }
        return List.copyOf(plans);
    }

    private List<QuantumAccessPlan> quantumAccessPlans(List<GeneratedServiceMetadata> metadata,
                                                       List<PhysicalQuantumPlan> quantumPlans,
                                                       List<ObjectSnapshotPlan> objectSnapshotPlans,
                                                       Map<String, List<String>> compensationRules,
                                                       List<IdempotencyPlan> idempotencyPlans) {
        List<GeneratedServiceMetadata> safeMetadata = metadata == null ? List.of() : List.copyOf(metadata);
        List<PhysicalQuantumPlan> safeQuantumPlans = quantumPlans == null ? List.of() : List.copyOf(quantumPlans);
        List<ObjectSnapshotPlan> safeObjectSnapshotPlans = objectSnapshotPlans == null
                ? List.of()
                : List.copyOf(objectSnapshotPlans);
        Map<String, List<String>> safeCompensationRules = compensationRules == null
                ? Map.of()
                : compensationRules;
        Map<String, IdempotencyPlan> idempotencyPlansByService = new LinkedHashMap<>();
        if (idempotencyPlans != null) {
            for (IdempotencyPlan plan : idempotencyPlans) {
                idempotencyPlansByService.putIfAbsent(plan.serviceName(), plan);
            }
        }
        Set<String> snapshotServiceNames = safeObjectSnapshotPlans.stream()
                .map(ObjectSnapshotPlan::serviceName)
                .filter(value -> value != null && !value.isBlank())
                .collect(Collectors.toCollection(LinkedHashSet::new));
        Set<String> reversalServiceNames = safeCompensationRules.keySet().stream()
                .filter(value -> value != null && !value.isBlank())
                .collect(Collectors.toCollection(LinkedHashSet::new));
        List<QuantumAccessPlan> plans = new ArrayList<>();
        for (GeneratedServiceMetadata service : safeMetadata) {
            if (service.transactionMode() != TransactionMode.QUANTUM) {
                continue;
            }
            List<String> attributes = service.quantumAttributeIds() == null
                    ? List.of()
                    : service.quantumAttributeIds().stream()
                            .filter(value -> value != null && !value.isBlank())
                            .distinct()
                            .toList();
            List<PhysicalQuantumPlan> attributePlans = quantumPlansForAttributes(safeQuantumPlans, attributes);
            boolean quantumServiceOwned = attributePlans.stream()
                    .anyMatch(plan -> "QUANTUM_SERVICE".equals(plan.implementationStrategy()));
            String serviceName = service.serviceName();
            boolean snapshotDeclared = snapshotServiceNames.contains(serviceName);
            boolean reversalDeclared = reversalServiceNames.contains(serviceName);
            IdempotencyPlan idempotencyPlan = idempotencyPlansByService.get(serviceName);
            String idempotencyMode = idempotencyPlan == null ? idempotencyModeForService(service, safeQuantumPlans)
                    : idempotencyPlan.idempotencyMode();
            String idempotencyOwner = idempotencyPlan == null ? idempotencyOwner(idempotencyMode)
                    : idempotencyPlan.idempotencyOwner();
            List<String> missing = quantumServiceAccessContractMissingReasons(service, safeQuantumPlans,
                    quantumServiceOwned && snapshotDeclared ? Set.of(serviceName) : Set.of(),
                    quantumServiceOwned && snapshotDeclared ? Set.of(serviceName) : Set.of(),
                    quantumServiceOwned && reversalDeclared ? Set.of(serviceName) : Set.of(),
                    quantumServiceOwned && reversalDeclared ? Set.of(serviceName) : Set.of(),
                    "SERVICE_IDEMPOTENCY".equals(idempotencyMode) ? Set.of(serviceName) : Set.of());
            List<String> storeNames = distinctQuantumPlanValues(attributePlans, PhysicalQuantumPlan::storeName);
            List<String> adapterNames = distinctQuantumPlanValues(attributePlans, PhysicalQuantumPlan::adapterName);
            List<String> implementationStrategies = distinctQuantumPlanValues(attributePlans,
                    PhysicalQuantumPlan::implementationStrategy);
            if (implementationStrategies.size() > 1) {
                missing.add("mixedImplementationStrategy");
            }
            List<String> accessModes = distinctQuantumPlanValues(attributePlans, PhysicalQuantumPlan::accessMode);
            List<String> executionOwners = distinctQuantumPlanValues(attributePlans,
                    LocalGeneratedServiceRuntime::quantumAccessExecutionOwner);
            List<String> backendBindingRoles = distinctQuantumPlanValues(attributePlans,
                    LocalGeneratedServiceRuntime::quantumAccessBackendBindingRole);
            List<String> reversalModes = distinctQuantumPlanValues(attributePlans, PhysicalQuantumPlan::reversalMode);
            List<String> reversalOwners = distinctQuantumPlanValues(attributePlans,
                    LocalGeneratedServiceRuntime::quantumAccessReversalOwner);
            List<String> reversalExecutions = distinctQuantumPlanValues(attributePlans,
                    LocalGeneratedServiceRuntime::quantumReversalExecutionMode);
            plans.add(GeneratedServiceCatalog.enrichQuantumAccessPlan(
                    new QuantumAccessPlan(serviceName, service.transactionMode(),
                            service.transactionResourceId(),
                            attributes,
                            storeNames,
                            adapterNames,
                            implementationStrategies,
                            implementationStrategies.size() <= 1,
                            implementationStrategies.size() > 1,
                            accessModes,
                            executionOwners,
                            backendBindingRoles,
                            idempotencyMode,
                            idempotencyOwner,
                            quantumAccessIdempotencyBoundary(idempotencyMode),
                            idempotencyPlan != null && idempotencyPlan.idempotencyKeyAvailable(),
                            reversalModes,
                            reversalOwners,
                            reversalExecutions,
                            quantumAccessSnapshotBoundary(implementationStrategies, snapshotDeclared),
                            quantumAccessRecoveryOwner(implementationStrategies),
                            snapshotDeclared && !quantumServiceOwned,
                            reversalDeclared && !quantumServiceOwned,
                            (snapshotDeclared || reversalDeclared) && !quantumServiceOwned,
                            quantumServiceOwned,
                            quantumServiceOwned,
                            quantumServiceOwned,
                            "SERVICE_IDEMPOTENCY".equals(idempotencyMode),
                            quantumServiceOwned && !reversalModes.isEmpty(),
                            reversalModes.contains("NEGATIVE_DELTA"),
                            reversalModes.contains("SERVICE_REVERSAL"),
                            distinctQuantumPlanValues(attributePlans, PhysicalQuantumPlan::endpoint),
                            distinctQuantumPlanValues(attributePlans, PhysicalQuantumPlan::timeoutMillis),
                            distinctQuantumPlanValues(attributePlans, PhysicalQuantumPlan::datasourceUrl),
                            missing.isEmpty(),
                            missing)));
        }
        return List.copyOf(plans);
    }

    private static List<String> distinctQuantumPlanValues(List<PhysicalQuantumPlan> plans,
                                                          Function<PhysicalQuantumPlan, String> mapper) {
        if (plans == null || plans.isEmpty() || mapper == null) {
            return List.of();
        }
        return plans.stream()
                .map(mapper)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .toList();
    }

    private static String quantumAccessIdempotencyBoundary(String idempotencyMode) {
        if ("SERVICE_IDEMPOTENCY".equals(idempotencyMode)) {
            return "QUANTUM_SERVICE_INTERNAL";
        }
        if ("OBJECT_STORE_IDEMPOTENCY".equals(idempotencyMode)) {
            return "OBJECT_STORE_TCC_BOUNDARY";
        }
        return "FRAMEWORK_IDEMPOTENCY_STORE";
    }

    private static String quantumAccessSnapshotBoundary(List<String> implementationStrategies,
                                                        boolean snapshotDeclared) {
        if (implementationStrategies.contains("QUANTUM_SERVICE")) {
            return "QUANTUM_SERVICE_AUDIT_EVIDENCE";
        }
        if (implementationStrategies.contains("TCC_OBJECT_STORE")) {
            return "OBJECT_STORE_TCC_BOUNDARY";
        }
        if (implementationStrategies.contains("GLOBAL_QUANTUM_STORE")) {
            return "QUANTUM_JOURNAL_STORE";
        }
        return snapshotDeclared ? "OBJECT_SNAPSHOT_STORE" : "";
    }

    private static String quantumAccessRecoveryOwner(List<String> implementationStrategies) {
        if (implementationStrategies == null || implementationStrategies.isEmpty()) {
            return "";
        }
        return implementationStrategies.stream()
                .map(LocalGeneratedServiceRuntime::quantumAccessRecoveryOwner)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining("+"));
    }

    private static String quantumAccessRecoveryOwner(String implementationStrategy) {
        if ("QUANTUM_SERVICE".equals(implementationStrategy)) {
            return "QUANTUM_SERVICE";
        }
        if ("TCC_OBJECT_STORE".equals(implementationStrategy)) {
            return "OBJECT_STORE";
        }
        if ("GLOBAL_QUANTUM_STORE".equals(implementationStrategy)) {
            return "FRAMEWORK";
        }
        return blankAsDash(implementationStrategy);
    }

    private String idempotencyModeForService(GeneratedServiceMetadata service, List<PhysicalQuantumPlan> quantumPlans) {
        if (service == null || service.transactionMode() != TransactionMode.QUANTUM) {
            return "FRAMEWORK_IDEMPOTENCY";
        }
        List<PhysicalQuantumPlan> attributePlans =
                quantumPlansForAttributes(quantumPlans, service.quantumAttributeIds());
        if (attributePlans.stream().anyMatch(plan -> "SERVICE_IDEMPOTENCY".equals(plan.idempotencyMode()))) {
            return "SERVICE_IDEMPOTENCY";
        }
        if (attributePlans.stream().anyMatch(plan -> "OBJECT_STORE_IDEMPOTENCY".equals(plan.idempotencyMode()))) {
            return "OBJECT_STORE_IDEMPOTENCY";
        }
        if (attributePlans.stream().anyMatch(plan -> "FRAMEWORK_IDEMPOTENCY".equals(plan.idempotencyMode()))) {
            return "FRAMEWORK_IDEMPOTENCY";
        }
        return attributePlans.stream()
                .map(PhysicalQuantumPlan::idempotencyMode)
                .filter(value -> value != null && !value.isBlank())
                .findFirst()
                .orElse("FRAMEWORK_IDEMPOTENCY");
    }

    private static String idempotencyOwner(String idempotencyMode) {
        if ("SERVICE_IDEMPOTENCY".equals(idempotencyMode)) {
            return "QUANTUM_SERVICE";
        }
        if ("OBJECT_STORE_IDEMPOTENCY".equals(idempotencyMode)) {
            return "OBJECT_STORE";
        }
        return "FRAMEWORK";
    }

    private static String idempotencyOwnerStoreNames(List<PhysicalQuantumPlan> quantumPlans,
                                                     String idempotencyMode) {
        return idempotencyOwnerQuantumPlans(quantumPlans, idempotencyMode).stream()
                .map(PhysicalQuantumPlan::storeName)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining("+"));
    }

    private static String idempotencyOwnerAdapterNames(List<PhysicalQuantumPlan> quantumPlans,
                                                       String idempotencyMode) {
        return idempotencyOwnerQuantumPlans(quantumPlans, idempotencyMode).stream()
                .map(PhysicalQuantumPlan::adapterName)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining("+"));
    }

    private static String idempotencyOwnerAccessModes(List<PhysicalQuantumPlan> quantumPlans,
                                                      String idempotencyMode) {
        return idempotencyOwnerQuantumPlans(quantumPlans, idempotencyMode).stream()
                .map(PhysicalQuantumPlan::accessMode)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining("+"));
    }

    private static String idempotencyOwnerAttributeIds(List<String> quantumAttributeIds,
                                                       String idempotencyMode) {
        if (quantumAttributeIds == null || quantumAttributeIds.isEmpty()
                || idempotencyMode == null || idempotencyMode.isBlank()
                || "FRAMEWORK_IDEMPOTENCY".equals(idempotencyMode)) {
            return "";
        }
        return quantumAttributeIds.stream()
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining("+"));
    }

    private static List<PhysicalQuantumPlan> idempotencyOwnerQuantumPlans(List<PhysicalQuantumPlan> quantumPlans,
                                                                          String idempotencyMode) {
        if (quantumPlans == null || quantumPlans.isEmpty()
                || idempotencyMode == null || idempotencyMode.isBlank()
                || "FRAMEWORK_IDEMPOTENCY".equals(idempotencyMode)) {
            return List.of();
        }
        return quantumPlans.stream()
                .filter(plan -> idempotencyMode.equals(plan.idempotencyMode()))
                .toList();
    }

    private List<ScopeHeaderPlan> scopeHeaderPlans(List<GeneratedServiceMetadata> metadata,
                                                   List<IdempotencyPlan> idempotencyPlans,
                                                   List<PhysicalBackendAssignment> physicalAssignments) {
        Map<String, IdempotencyPlan> idempotencyPlansByService = new LinkedHashMap<>();
        for (IdempotencyPlan plan : idempotencyPlans) {
            idempotencyPlansByService.putIfAbsent(plan.serviceName(), plan);
        }
        Map<String, PhysicalBackendAssignment> physicalAssignmentsByService = new LinkedHashMap<>();
        for (PhysicalBackendAssignment assignment : physicalAssignments) {
            physicalAssignmentsByService.putIfAbsent(assignment.serviceName(), assignment);
        }
        Map<String, ScopeHeaderPlanBuilder> builders = new LinkedHashMap<>();
        for (GeneratedServiceMetadata service : metadata) {
            String scopeName = service.remote() ? "REMOTE" : service.scopeLocal() ? "LOCAL" : "ASYNC";
            builders.computeIfAbsent(scopeName, ignored -> new ScopeHeaderPlanBuilder(scopeName, service))
                    .add(service, requiresRuntimeIdempotencyKey(service),
                            idempotencyPlansByService.get(service.serviceName()),
                            physicalAssignmentsByService.get(service.serviceName()));
        }
        return builders.values().stream()
                .map(ScopeHeaderPlanBuilder::build)
                .toList();
    }

