        if (plan == null || isBlankStatic(plan.backendName())) {
            return "";
        }
        return plan.backendName()
                + ":adapter=" + blankAsDash(plan.adapterName())
                + ":impl=" + blankAsDash(plan.adapterImplementationType())
                + ":transactions=" + blankAsDash(String.join("+", plan.supportedTransactions()))
                + ":datasource=" + blankAsDash(plan.datasourceUrl())
                + ":driver=" + blankAsDash(plan.driverClassName())
                + ":quantum=" + blankAsDash(plan.quantumStoreName())
                + ":quantumDatasource=" + blankAsDash(plan.quantumDatasourceUrl())
                + ":quantumJournal=" + blankAsDash(plan.quantumJournalTableName())
                + ":quantumValue=" + blankAsDash(plan.quantumValueTableName())
                + ":coordinator=" + blankAsDash(plan.transactionCoordinatorName())
                + ":idempotencyStore=" + blankAsDash(plan.idempotencyStoreName())
                + ":idempotency=" + blankAsDash(plan.idempotencyTableName())
                + ":sagaLogStore=" + blankAsDash(plan.sagaLogStoreName())
                + ":sagaLog=" + blankAsDash(plan.sagaLogTableName())
                + ":tccBranchStore=" + blankAsDash(plan.tccBranchStoreName())
                + ":tccBranch=" + blankAsDash(plan.tccBranchTableName())
                + ":tccReservationStore=" + blankAsDash(plan.tccReservationStoreName())
                + ":tccReservation=" + blankAsDash(plan.tccReservationTableName())
                + ":reservationTtl=" + blankAsDash(plan.tccReservationTtlMillis())
                + ":seataApp=" + blankAsDash(plan.applicationId())
                + ":seataGroup=" + blankAsDash(plan.transactionServiceGroup())
                + ":seataBridge=" + blankAsDash(plan.transactionBridgeName())
                + ":seataBridgeClass=" + blankAsDash(plan.transactionBridgeClassName())
                + ":seataTimeout=" + blankAsDash(plan.seataTransactionTimeoutMillis())
                + ":seataQuantum=" + plan.seataQuantumSupported();
