    private static String remoteServiceBinding(RemoteServiceAssignment assignment, PhysicalRemotePlan plan) {
        if (assignment == null || isBlankStatic(assignment.serviceName())) {
            return "";
        }
        return assignment.serviceName()
                + ":adapter=" + blankAsDash(plan == null ? "" : plan.adapterName())
                + ":role=" + blankAsDash(assignment.adapterRole())
                + ":impl=" + blankAsDash(assignment.adapterImplementationType())
                + ":available=" + assignment.adapterAvailable()
                + ":executable=" + assignment.adapterExecutable()
                + ":reference=" + assignment.referenceImplementation()
                + ":external=" + assignment.externalImplementation()
                + ":endpoint=" + blankAsDash(plan == null ? "" : plan.endpoint())
                + ":timeout=" + blankAsDash(plan == null ? "" : plan.timeoutMillis())
                + ":object=" + blankAsDash(plan == null ? "" : plan.objectType())
                + ":objectIds=" + blankAsDash(plan == null ? "" : String.join("+", plan.objectIdPaths()))
                + ":repositoryObjectIds="
                + blankAsDash(plan == null ? "" : String.join("+", plan.repositoryObjectIdPaths()))
                + ":repository=" + blankAsDash(plan == null ? "" : plan.repositoryName())
                + ":repositoryAdapter=" + blankAsDash(plan == null ? "" : plan.repositoryAdapterName())
                + ":repositoryRole=" + blankAsDash(plan == null ? "" : plan.repositoryAdapterRole())
                + ":repositoryAppDdl=" + (plan != null && plan.repositoryAppDdlTables())
                + ":storage=" + blankAsDash(plan == null ? "" : plan.repositoryStorageTableName())
                + ":datasource=" + blankAsDash(plan == null ? "" : plan.repositoryDatasourceUrl())
                + ":repositoryDriver=" + blankAsDash(plan == null ? "" : plan.repositoryDriverClassName());
    }

    private static String remoteProductionReadinessBinding(RemoteServiceAssignment assignment,
                                                           PhysicalRemotePlan plan) {
        if (assignment == null || isBlankStatic(assignment.serviceName())) {
            return "";
        }
        boolean productionReady = remoteProductionReady(assignment, plan);
        String missing = remoteProductionReadinessMissingReason(assignment, plan);
        return assignment.serviceName()
                + ":productionReady=" + productionReady
                + ":adapter=" + blankAsDash(plan == null ? "" : plan.adapterName())
                + ":role=" + blankAsDash(assignment.adapterRole())
                + ":impl=" + blankAsDash(assignment.adapterImplementationType())
                + ":available=" + assignment.adapterAvailable()
                + ":executable=" + assignment.adapterExecutable()
                + ":reference=" + assignment.referenceImplementation()
                + ":external=" + assignment.externalImplementation()
                + ":endpoint=" + blankAsDash(plan == null ? "" : plan.endpoint())
                + ":repository=" + blankAsDash(plan == null ? "" : plan.repositoryName())
                + ":repositoryAdapter=" + blankAsDash(plan == null ? "" : plan.repositoryAdapterName())
                + ":repositoryStorage=" + blankAsDash(plan == null ? "" : plan.repositoryStorageTableName())
                + ":missing=" + missing
                + ":actions=" + remoteProductionReadinessActions(missing);
    }

    private static boolean remoteProductionReady(RemoteServiceAssignment assignment, PhysicalRemotePlan plan) {
        return assignment != null
                && assignment.externalImplementation()
                && assignment.adapterAvailable()
                && assignment.adapterExecutable()
                && "-".equals(remoteExternalEndpointReadinessReason(plan));
    }

    private static String remoteProductionReadinessMissingReason(RemoteServiceAssignment assignment,
                                                                 PhysicalRemotePlan plan) {
        if (assignment == null) {
            return "assignment";
        }
        if (assignment.referenceImplementation()) {
            return "externalAdapter";
        }
        if (!assignment.adapterAvailable()) {
            return "adapter";
        }
        if (!assignment.adapterExecutable()) {
            return "executableAdapter";
        }
        if (!assignment.externalImplementation()) {
            return "externalImplementation";
        }
        return remoteExternalEndpointReadinessReason(plan);
    }

    private static String remoteProductionReadinessActions(String missing) {
        if (isBlankStatic(missing) || "-".equals(missing)) {
            return "-";
        }
        if ("endpoint".equals(missing)
                || "endpointInvalid".equals(missing)
                || "developmentEndpoint".equals(missing)
                || "placeholderEndpoint".equals(missing)) {
            return remoteExternalEndpointStrictActions(missing);
        }
        if ("externalAdapter".equals(missing)) {
            return "replaceReferenceRemoteAdapter+bindExternalDomainAdapter";
        }
        if ("adapter".equals(missing)) {
            return "bindRemoteAdapter";
        }
        if ("executableAdapter".equals(missing)) {
            return "enableExecutableRemoteAdapter";
        }
        if ("externalImplementation".equals(missing)) {
            return "switchRemoteServiceToExternalImplementation";
        }
        return "resolve" + Character.toUpperCase(missing.charAt(0)) + missing.substring(1);
    }

    private static String remoteExternalEndpointReadinessBinding(RemoteServiceAssignment assignment,
                                                                 PhysicalRemotePlan plan) {
        if (assignment == null || isBlankStatic(assignment.serviceName())
                || !assignment.externalImplementation()) {
            return "";
        }
        String reason = remoteExternalEndpointReadinessReason(plan);
        boolean ready = "-".equals(reason);
        return assignment.serviceName()
                + ":endpointReady=" + ready
                + ":readiness=" + (ready ? "PRODUCTION_READY" : "CONTRACT_ONLY")
                + ":reason=" + reason
                + ":adapter=" + blankAsDash(plan == null ? "" : plan.adapterName())
                + ":role=" + blankAsDash(assignment.adapterRole())
                + ":impl=" + blankAsDash(assignment.adapterImplementationType())
                + ":endpoint=" + blankAsDash(plan == null ? "" : plan.endpoint())
                + ":timeout=" + blankAsDash(plan == null ? "" : plan.timeoutMillis())
                + ":actions=" + remoteExternalEndpointStrictActions(reason);
    }

    private long remoteExternalEndpointReadinessReasonPlanCount(List<RemoteServiceAssignment> assignments,
                                                                Map<String, PhysicalRemotePlan> physicalPlansByService) {
        return remoteExternalEndpointReadinessReasonCounts(assignments, physicalPlansByService).values().stream()
                .mapToLong(Long::longValue)
                .sum();
    }

    private String remoteExternalEndpointReadinessReasonCountBindings(
            List<RemoteServiceAssignment> assignments,
            Map<String, PhysicalRemotePlan> physicalPlansByService) {
        Map<String, Long> counts = remoteExternalEndpointReadinessReasonCounts(assignments, physicalPlansByService);
        long total = assignments == null ? 0 : assignments.stream()
                .filter(RemoteServiceAssignment::externalImplementation)
                .count();
        return counts.entrySet().stream()
                .map(entry -> entry.getKey()
                        + ":count=" + entry.getValue()
                        + ":coverage=" + coverage(entry.getValue(), total)
                        + ":services=" + remoteExternalEndpointReadinessReasonServiceNames(assignments,
                                physicalPlansByService, entry.getKey())
                        + ":actions=" + remoteExternalEndpointStrictActions(entry.getKey()))
                .collect(Collectors.joining(";"));
    }

    private Map<String, Long> remoteExternalEndpointReadinessReasonCounts(
            List<RemoteServiceAssignment> assignments,
            Map<String, PhysicalRemotePlan> physicalPlansByService) {
        Map<String, Long> counts = new LinkedHashMap<>();
        if (assignments == null) {
            return counts;
        }
        for (RemoteServiceAssignment assignment : assignments) {
            if (assignment == null || !assignment.externalImplementation()) {
                continue;
            }
            PhysicalRemotePlan plan = physicalPlansByService == null
                    ? null : physicalPlansByService.get(assignment.serviceName());
            String reason = remoteExternalEndpointReadinessReason(plan);
            if (!reason.isBlank() && !"-".equals(reason)) {
                counts.merge(reason, 1L, Long::sum);
            }
        }
        return counts;
    }

    private static String remoteExternalEndpointReadinessReasonServiceNames(
            List<RemoteServiceAssignment> assignments,
            Map<String, PhysicalRemotePlan> physicalPlansByService,
            String reason) {
        if (assignments == null || reason == null || reason.isBlank()) {
            return "";
        }
        return assignments.stream()
                .filter(Objects::nonNull)
                .filter(RemoteServiceAssignment::externalImplementation)
                .filter(assignment -> {
                    PhysicalRemotePlan plan = physicalPlansByService == null
                            ? null : physicalPlansByService.get(assignment.serviceName());
                    return reason.equals(remoteExternalEndpointReadinessReason(plan));
                })
                .map(RemoteServiceAssignment::serviceName)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining("+"));
    }

    private static String remoteServiceMissingBinding(RemoteServiceAssignment assignment, PhysicalRemotePlan plan,
                                                      String missingKind) {
        if (assignment == null || isBlankStatic(assignment.serviceName())) {
            return "";
        }
        return assignment.serviceName()
                + ":missing=" + blankAsDash(missingKind)
                + ":actions=" + blankAsDash(remoteServiceMissingActions(missingKind))
                + ":adapter=" + blankAsDash(plan == null ? "" : plan.adapterName())
                + ":role=" + blankAsDash(assignment.adapterRole())
                + ":impl=" + blankAsDash(assignment.adapterImplementationType())
                + ":available=" + assignment.adapterAvailable()
                + ":executable=" + assignment.adapterExecutable()
                + ":reference=" + assignment.referenceImplementation()
                + ":external=" + assignment.externalImplementation()
                + ":endpoint=" + blankAsDash(plan == null ? "" : plan.endpoint())
                + ":timeout=" + blankAsDash(plan == null ? "" : plan.timeoutMillis())
                + ":object=" + blankAsDash(plan == null ? "" : plan.objectType())
                + ":objectIds=" + blankAsDash(plan == null ? "" : String.join("+", plan.objectIdPaths()))
                + ":repositoryObjectIds="
                + blankAsDash(plan == null ? "" : String.join("+", plan.repositoryObjectIdPaths()))
                + ":repository=" + blankAsDash(plan == null ? "" : plan.repositoryName())
                + ":repositoryAdapter=" + blankAsDash(plan == null ? "" : plan.repositoryAdapterName())
                + ":repositoryRole=" + blankAsDash(plan == null ? "" : plan.repositoryAdapterRole())
                + ":repositoryAppDdl=" + (plan != null && plan.repositoryAppDdlTables())
                + ":storage=" + blankAsDash(plan == null ? "" : plan.repositoryStorageTableName())
                + ":datasource=" + blankAsDash(plan == null ? "" : plan.repositoryDatasourceUrl())
                + ":repositoryDriver=" + blankAsDash(plan == null ? "" : plan.repositoryDriverClassName());
    }

    static String remoteServiceMissingActions(String missingKind) {
        if (isBlankStatic(missingKind)) {
            return "";
        }
        return switch (missingKind) {
            case "physicalRemote" -> "declarePhysicalRemoteAdapter";
            case "referenceRemote" -> "bindObjectRepositoryRemoteAdapter";
            case "referenceObjectKey" -> "declareReferenceRemoteObjectKey";
            case "referenceRepositoryBinding" -> "bindReferenceRemoteObjectRepository";
            case "referenceRepositoryAppDdl" -> "enableReferenceRemoteAppDdlRepository";
            case "referenceRepositoryStorage" -> "configureReferenceRemoteStorageTable";
            case "referenceRepositoryDatasource" -> "configureReferenceRemoteDatasource";
            case "referenceRepositoryDriver" -> "configureReferenceRemoteDriver";
            case "realExternalRemote" -> "replaceReferenceRemoteAdapter+bindExternalDomainAdapter";
            default -> "resolveRemoteServicePhysicalBinding";
        };
    }

    private static String physicalRemoteBinding(PhysicalRemotePlan plan, String bindingKind) {
        if (plan == null || isBlankStatic(plan.serviceName())) {
            return "";
        }
        return plan.serviceName()
                + ":binding=" + blankAsDash(bindingKind)
                + ":actions=removeOrRenamePhysicalRemoteAdapter"
                + ":adapter=" + blankAsDash(plan.adapterName())
                + ":role=" + blankAsDash(plan.adapterRole())
                + ":executable=" + plan.adapterExecutable()
                + ":reference=" + plan.referenceImplementation()
                + ":external=" + plan.externalImplementation()
                + ":endpoint=" + blankAsDash(plan.endpoint())
                + ":timeout=" + blankAsDash(plan.timeoutMillis())
                + ":object=" + blankAsDash(plan.objectType())
                + ":objectIds=" + blankAsDash(String.join("+", plan.objectIdPaths()))
                + ":repositoryObjectIds=" + blankAsDash(String.join("+", plan.repositoryObjectIdPaths()))
                + ":repository=" + blankAsDash(plan.repositoryName())
                + ":repositoryAdapter=" + blankAsDash(plan.repositoryAdapterName())
                + ":repositoryRole=" + blankAsDash(plan.repositoryAdapterRole())
                + ":repositoryAppDdl=" + plan.repositoryAppDdlTables()
                + ":storage=" + blankAsDash(plan.repositoryStorageTableName())
                + ":datasource=" + blankAsDash(plan.repositoryDatasourceUrl())
                + ":repositoryDriver=" + blankAsDash(plan.repositoryDriverClassName());
    }

    private DeploymentValidationPlan remoteCompensationDeploymentPlan(Map<String, List<String>> remoteCompensationRules,
                                                                      List<PhysicalRemotePlan> remotePlans,
                                                                      List<RemoteServiceAssignment> assignments,
                                                                      List<String> errors) {
        Map<String, List<String>> safeRules = remoteCompensationRules == null ? Map.of() : remoteCompensationRules;
        List<PhysicalRemotePlan> safeRemotePlans = remotePlans == null ? List.of() : List.copyOf(remotePlans);
        List<RemoteServiceAssignment> safeAssignments = assignments == null ? List.of() : List.copyOf(assignments);
        List<String> safeErrors = errors == null ? List.of() : List.copyOf(errors);
        List<String> deploymentErrors = new ArrayList<>(safeErrors);
        Set<String> targetServiceNames = safeRules.values().stream()
                .filter(Objects::nonNull)
                .flatMap(List::stream)
                .filter(value -> value != null && !value.isBlank())
                .collect(Collectors.toCollection(LinkedHashSet::new));
        Map<String, RemoteServiceAssignment> assignmentsByService = safeAssignments.stream()
                .collect(Collectors.toMap(RemoteServiceAssignment::serviceName,
                        assignment -> assignment, (first, second) -> first, LinkedHashMap::new));
        Map<String, PhysicalRemotePlan> remotePlansByService = safeRemotePlans.stream()
                .collect(Collectors.toMap(PhysicalRemotePlan::serviceName,
                        plan -> plan, (first, second) -> first, LinkedHashMap::new));
        List<RemoteServiceAssignment> targetAssignments = targetServiceNames.stream()
                .map(assignmentsByService::get)
                .filter(Objects::nonNull)
                .toList();
        List<PhysicalRemotePlan> targetRemotePlans = targetServiceNames.stream()
                .map(remotePlansByService::get)
                .filter(Objects::nonNull)
                .toList();
        Map<String, String> metadata = new LinkedHashMap<>();
        metadata.put("ruleCount", String.valueOf(safeRules.values().stream()
                .filter(Objects::nonNull)
                .mapToInt(List::size)
                .sum()));
        metadata.put("sourceServiceNames", safeRules.keySet().stream()
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("targetServiceNames", String.join(",", targetServiceNames));
        metadata.put("targetAdapterNames", targetRemotePlans.stream()
                .map(PhysicalRemotePlan::adapterName)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("targetPhysicalAdapterRoles", targetRemotePlans.stream()
                .map(PhysicalRemotePlan::adapterRole)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("targetAdapterImplementationTypes", targetAssignments.stream()
                .map(RemoteServiceAssignment::adapterImplementationType)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("targetAdapterRoles", targetAssignments.stream()
                .map(RemoteServiceAssignment::adapterRole)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        Set<String> executableTargetServiceNames = targetAssignments.stream()
                .filter(RemoteServiceAssignment::adapterExecutable)
                .map(RemoteServiceAssignment::serviceName)
                .filter(value -> value != null && !value.isBlank())
                .collect(Collectors.toCollection(LinkedHashSet::new));
        Set<String> missingAssignmentTargetServiceNames = targetServiceNames.stream()
                .filter(serviceName -> !assignmentsByService.containsKey(serviceName))
                .collect(Collectors.toCollection(LinkedHashSet::new));
        Set<String> adapterUnavailableTargetServiceNames = targetServiceNames.stream()
                .filter(serviceName -> {
                    RemoteServiceAssignment assignment = assignmentsByService.get(serviceName);
                    return assignment == null || !assignment.adapterAvailable();
                })
                .collect(Collectors.toCollection(LinkedHashSet::new));
        Set<String> nonExecutableTargetServiceNames = targetAssignments.stream()
                .filter(assignment -> assignment.adapterAvailable() && !assignment.adapterExecutable())
                .map(RemoteServiceAssignment::serviceName)
                .filter(value -> value != null && !value.isBlank())
                .collect(Collectors.toCollection(LinkedHashSet::new));
        Set<String> policyConfiguredTargetServiceNames = targetRemotePlans.stream()
                .filter(plan -> !isBlank(plan.compensationMaxAttempts())
                        || !isBlank(plan.compensationBackoffMillis())
                        || !isBlank(plan.compensationManualInterventionRequired()))
                .map(PhysicalRemotePlan::serviceName)
                .filter(value -> value != null && !value.isBlank())
                .collect(Collectors.toCollection(LinkedHashSet::new));
        Set<String> policyMissingTargetServiceNames = targetServiceNames.stream()
                .filter(serviceName -> !policyConfiguredTargetServiceNames.contains(serviceName))
                .collect(Collectors.toCollection(LinkedHashSet::new));
        policyMissingTargetServiceNames.stream()
                .map(target -> "Remote compensation target " + target
                        + " is missing recovery policy (binding="
                        + remoteCompensationTargetMissingBinding(target, "policy",
                                assignmentsByService.get(target), remotePlansByService.get(target))
                        + ", action=configureRemoteCompensationPolicy).")
                .forEach(deploymentErrors::add);
        Set<String> referenceImplementationTargetServiceNames = targetAssignments.stream()
                .filter(RemoteServiceAssignment::referenceImplementation)
                .map(RemoteServiceAssignment::serviceName)
                .filter(value -> value != null && !value.isBlank())
                .collect(Collectors.toCollection(LinkedHashSet::new));
        Set<String> externalImplementationTargetServiceNames = targetAssignments.stream()
                .filter(RemoteServiceAssignment::externalImplementation)
                .map(RemoteServiceAssignment::serviceName)
                .filter(value -> value != null && !value.isBlank())
                .collect(Collectors.toCollection(LinkedHashSet::new));
        metadata.put("remoteCompensationBindings", safeRules.entrySet().stream()
                .filter(entry -> entry.getKey() != null && !entry.getKey().isBlank())
                .flatMap(entry -> entry.getValue() == null
                        ? Stream.<String>empty()
                        : entry.getValue().stream()
                        .filter(target -> target != null && !target.isBlank())
                        .map(target -> remoteCompensationBinding(entry.getKey(), target,
                                assignmentsByService.get(target), remotePlansByService.get(target))))
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("remoteCompensationPolicyBindings", targetServiceNames.stream()
                .map(target -> remoteCompensationPolicyBinding(target,
                        assignmentsByService.get(target), remotePlansByService.get(target)))
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("remoteCompensationPolicyMissingBindings", policyMissingTargetServiceNames.stream()
                .map(target -> remoteCompensationPolicyBinding(target,
                        assignmentsByService.get(target), remotePlansByService.get(target)))
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        long executableTargetCount = executableTargetServiceNames.size();
        metadata.put("executableTargetCount", String.valueOf(executableTargetCount));
        metadata.put("executableTargetServiceNames", String.join(",", executableTargetServiceNames));
        metadata.put("executableTargetBindings", executableTargetServiceNames.stream()
                .map(target -> remoteCompensationTargetBinding(target,
                        assignmentsByService.get(target), remotePlansByService.get(target)))
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("executableTargetCoverage", coverage(executableTargetCount, targetServiceNames.size()));
        metadata.put("missingAssignmentTargetCount", String.valueOf(missingAssignmentTargetServiceNames.size()));
        metadata.put("missingAssignmentTargetServiceNames",
                String.join(",", missingAssignmentTargetServiceNames));
        metadata.put("missingAssignmentTargetBindings", missingAssignmentTargetServiceNames.stream()
                .map(target -> remoteCompensationTargetMissingBinding(target, "assignment",
                        assignmentsByService.get(target), remotePlansByService.get(target)))
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("adapterUnavailableTargetCount", String.valueOf(adapterUnavailableTargetServiceNames.size()));
        metadata.put("adapterUnavailableTargetServiceNames",
                String.join(",", adapterUnavailableTargetServiceNames));
        metadata.put("adapterUnavailableTargetBindings", adapterUnavailableTargetServiceNames.stream()
                .map(target -> remoteCompensationTargetMissingBinding(target, "adapterUnavailable",
                        assignmentsByService.get(target), remotePlansByService.get(target)))
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("nonExecutableTargetCount", String.valueOf(nonExecutableTargetServiceNames.size()));
        metadata.put("nonExecutableTargetServiceNames", String.join(",", nonExecutableTargetServiceNames));
        metadata.put("nonExecutableTargetBindings", nonExecutableTargetServiceNames.stream()
                .map(target -> remoteCompensationTargetMissingBinding(target, "nonExecutable",
                        assignmentsByService.get(target), remotePlansByService.get(target)))
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("referenceImplementationTargetCount",
                String.valueOf(referenceImplementationTargetServiceNames.size()));
        metadata.put("referenceImplementationTargetServiceNames",
                String.join(",", referenceImplementationTargetServiceNames));
        metadata.put("referenceImplementationTargetBindings", referenceImplementationTargetServiceNames.stream()
                .map(target -> remoteCompensationTargetBinding(target,
                        assignmentsByService.get(target), remotePlansByService.get(target)))
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("externalImplementationTargetCount",
                String.valueOf(externalImplementationTargetServiceNames.size()));
        metadata.put("externalImplementationTargetServiceNames",
                String.join(",", externalImplementationTargetServiceNames));
        metadata.put("externalImplementationTargetBindings", externalImplementationTargetServiceNames.stream()
                .map(target -> remoteCompensationTargetBinding(target,
                        assignmentsByService.get(target), remotePlansByService.get(target)))
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        long policyConfiguredTargetCount = policyConfiguredTargetServiceNames.size();
        metadata.put("policyConfiguredTargetCount", String.valueOf(policyConfiguredTargetCount));
        metadata.put("policyConfiguredTargetServiceNames",
                String.join(",", policyConfiguredTargetServiceNames));
        metadata.put("policyConfiguredTargetBindings", policyConfiguredTargetServiceNames.stream()
                .map(target -> remoteCompensationTargetBinding(target,
                        assignmentsByService.get(target), remotePlansByService.get(target)))
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("policyMissingTargetCount", String.valueOf(policyMissingTargetServiceNames.size()));
        metadata.put("policyMissingTargetServiceNames", String.join(",", policyMissingTargetServiceNames));
        metadata.put("policyMissingTargetBindings", policyMissingTargetServiceNames.stream()
                .map(target -> remoteCompensationTargetMissingBinding(target, "policy",
                        assignmentsByService.get(target), remotePlansByService.get(target)))
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("policyConfiguredCoverage", coverage(policyConfiguredTargetCount, targetServiceNames.size()));
        metadata.put("compensationMaxAttempts", targetRemotePlans.stream()
                .map(PhysicalRemotePlan::compensationMaxAttempts)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("compensationBackoffMillis", targetRemotePlans.stream()
                .map(PhysicalRemotePlan::compensationBackoffMillis)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put("manualInterventionRequiredValues", targetRemotePlans.stream()
                .map(PhysicalRemotePlan::compensationManualInterventionRequired)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        List<String> distinctErrors = deploymentErrors.stream()
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .toList();
        return new DeploymentValidationPlan("REMOTE_COMPENSATION", distinctErrors.isEmpty(), distinctErrors.size(),
                distinctErrors, metadata);
    }

    private String remoteCompensationBinding(String sourceServiceName,
                                             String targetServiceName,
                                             RemoteServiceAssignment assignment,
                                             PhysicalRemotePlan remotePlan) {
        String attempts = remotePlan == null ? null : remotePlan.compensationMaxAttempts();
        String backoff = remotePlan == null ? null : remotePlan.compensationBackoffMillis();
        String manual = remotePlan == null ? null : remotePlan.compensationManualInterventionRequired();
        boolean policyConfigured = remotePlan != null
                && (!isBlank(attempts) || !isBlank(backoff) || !isBlank(manual));
        return sourceServiceName
                + "->" + targetServiceName
                + ":physicalAdapter=" + valueOrDash(remotePlan == null ? null : remotePlan.adapterName())
                + ":physicalRole=" + valueOrDash(remotePlan == null ? null : remotePlan.adapterRole())
                + ":runtimeAdapter=" + valueOrDash(assignment == null ? null : assignment.adapterImplementationType())
                + ":runtimeRole=" + valueOrDash(assignment == null ? null : assignment.adapterRole())
                + ":available=" + (assignment != null && assignment.adapterAvailable())
                + ":executable=" + (assignment != null && assignment.adapterExecutable())
                + ":reference=" + (assignment != null && assignment.referenceImplementation())
                + ":external=" + (assignment != null && assignment.externalImplementation())
                + ":endpoint=" + blankAsDash(remotePlan == null ? "" : remotePlan.endpoint())
                + ":timeout=" + blankAsDash(remotePlan == null ? "" : remotePlan.timeoutMillis())
                + ":object=" + blankAsDash(remotePlan == null ? "" : remotePlan.objectType())
                + ":repository=" + blankAsDash(remotePlan == null ? "" : remotePlan.repositoryName())
                + ":repositoryAdapter=" + blankAsDash(remotePlan == null ? "" : remotePlan.repositoryAdapterName())
                + ":repositoryRole=" + blankAsDash(remotePlan == null ? "" : remotePlan.repositoryAdapterRole())
                + ":repositoryAppDdl=" + (remotePlan != null && remotePlan.repositoryAppDdlTables())
                + ":storage=" + blankAsDash(remotePlan == null ? "" : remotePlan.repositoryStorageTableName())
                + ":datasource=" + blankAsDash(remotePlan == null ? "" : remotePlan.repositoryDatasourceUrl())
                + ":repositoryDriver=" + blankAsDash(remotePlan == null ? "" : remotePlan.repositoryDriverClassName())
                + ":policy=" + policyConfigured
                + ":attempts=" + valueOrDash(attempts)
                + ":backoff=" + valueOrDash(backoff)
                + ":manual=" + valueOrDash(manual);
    }

    private String remoteCompensationPolicyBinding(String targetServiceName,
                                                   RemoteServiceAssignment assignment,
                                                   PhysicalRemotePlan remotePlan) {
        String attempts = remotePlan == null ? null : remotePlan.compensationMaxAttempts();
        String backoff = remotePlan == null ? null : remotePlan.compensationBackoffMillis();
        String manual = remotePlan == null ? null : remotePlan.compensationManualInterventionRequired();
        boolean policyConfigured = remotePlan != null
                && (!isBlank(attempts) || !isBlank(backoff) || !isBlank(manual));
        return targetServiceName
                + ":configured=" + policyConfigured
                + ":attempts=" + valueOrDash(attempts)
                + ":backoff=" + valueOrDash(backoff)
                + ":manual=" + valueOrDash(manual)
                + ":actions=" + (policyConfigured ? "-" : "configureRemoteCompensationPolicy")
                + ":physicalAdapter=" + valueOrDash(remotePlan == null ? null : remotePlan.adapterName())
                + ":physicalRole=" + valueOrDash(remotePlan == null ? null : remotePlan.adapterRole())
                + ":runtimeAdapter=" + valueOrDash(assignment == null ? null : assignment.adapterImplementationType())
                + ":runtimeRole=" + valueOrDash(assignment == null ? null : assignment.adapterRole())
                + ":available=" + (assignment != null && assignment.adapterAvailable())
                + ":executable=" + (assignment != null && assignment.adapterExecutable())
                + ":reference=" + (assignment != null && assignment.referenceImplementation())
                + ":external=" + (assignment != null && assignment.externalImplementation());
    }

