    private String currentSnapshotAppDdlKeyStrictError(AppSemanticMigrationPlan plan) {
        if (plan == null || isBlank(plan.serviceName())) {
            return "";
        }
        if (closedCurrentSnapshotContext(plan)) {
            return "";
        }
        List<String> missingReasons = new ArrayList<>();
        if (!plan.objectKeyAppDdlDerived()) {
            missingReasons.add("appDdlDerived");
        }
        if (plan.objectKeyEscapeHatch()) {
            missingReasons.add("escapeHatchClear");
        }
        if (!plan.appDdlObjectKeyPushdown()) {
            missingReasons.add("appDdlObjectKeyPushdown");
        }
        String action = "declareAppDdlPrimaryKeyOrNamedIndex+pushCurrentObjectKeyToAppDdlColumns";
        return "Current snapshot " + valueOrDash(plan.objectType())
                + " on service " + plan.serviceName()
                + " is not covered by APP DDL key under strictCurrentSnapshotAppDdlKey"
                + " (reason=" + valueOrDash(String.join("+", missingReasons))
                + ", missing=" + valueOrDash(String.join("+", missingReasons))
                + ", keySource=" + valueOrDash(plan.objectKeySource())
                + ", index=" + valueOrDash(plan.objectKeyAppDdlIndexName())
                + ", paths=" + valueOrDash(String.join("+", plan.paths()))
                + ", appDdlPaths=" + valueOrDash(String.join("+", plan.appDdlObjectKeyPaths()))
                + ", columns=" + valueOrDash(String.join("+", plan.objectKeyColumns()))
                + ", externalRoots=" + valueOrDash(String.join("+", plan.externalObjectKeyRoots()))
                + ", actions=" + action
                + ", action=" + action + ").";
    }

    private static String remoteExternalEndpointReadinessReason(PhysicalRemotePlan plan) {
        if (plan == null || isBlankStatic(plan.endpoint())) {
            return "endpoint";
        }
        if (!isAbsoluteHttpEndpoint(plan.endpoint())) {
            return "endpointInvalid";
        }
        if (remoteExternalDevelopmentEndpoint(plan.endpoint())) {
            return "developmentEndpoint";
        }
        if (remoteExternalPlaceholderEndpoint(plan.endpoint())) {
            return "placeholderEndpoint";
        }
        return "-";
    }

    private static boolean remoteExternalDevelopmentEndpoint(String endpoint) {
        if (isBlankStatic(endpoint)) {
            return false;
        }
        try {
            URI uri = URI.create(endpoint);
            String host = uri.getHost();
            if (host == null || host.isBlank()) {
                return false;
            }
            String normalizedHost = host.toLowerCase(Locale.ROOT);
            return "localhost".equals(normalizedHost)
                    || "127.0.0.1".equals(normalizedHost)
                    || "0.0.0.0".equals(normalizedHost)
                    || "::1".equals(normalizedHost);
        } catch (IllegalArgumentException e) {
            return false;
        }
    }

    private static boolean remoteExternalPlaceholderEndpoint(String endpoint) {
        if (isBlankStatic(endpoint)) {
            return false;
        }
        try {
            URI uri = URI.create(endpoint);
            String host = uri.getHost();
            if (host == null || host.isBlank()) {
                return false;
            }
            String normalizedHost = host.toLowerCase(Locale.ROOT);
            return "example.test".equals(normalizedHost)
                    || normalizedHost.endsWith(".example.test")
                    || "example.com".equals(normalizedHost)
                    || normalizedHost.endsWith(".example.com");
        } catch (IllegalArgumentException e) {
            return false;
        }
    }

    private static boolean repositoryReplacementReady(RepositoryQueryPlan plan) {
        return plan != null
                && plan.appDdlDerived()
                && plan.appDdlColumnPushdown()
                && !plan.escapeHatch();
    }

    private String repositoryRelationServiceNames(List<RepositoryQueryPlan> plans, String relationKind) {
        return plans.stream()
                .filter(plan -> relationKind.equals(plan.aggregateRelationKind()))
                .map(RepositoryQueryPlan::serviceName)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(","));
    }

    private String repositoryAggregateRelationBinding(RepositoryQueryPlan plan) {
        if (plan == null || isBlank(plan.serviceName())) {
            return "";
        }
        return plan.serviceName()
                + ":" + valueOrDash(plan.objectType())
                + ":relation=" + valueOrDash(plan.aggregateRelationKind())
                + ":lookup=" + valueOrDash(plan.repositoryLookupKind())
                + ":collection=" + plan.collectionQuery()
                + ":composite=" + plan.compositeRepositoryKey()
                + ":crossKeys=" + plan.crossAggregateKeyCount()
                + ":index=" + valueOrDash(plan.appDdlIndexName())
                + ":externalRoots=" + valueOrDash(joinNonBlank(plan.externalAggregateRoots(), "+"))
                + ":columns=" + valueOrDash(joinNonBlank(plan.repositoryColumns(), "+"));
    }

    private String repositoryExternalAggregateRootBindings(List<RepositoryQueryPlan> plans) {
        Map<String, List<RepositoryQueryPlan>> plansByRootSet = new LinkedHashMap<>();
        for (RepositoryQueryPlan plan : plans) {
            String roots = joinNonBlank(plan.externalAggregateRoots(), "+");
            if (roots.isBlank()) {
                continue;
            }
            plansByRootSet.computeIfAbsent(roots, ignored -> new ArrayList<>()).add(plan);
        }
        return plansByRootSet.entrySet().stream()
                .map(entry -> entry.getKey()
                        + ":services=" + entry.getValue().stream()
                        .map(RepositoryQueryPlan::serviceName)
                        .filter(value -> value != null && !value.isBlank())
                        .distinct()
                        .collect(Collectors.joining("+"))
                        + ":objects=" + entry.getValue().stream()
                        .map(RepositoryQueryPlan::objectType)
                        .filter(value -> value != null && !value.isBlank())
                        .distinct()
                        .collect(Collectors.joining("+"))
                        + ":relations=" + entry.getValue().stream()
                        .map(RepositoryQueryPlan::aggregateRelationKind)
                        .filter(value -> value != null && !value.isBlank())
                        .distinct()
                        .collect(Collectors.joining("+"))
                        + ":lookups=" + entry.getValue().stream()
                        .map(RepositoryQueryPlan::repositoryLookupKind)
                        .filter(value -> value != null && !value.isBlank())
                        .distinct()
                        .collect(Collectors.joining("+"))
                        + ":indexes=" + entry.getValue().stream()
                        .map(RepositoryQueryPlan::appDdlIndexName)
                        .filter(value -> value != null && !value.isBlank())
                        .distinct()
                        .collect(Collectors.joining("+"))
                        + ":columns=" + entry.getValue().stream()
                        .flatMap(plan -> plan.repositoryColumns().stream())
                        .filter(value -> value != null && !value.isBlank())
                        .distinct()
                        .collect(Collectors.joining("+")))
                .collect(Collectors.joining(","));
    }

