    private boolean remainingAppSemanticMigrationAction(AppSemanticMigrationPlan plan) {
        return remainingAppSemanticMigrationAction(plan, generatedRoleParticipantPlans);
    }

    private boolean remainingAppSemanticMigrationAction(AppSemanticMigrationPlan plan,
                                                       List<RoleParticipantPlan> roleParticipantPlans) {
        return remainingAppSemanticMigrationAction(plan, roleParticipantPlans, Set.of());
    }

    private boolean remainingAppSemanticMigrationAction(AppSemanticMigrationPlan plan,
                                                       List<RoleParticipantPlan> roleParticipantPlans,
                                                       Set<String> roleOnlyReadyServiceParticipantPaths) {
        if (plan == null) {
            return false;
        }
        if ("APP_DDL_PLATFORM_PRIMARY_KEY".equals(plan.migrationType())
                && appDdlPlatformPrimaryKeyClosedIdentity(plan.identityKind())) {
            return false;
        }
        if ("APP_DDL_PLATFORM_PRIMARY_KEY".equals(plan.migrationType())
                && appDdlPlatformPrimaryKeyResolvedByRoleIdentity(plan, roleParticipantPlans)) {
            return false;
        }
        if ("SERVICE_NON_ROLE_PARTICIPANT".equals(plan.migrationType())
                && serviceParticipantPathsRoleOnlyReady(plan, roleOnlyReadyServiceParticipantPaths)) {
            return false;
        }
        return "OBJECT_BACKED_PRIMARY_KEY".equals(plan.migrationType())
                || "APP_DDL_PLATFORM_PRIMARY_KEY".equals(plan.migrationType())
                || "OBJECT_BACKED_INDEX".equals(plan.migrationType())
                || "SPP_TECHNICAL_FIELD_PLATFORM_COLUMN".equals(plan.migrationType())
                || "REPOSITORY_ESCAPE_HATCH".equals(plan.migrationType())
                || "SNAPSHOT_ESCAPE_HATCH".equals(plan.migrationType())
                || "REMOTE_REFERENCE_ADAPTER".equals(plan.migrationType())
                || "SERVICE_NON_ROLE_PARTICIPANT".equals(plan.migrationType())
                || "QUANTUM_SERVICE_INTERNAL_PROTOCOL".equals(plan.migrationType());
    }

    private Set<String> roleOnlyReadyServiceParticipantPaths(
            List<ServiceParticipantRoleOnlyMigrationActionPlan> plans) {
        if (plans == null || plans.isEmpty()) {
            return Set.of();
        }
        return plans.stream()
                .filter(ServiceParticipantRoleOnlyMigrationActionPlan::roleOnlyReady)
                .map(ServiceParticipantRoleOnlyMigrationActionPlan::path)
                .filter(value -> value != null && !value.isBlank())
                .collect(Collectors.toUnmodifiableSet());
    }

    private boolean serviceParticipantPathsRoleOnlyReady(
            AppSemanticMigrationPlan plan, Set<String> roleOnlyReadyServiceParticipantPaths) {
        if (plan == null || plan.paths() == null || plan.paths().isEmpty()
                || roleOnlyReadyServiceParticipantPaths == null || roleOnlyReadyServiceParticipantPaths.isEmpty()) {
            return false;
        }
        return roleOnlyReadyServiceParticipantPaths.containsAll(plan.paths());
    }

    private static boolean appDdlPlatformPrimaryKeyResolvedByRoleIdentity(
            AppSemanticMigrationPlan plan, List<RoleParticipantPlan> roleParticipantPlans) {
        String identityKind = appDdlPlatformPrimaryKeyIdentityKind(plan, roleParticipantPlans);
        return appDdlPlatformPrimaryKeyClosedIdentityStatic(identityKind);
    }

    private static boolean appDdlPlatformPrimaryKeyClosedIdentityStatic(String identityKind) {
        return "ROLE_PERFORMER_IDENTITY".equals(identityKind)
                || "COMPOSITION_IDENTITY".equals(identityKind)
                || "BUSINESS_FIELD_IDENTITY".equals(identityKind);
    }

    private static String appDdlPlatformPrimaryKeyIdentityKinds(List<AppSemanticMigrationPlan> plans,
                                                               List<RoleParticipantPlan> roleParticipantPlans) {
        List<AppSemanticMigrationPlan> safePlans = plans == null ? List.of() : plans;
        return safePlans.stream()
                .map(plan -> appDdlPlatformPrimaryKeyIdentityKind(plan, roleParticipantPlans))
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(","));
    }

    private static long appDdlPlatformPrimaryKeyIdentityKindCount(List<AppSemanticMigrationPlan> plans,
                                                                 List<RoleParticipantPlan> roleParticipantPlans,
                                                                 String identityKind) {
        List<AppSemanticMigrationPlan> safePlans = plans == null ? List.of() : plans;
        return safePlans.stream()
                .filter(plan -> identityKind.equals(appDdlPlatformPrimaryKeyIdentityKind(plan,
                        roleParticipantPlans)))
                .count();
    }

    private static String appDdlPlatformPrimaryKeyIdentityKindTableNames(List<AppSemanticMigrationPlan> plans,
                                                                        List<RoleParticipantPlan> roleParticipantPlans,
                                                                        String identityKind) {
        List<AppSemanticMigrationPlan> safePlans = plans == null ? List.of() : plans;
        return safePlans.stream()
                .filter(plan -> identityKind.equals(appDdlPlatformPrimaryKeyIdentityKind(plan,
                        roleParticipantPlans)))
                .map(AppSemanticMigrationPlan::tableName)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(","));
    }

    private static String appDdlPlatformPrimaryKeyIdentityKindBindings(List<AppSemanticMigrationPlan> plans,
                                                                      List<RoleParticipantPlan> roleParticipantPlans) {
        List<AppSemanticMigrationPlan> safePlans = plans == null ? List.of() : plans;
        return safePlans.stream()
                .map(plan -> appDdlPlatformPrimaryKeyIdentityKindBinding(plan, roleParticipantPlans))
                .filter(value -> value != null && !value.isBlank())
                .collect(Collectors.joining(";"));
    }

    private static String appDdlPlatformPrimaryKeyIdentityKindBinding(AppSemanticMigrationPlan plan,
                                                                     List<RoleParticipantPlan> roleParticipantPlans) {
        if (plan == null) {
            return "";
        }
        RoleParticipantPlan roleParticipant = appDdlPlatformPrimaryKeyRelatedRoleParticipant(plan,
                roleParticipantPlans);
        String identityKind = appDdlPlatformPrimaryKeyIdentityKind(plan, roleParticipantPlans);
        return blankAsDash(plan.tableName())
                + ":object=" + blankAsDash(plan.objectType())
                + ":paths=" + blankAsDash(String.join("+", plan.paths()))
                + ":identityKind=" + identityKind
                + ":role=" + blankAsDash(roleParticipant == null ? "" : roleParticipant.roleType())
                + ":roleTable=" + blankAsDash(roleParticipant == null ? "" : roleParticipant.roleTableName())
                + ":roleColumns=" + blankAsDash(roleParticipant == null
                ? "" : String.join("+", roleParticipant.platformColumns()));
    }

    private static String appDdlPlatformPrimaryKeyIdentityKind(AppSemanticMigrationPlan plan,
                                                              List<RoleParticipantPlan> roleParticipantPlans) {
        if (plan != null && plan.identityKind() != null && !plan.identityKind().isBlank()) {
            return plan.identityKind();
        }
        RoleParticipantPlan exactRoleParticipant = appDdlPlatformPrimaryKeyRoleParticipant(plan,
                roleParticipantPlans);
        if (exactRoleParticipant != null) {
            return "ROLE_PERFORMER_IDENTITY";
        }
        RoleParticipantPlan compositionRoleParticipant = appDdlPlatformPrimaryKeyCompositionRoleParticipant(plan,
                roleParticipantPlans);
        return compositionRoleParticipant == null ? "SIDECAR_PLATFORM_IDENTITY" : "COMPOSITION_IDENTITY";
    }

    private static RoleParticipantPlan appDdlPlatformPrimaryKeyRoleParticipant(AppSemanticMigrationPlan plan,
                                                                              List<RoleParticipantPlan> roleParticipantPlans) {
        if (plan == null || roleParticipantPlans == null || roleParticipantPlans.isEmpty()) {
            return null;
        }
        List<String> pathColumns = appDdlPlatformPrimaryKeyPathColumns(plan);
        if (pathColumns.isEmpty()) {
            return null;
        }
        return roleParticipantPlans.stream()
                .filter(rolePlan -> rolePlan != null
                        && matchesAppDdlPlatformPrimaryKeyRoleParticipant(plan, rolePlan, pathColumns))
                .findFirst()
                .orElse(null);
    }

    private static RoleParticipantPlan appDdlPlatformPrimaryKeyCompositionRoleParticipant(
            AppSemanticMigrationPlan plan, List<RoleParticipantPlan> roleParticipantPlans) {
        if (plan == null || roleParticipantPlans == null || roleParticipantPlans.isEmpty()) {
            return null;
        }
        List<String> pathColumns = appDdlPlatformPrimaryKeyPathColumns(plan);
        if (pathColumns.isEmpty()) {
            return null;
        }
        return roleParticipantPlans.stream()
                .filter(rolePlan -> rolePlan != null
                        && matchesAppDdlPlatformPrimaryKeyComposition(plan, rolePlan, pathColumns))
                .findFirst()
                .orElse(null);
    }

    private static RoleParticipantPlan appDdlPlatformPrimaryKeyRelatedRoleParticipant(
            AppSemanticMigrationPlan plan, List<RoleParticipantPlan> roleParticipantPlans) {
        RoleParticipantPlan exact = appDdlPlatformPrimaryKeyRoleParticipant(plan, roleParticipantPlans);
        return exact == null ? appDdlPlatformPrimaryKeyCompositionRoleParticipant(plan, roleParticipantPlans) : exact;
    }

    private static boolean matchesAppDdlPlatformPrimaryKeyRoleParticipant(AppSemanticMigrationPlan plan,
                                                                         RoleParticipantPlan rolePlan,
                                                                         List<String> pathColumns) {
        boolean tableMatches = plan.tableName() != null
                && !plan.tableName().isBlank()
                && plan.tableName().equals(rolePlan.roleTableName());
        boolean typeMatches = plan.objectType() != null
                && !plan.objectType().isBlank()
                && plan.objectType().equals(rolePlan.roleType());
        return (tableMatches || typeMatches)
                && !rolePlan.platformColumns().isEmpty()
                && rolePlan.platformColumns().containsAll(pathColumns);
    }

    private static boolean matchesAppDdlPlatformPrimaryKeyComposition(AppSemanticMigrationPlan plan,
                                                                      RoleParticipantPlan rolePlan,
                                                                      List<String> pathColumns) {
        boolean tableMatches = plan.tableName() != null
                && !plan.tableName().isBlank()
                && plan.tableName().equals(rolePlan.roleTableName());
        boolean typeMatches = plan.objectType() != null
                && !plan.objectType().isBlank()
                && plan.objectType().equals(rolePlan.roleType());
        return (tableMatches || typeMatches)
                && !rolePlan.platformColumns().isEmpty()
                && pathColumns.containsAll(rolePlan.platformColumns())
                && pathColumns.size() > rolePlan.platformColumns().size();
    }

    private static List<String> appDdlPlatformPrimaryKeyPathColumns(AppSemanticMigrationPlan plan) {
        if (plan == null || plan.paths() == null || plan.paths().isEmpty()) {
            return List.of();
        }
        return plan.paths().stream()
                .map(LocalGeneratedServiceRuntime::appDdlPlatformPrimaryKeyPathColumn)
                .filter(value -> value != null && !value.isBlank())
                .toList();
    }

    private static String appDdlPlatformPrimaryKeyPathColumn(String path) {
        if (path == null || path.isBlank()) {
            return "";
        }
        int dot = path.lastIndexOf('.');
        return dot >= 0 && dot + 1 < path.length() ? path.substring(dot + 1) : path;
    }

    private void putServiceParticipantCategoryMetadata(Map<String, String> metadata,
                                                       String prefix,
                                                       List<AppSemanticMigrationPlan> plans,
                                                       String appDdlCategory) {
        List<ServiceParticipantMigrationEntry> entries = serviceParticipantMigrationEntries(plans).stream()
                .filter(entry -> appDdlCategory.equals(appDdlCategoryForBusinessType(entry.participantType())))
                .toList();
        putServiceParticipantEntryMetadata(metadata, prefix, entries);
    }

    private void putServiceParticipantReferenceMetadata(Map<String, String> metadata,
                                                        String prefix,
                                                        List<AppSemanticMigrationPlan> plans) {
        List<ServiceParticipantMigrationEntry> entries = serviceParticipantMigrationEntries(plans).stream()
                .filter(entry -> "references".equals(entry.category()) || entry.category().isBlank())
                .toList();
        putServiceParticipantEntryMetadata(metadata, prefix, entries);
    }

    private void putServiceParticipantTargetKindMetadata(Map<String, String> metadata,
                                                         String prefix,
                                                         List<AppSemanticMigrationPlan> plans,
                                                         String targetKind) {
        List<AppSemanticMigrationPlan> matchingPlans = plans == null
                ? List.of()
                : plans.stream()
                        .filter(plan -> plan != null && targetKind.equals(plan.targetKind()))
                        .toList();
        metadata.put(prefix + "Count", String.valueOf(matchingPlans.size()));
        metadata.put(prefix + "ServiceNames", serviceNames(matchingPlans));
        metadata.put(prefix + "Paths", migrationPaths(matchingPlans));
        metadata.put(prefix + "Bindings", appSemanticMigrationBindings(matchingPlans));
    }

    private void putServiceParticipantEntryMetadata(Map<String, String> metadata,
                                                    String prefix,
                                                    List<ServiceParticipantMigrationEntry> entries) {
        List<ServiceParticipantMigrationEntry> safeEntries = entries == null ? List.of() : List.copyOf(entries);
        metadata.put(prefix + "Count", String.valueOf(safeEntries.size()));
        metadata.put(prefix + "ServiceNames", safeEntries.stream()
                .map(ServiceParticipantMigrationEntry::serviceName)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put(prefix + "Types", safeEntries.stream()
                .map(ServiceParticipantMigrationEntry::participantType)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put(prefix + "CategorySources", safeEntries.stream()
                .map(ServiceParticipantMigrationEntry::categorySource)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put(prefix + "Paths", safeEntries.stream()
                .map(ServiceParticipantMigrationEntry::path)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
        metadata.put(prefix + "Bindings", safeEntries.stream()
                .map(this::serviceParticipantMigrationEntryBinding)
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(",")));
    }

    private List<ServiceParticipantRoleOnlyMigrationActionPlan> serviceParticipantRoleOnlyMigrationActionPlans(
            List<AppSemanticMigrationPlan> generatedAppSemanticMigrationPlans,
            List<AppSemanticMigrationPlan> appSemanticMigrationPlans,
            List<TransactionSnapshotPlan> transactionSnapshotPlans,
            List<GeneratedServiceMetadata> serviceMetadata,
            List<RepositoryQueryPlan> repositoryQueryPlans,
            List<ObjectSnapshotPlan> objectSnapshotPlans,
            List<QuantumAccessPlan> quantumAccessPlans,
            List<RemoteServiceAssignment> remoteAssignments) {
        List<AppSemanticMigrationPlan> safeGeneratedPlans = generatedAppSemanticMigrationPlans == null
                ? List.of()
                : List.copyOf(generatedAppSemanticMigrationPlans);
        List<AppSemanticMigrationPlan> safePlans = appSemanticMigrationPlans == null
                ? List.of()
                : List.copyOf(appSemanticMigrationPlans);
        Set<String> externalRemoteServiceNames = safePlans.stream()
                .filter(plan -> "REMOTE_EXTERNAL_ADAPTER".equals(plan.migrationType()))
                .map(AppSemanticMigrationPlan::serviceName)
                .filter(value -> value != null && !value.isBlank())
                .collect(Collectors.toCollection(LinkedHashSet::new));
        Set<String> transactionSnapshotServiceNames = transactionSnapshotPlans == null
                ? Set.of()
                : transactionSnapshotPlans.stream()
                        .map(TransactionSnapshotPlan::serviceName)
                        .filter(value -> value != null && !value.isBlank())
                        .collect(Collectors.toCollection(LinkedHashSet::new));
        Set<String> closedCurrentContextKeys = safePlans.stream()
                .filter(this::closedCurrentSnapshotContext)
                .map(this::currentSnapshotContextKey)
                .collect(Collectors.toCollection(LinkedHashSet::new));
        Map<String, RemoteServiceAssignment> remoteAssignmentsByService =
                (remoteAssignments == null ? List.<RemoteServiceAssignment>of() : remoteAssignments).stream()
                        .collect(Collectors.toMap(RemoteServiceAssignment::serviceName, Function.identity(),
                                (first, second) -> first, LinkedHashMap::new));
        List<AppSemanticMigrationPlan> activeServiceParticipantPlans = safeGeneratedPlans.stream()
                .filter(plan -> "SERVICE_NON_ROLE_PARTICIPANT".equals(plan.migrationType()))
                .filter(plan -> !suppressedGeneratedAppSemanticMigrationPlan(plan, externalRemoteServiceNames,
                        transactionSnapshotServiceNames, closedCurrentContextKeys))
                .toList();
        Set<String> roleParticipantRequestServiceNames =
                roleParticipantRequestBindings(serviceMetadata, generatedRoleParticipantPlans,
                        remoteAssignmentsByService).stream()
                        .map(RoleParticipantRequestBindingPlan::serviceName)
                        .filter(value -> value != null && !value.isBlank())
                        .collect(Collectors.toCollection(LinkedHashSet::new));
        List<RoleParticipantRequestBindingPlan> requestBindings =
                roleParticipantRequestBindings(serviceMetadata, generatedRoleParticipantPlans,
                        remoteAssignmentsByService);
        Map<String, List<RoleParticipantRequestBindingPlan>> requestBindingsByService = requestBindings.stream()
                .collect(Collectors.groupingBy(RoleParticipantRequestBindingPlan::serviceName,
                        LinkedHashMap::new, Collectors.toList()));
        Map<String, List<RoleParticipantRequestBindingPlan>> sagaContractRequestBindingsByTarget =
                sagaContractRequestBindingsByTarget(serviceMetadata, requestBindingsByService);
        List<RoleParticipantPlan> roleParticipantPlans = generatedRoleParticipantPlans == null
                ? List.of()
                : List.copyOf(generatedRoleParticipantPlans);
        return serviceParticipantMigrationEntries(activeServiceParticipantPlans).stream()
                .map(entry -> {
                    String action = serviceParticipantRoleOnlyMigrationAction(entry, repositoryQueryPlans,
                            objectSnapshotPlans, quantumAccessPlans, remoteAssignments);
                    List<RoleParticipantRequestBindingPlan> serviceRoleBindings =
                            serviceParticipantRoleBindings(entry, action, requestBindingsByService,
                                    sagaContractRequestBindingsByTarget);
                    if ("CONTRACT_CONTEXT_TO_ROLE_SIGNED_SCENARIO".equals(action)) {
                        serviceRoleBindings = scenarioBoundaryRoleBindings(serviceRoleBindings);
                    }
                    boolean roleParticipantPresent = roleParticipantRequestServiceNames.contains(entry.serviceName())
                            || !serviceRoleBindings.isEmpty();
                    List<String> targetRoleTypes = serviceParticipantTargetRoleTypes(entry, action,
                            serviceRoleBindings, roleParticipantPlans);
                    List<String> targetRoleParameterNames = serviceParticipantTargetRoleParameterNames(
                            targetRoleTypes, serviceRoleBindings);
                    List<String> targetRoleBindings = serviceParticipantTargetRoleBindings(
                            targetRoleTypes, serviceRoleBindings);
                    List<String> candidateRoleTypes = serviceParticipantCandidateRoleTypes(entry, action,
                            roleParticipantPlans);
                    boolean targetRolePresent = !targetRoleTypes.isEmpty()
                            && !targetRoleParameterNames.isEmpty();
                    boolean adapterReady = serviceParticipantAdapterBoundaryReady(action);
                    boolean roleOnlyReadyAfterAction = adapterReady
                            || (roleParticipantPresent
                            && targetRolePresent
                            && !"REFERENCE_TO_REMOTE_ROLE_ADAPTER".equals(action));
                    List<String> readinessReasons = adapterReady
                            ? serviceParticipantAdapterBoundaryReadinessReasons(action)
                            : serviceParticipantRoleOnlyMigrationActionReadinessReasonList(
                            roleOnlyReadyAfterAction, roleParticipantPresent, targetRolePresent, action);
                    return new ServiceParticipantRoleOnlyMigrationActionPlan(entry.serviceName(), entry.path(),
                            entry.participantType(), entry.category(), action, roleParticipantPresent,
                            targetRolePresent, targetRoleTypes, targetRoleParameterNames, targetRoleBindings,
                            candidateRoleTypes, roleOnlyReadyAfterAction, readinessReasons,
                            String.join("+", readinessReasons),
                            serviceParticipantRoleOnlyMigrationRecommendation(action, candidateRoleTypes));
                })
                .toList();
    }

    private List<RoleParticipantRequestBindingPlan> scenarioBoundaryRoleBindings(
            List<RoleParticipantRequestBindingPlan> bindings) {
        if (bindings == null || bindings.isEmpty()) {
            return List.of();
        }
        return bindings.stream()
                .filter(binding -> binding != null
                        && binding.roleParameterName() != null
                        && !binding.roleParameterName().isBlank()
                        && !binding.roleParameterName().contains("."))
                .toList();
    }

    private Map<String, List<RoleParticipantRequestBindingPlan>> sagaContractRequestBindingsByTarget(
            List<GeneratedServiceMetadata> serviceMetadata,
            Map<String, List<RoleParticipantRequestBindingPlan>> requestBindingsByService) {
        List<GeneratedServiceMetadata> safeServices = serviceMetadata == null ? List.of() : List.copyOf(serviceMetadata);
        if (safeServices.isEmpty() || requestBindingsByService == null || requestBindingsByService.isEmpty()
                || appDdlCatalog == null) {
            return Map.of();
        }
        Map<String, GeneratedServiceMetadata> servicesByName = safeServices.stream()
                .filter(service -> service.serviceName() != null && !service.serviceName().isBlank())
                .collect(Collectors.toMap(GeneratedServiceMetadata::serviceName, Function.identity(),
                        (first, second) -> first, LinkedHashMap::new));
        Map<String, List<RoleParticipantRequestBindingPlan>> bindingsByTarget = new LinkedHashMap<>();
        for (GeneratedServiceMetadata saga : safeServices) {
            if (saga == null || saga.serviceKind() != GeneratedServiceKind.SCENARIO
                    || saga.sagaTransactionCallServiceNames() == null
                    || saga.sagaTransactionCallServiceNames().isEmpty()) {
                continue;
            }
            List<ScenarioParameter> sagaContracts = scenarioParametersByCategory(saga, "contracts");
            List<RoleParticipantRequestBindingPlan> sagaRoleBindings =
                    requestBindingsByService.getOrDefault(saga.serviceName(), List.of());
            if (sagaContracts.isEmpty() || sagaRoleBindings.isEmpty()) {
                continue;
            }
            Set<String> sagaContractTypes = sagaContracts.stream()
                    .map(ScenarioParameter::typeName)
                    .filter(value -> value != null && !value.isBlank())
                    .collect(Collectors.toCollection(LinkedHashSet::new));
            for (String targetName : saga.sagaTransactionCallServiceNames()) {
                GeneratedServiceMetadata target = servicesByName.get(targetName);
                if (target == null || !serviceHasAnyContractParameter(target, sagaContractTypes)) {
                    continue;
                }
                bindingsByTarget.computeIfAbsent(targetName, ignored -> new ArrayList<>())
                        .addAll(sagaRoleBindings);
            }
        }
        return bindingsByTarget.entrySet().stream()
                .collect(Collectors.toMap(Map.Entry::getKey,
                        entry -> distinctRoleParticipantRequestBindings(entry.getValue()),
                        (first, second) -> first, LinkedHashMap::new));
    }

    private boolean serviceHasAnyContractParameter(GeneratedServiceMetadata service, Set<String> contractTypes) {
        if (service == null || contractTypes == null || contractTypes.isEmpty()) {
            return false;
        }
        List<String> parameterTypes = service.serviceParameterTypes() == null
                ? List.of()
                : service.serviceParameterTypes();
        return parameterTypes.stream()
                .map(this::simpleTypeName)
                .anyMatch(contractTypes::contains);
    }

    private List<RoleParticipantRequestBindingPlan> serviceParticipantRoleBindings(
            ServiceParticipantMigrationEntry entry,
            String action,
            Map<String, List<RoleParticipantRequestBindingPlan>> requestBindingsByService,
            Map<String, List<RoleParticipantRequestBindingPlan>> sagaContractRequestBindingsByTarget) {
        if (entry == null || entry.serviceName() == null || entry.serviceName().isBlank()) {
            return List.of();
        }
        List<RoleParticipantRequestBindingPlan> bindings = new ArrayList<>(
                requestBindingsByService == null
                        ? List.of()
                        : requestBindingsByService.getOrDefault(entry.serviceName(), List.of()));
        if ("CONTRACT_CONTEXT_TO_ROLE_SIGNED_SCENARIO".equals(action)
                && sagaContractRequestBindingsByTarget != null) {
            bindings.addAll(sagaContractRequestBindingsByTarget.getOrDefault(entry.serviceName(), List.of()));
        }
        return distinctRoleParticipantRequestBindings(bindings);
    }

    private List<RoleParticipantRequestBindingPlan> distinctRoleParticipantRequestBindings(
            List<RoleParticipantRequestBindingPlan> bindings) {
        if (bindings == null || bindings.isEmpty()) {
            return List.of();
        }
        Map<String, RoleParticipantRequestBindingPlan> distinct = new LinkedHashMap<>();
        for (RoleParticipantRequestBindingPlan binding : bindings) {
            if (binding == null) {
                continue;
            }
            String key = valueOrDash(binding.serviceName())
                    + "|" + valueOrDash(binding.roleType())
                    + "|" + valueOrDash(binding.roleParameterName());
            distinct.putIfAbsent(key, binding);
        }
        return List.copyOf(distinct.values());
    }

    private List<String> serviceParticipantTargetRoleTypes(ServiceParticipantMigrationEntry entry,
                                                           String action,
                                                           List<RoleParticipantRequestBindingPlan> serviceRoleBindings,
                                                           List<RoleParticipantPlan> roleParticipantPlans) {
        if (entry == null) {
            return List.of();
        }
        Set<String> serviceRoleTypes = serviceRoleBindings == null
                ? Set.of()
                : serviceRoleBindings.stream()
                        .map(RoleParticipantRequestBindingPlan::roleType)
                        .filter(value -> value != null && !value.isBlank())
                        .collect(Collectors.toCollection(LinkedHashSet::new));
        if ("CONTRACT_CONTEXT_TO_ROLE_SIGNED_SCENARIO".equals(action)) {
            return List.copyOf(serviceRoleTypes);
        }
        if ("KEEP_ROLE_PARTICIPANT".equals(action)) {
            return serviceRoleTypes.contains(entry.participantType())
                    ? List.of(entry.participantType())
                    : List.of();
        }
        if (!"ENTITY_TO_ROLE_PERFORMER_OR_REPOSITORY_QUERY".equals(action)) {
            return List.of();
        }
        return (roleParticipantPlans == null ? List.<RoleParticipantPlan>of() : roleParticipantPlans).stream()
                .filter(plan -> plan.performerTypes().contains(entry.participantType()))
                .map(RoleParticipantPlan::roleType)
                .filter(serviceRoleTypes::contains)
                .distinct()
                .toList();
    }

    private List<String> serviceParticipantCandidateRoleTypes(ServiceParticipantMigrationEntry entry,
                                                              String action,
                                                              List<RoleParticipantPlan> roleParticipantPlans) {
        if (entry == null) {
            return List.of();
        }
        if ("CONTRACT_CONTEXT_TO_ROLE_SIGNED_SCENARIO".equals(action)
                || "KEEP_ROLE_PARTICIPANT".equals(action)) {
            return List.of();
        }
        return (roleParticipantPlans == null ? List.<RoleParticipantPlan>of() : roleParticipantPlans).stream()
                .filter(plan -> plan.performerTypes().contains(entry.participantType()))
                .map(RoleParticipantPlan::roleType)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .toList();
    }

    private List<String> serviceParticipantTargetRoleParameterNames(
            List<String> targetRoleTypes,
            List<RoleParticipantRequestBindingPlan> serviceRoleBindings) {
        if (targetRoleTypes == null || targetRoleTypes.isEmpty()
                || serviceRoleBindings == null || serviceRoleBindings.isEmpty()) {
            return List.of();
        }
        Set<String> targets = new LinkedHashSet<>(targetRoleTypes);
        return serviceRoleBindings.stream()
                .filter(binding -> targets.contains(binding.roleType()))
                .map(RoleParticipantRequestBindingPlan::roleParameterName)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .toList();
    }

    private List<String> serviceParticipantTargetRoleBindings(
            List<String> targetRoleTypes,
            List<RoleParticipantRequestBindingPlan> serviceRoleBindings) {
        if (targetRoleTypes == null || targetRoleTypes.isEmpty()
                || serviceRoleBindings == null || serviceRoleBindings.isEmpty()) {
            return List.of();
        }
        Set<String> targets = new LinkedHashSet<>(targetRoleTypes);
        return serviceRoleBindings.stream()
                .filter(binding -> targets.contains(binding.roleType()))
                .map(this::roleParticipantRequestBinding)
                .filter(value -> !value.isBlank())
                .distinct()
                .toList();
    }

    private List<ServiceParticipantMigrationEntry> serviceParticipantMigrationEntries(
            List<AppSemanticMigrationPlan> plans) {
        if (plans == null || plans.isEmpty()) {
            return List.of();
        }
        List<ServiceParticipantMigrationEntry> entries = new ArrayList<>();
        for (AppSemanticMigrationPlan plan : plans) {
            if (plan == null || !"SERVICE_NON_ROLE_PARTICIPANT".equals(plan.migrationType())) {
                continue;
            }
            List<String> paths = plan.paths();
            for (int index = 0; index < paths.size(); index++) {
                String path = paths.get(index);
                String participantType = serviceParticipantType(path);
                if (participantType == null || participantType.isBlank()) {
                    continue;
                }
                entries.add(new ServiceParticipantMigrationEntry(plan.serviceName(), path, participantType,
                        serviceParticipantCategory(plan, index, participantType),
                        serviceParticipantCategorySource(plan, index, participantType)));
            }
        }
        return List.copyOf(entries);
    }

    private String serviceParticipantCategory(AppSemanticMigrationPlan plan, int pathIndex, String participantType) {
        if (plan != null && plan.participantCategories() != null && pathIndex >= 0
                && pathIndex < plan.participantCategories().size()) {
            String category = plan.participantCategories().get(pathIndex);
            if (category != null && !category.isBlank()) {
                return category;
            }
        }
        return appDdlCategoryForBusinessType(participantType);
    }

    private String serviceParticipantCategorySource(AppSemanticMigrationPlan plan, int pathIndex,
                                                    String participantType) {
        if (plan != null && plan.participantCategories() != null && pathIndex >= 0
                && pathIndex < plan.participantCategories().size()) {
            String category = plan.participantCategories().get(pathIndex);
            if (category != null && !category.isBlank()) {
                return "GENERATED_PARTICIPANT_CATEGORY";
            }
        }
        String fallbackCategory = appDdlCategoryForBusinessType(participantType);
        if (fallbackCategory != null && !fallbackCategory.isBlank()) {
            return "APP_DDL_CATEGORY_FALLBACK";
        }
        return "UNKNOWN";
    }

    private String serviceParticipantType(String path) {
        if (path == null || path.isBlank()) {
            return "";
        }
        int colon = path.lastIndexOf(':');
        if (colon < 0 || colon == path.length() - 1) {
            return "";
        }
        String typeName = path.substring(colon + 1).trim();
        while (typeName.endsWith("[]")) {
            typeName = typeName.substring(0, typeName.length() - 2);
        }
        return typeName;
    }

    private String appDdlCategoryForBusinessType(String businessType) {
        if (businessType == null || businessType.isBlank() || appDdlCatalog == null) {
            return "";
        }
        return appDdlCatalog.tableForBusinessType(businessType)
                .map(AppDdlCatalog.Table::category)
                .orElse("");
    }

    private String serviceParticipantMigrationEntryBinding(ServiceParticipantMigrationEntry entry) {
        if (entry == null || entry.path() == null || entry.path().isBlank()) {
            return "";
        }
        return valueOrDash(entry.serviceName())
                + ":" + entry.participantType()
                + ":category=" + valueOrDash(entry.category())
                + ":path=" + entry.path()
                + ":categorySource=" + valueOrDash(entry.categorySource());
    }

    private boolean serviceParticipantRoleOnlyReady(
            ServiceParticipantMigrationEntry entry,
            Map<String, ServiceParticipantRoleOnlyMigrationActionPlan> roleOnlyMigrationActionPlansByPath) {
        if (entry == null || entry.path() == null || entry.path().isBlank()
                || roleOnlyMigrationActionPlansByPath == null || roleOnlyMigrationActionPlansByPath.isEmpty()) {
            return false;
        }
        ServiceParticipantRoleOnlyMigrationActionPlan plan = roleOnlyMigrationActionPlansByPath.get(entry.path());
        return plan != null && plan.roleOnlyReady();
    }

    private String serviceParticipantRoleOnlyError(ServiceParticipantMigrationEntry entry,
                                                   ServiceParticipantRoleOnlyMigrationActionPlan actionPlan) {
        if (entry == null || entry.serviceName() == null || entry.serviceName().isBlank()) {
            return "";
        }
        String base = "Service/scenario " + entry.serviceName()
                + " participant " + valueOrDash(entry.path())
                + " (" + valueOrDash(entry.participantType()) + ") must be a Role participant";
        if (actionPlan == null) {
            return base;
        }
        return base
                + "; action=" + valueOrDash(actionPlan.migrationAction())
                + "; roleOnlyReady=" + actionPlan.roleOnlyReady()
                + "; targetRoles=" + valueOrDash(String.join("+", actionPlan.targetRoleTypes()))
                + "; targetRoleParams=" + valueOrDash(String.join("+", actionPlan.targetRoleParameterNames()))
                + "; candidateRoles=" + valueOrDash(String.join("+", actionPlan.candidateRoleTypes()))
                + "; reasons=" + serviceParticipantRoleOnlyMigrationActionReadinessReasons(actionPlan);
    }

    private String serviceParticipantRoleOnlyError(ServiceParticipantRoleOnlyMigrationActionPlan actionPlan) {
        if (actionPlan == null || actionPlan.serviceName() == null || actionPlan.serviceName().isBlank()) {
            return "";
        }
        String base = "Service/scenario " + actionPlan.serviceName()
                + " participant " + valueOrDash(actionPlan.path())
                + " (" + valueOrDash(actionPlan.participantType()) + ") must be a Role participant";
        return base
                + "; action=" + valueOrDash(actionPlan.migrationAction())
                + "; roleOnlyReady=" + actionPlan.roleOnlyReady()
                + "; targetRoles=" + valueOrDash(String.join("+", actionPlan.targetRoleTypes()))
                + "; targetRoleParams=" + valueOrDash(String.join("+", actionPlan.targetRoleParameterNames()))
                + "; candidateRoles=" + valueOrDash(String.join("+", actionPlan.candidateRoleTypes()))
                + "; reasons=" + serviceParticipantRoleOnlyMigrationActionReadinessReasons(actionPlan);
    }

    private String serviceParticipantRoleOnlyMigrationAction(ServiceParticipantMigrationEntry entry) {
        if (entry == null) {
            return "";
        }
        String category = entry.category();
        if ("contracts".equals(category)) {
            return "CONTRACT_CONTEXT_TO_ROLE_SIGNED_SCENARIO";
        }
        if ("entities".equals(category)) {
            return "ENTITY_TO_ROLE_PERFORMER_OR_REPOSITORY_QUERY";
        }
        if ("roles".equals(category)) {
            return "KEEP_ROLE_PARTICIPANT";
        }
        if ("references".equals(category)) {
            return "REFERENCE_TO_REMOTE_ROLE_ADAPTER";
        }
        return "REFERENCE_TO_REMOTE_ROLE_ADAPTER";
    }

    private String serviceParticipantRoleOnlyMigrationAction(ServiceParticipantMigrationEntry entry,
                                                             List<RepositoryQueryPlan> repositoryQueryPlans,
                                                             List<ObjectSnapshotPlan> objectSnapshotPlans,
                                                             List<QuantumAccessPlan> quantumAccessPlans,
                                                             List<RemoteServiceAssignment> remoteAssignments) {
        if (entry == null) {
            return "";
        }
        String category = entry.category();
        if (serviceParticipantUsesQuantumResourceBoundary(entry, quantumAccessPlans)) {
            if ("contracts".equals(category)) {
                return "CONTRACT_TO_QUANTUM_RESOURCE_ADAPTER";
            }
            if ("entities".equals(category)) {
                return "ENTITY_TO_QUANTUM_RESOURCE_ADAPTER";
            }
        }
        if (serviceParticipantUsesObjectTransactionBoundary(entry, objectSnapshotPlans)) {
            if ("contracts".equals(category)) {
                return "CONTRACT_TO_OBJECT_TRANSACTION_ADAPTER";
            }
            if ("entities".equals(category)) {
                return "ENTITY_TO_OBJECT_TRANSACTION_ADAPTER";
            }
        }
        if (serviceParticipantUsesObjectRepositoryBoundary(entry, repositoryQueryPlans)) {
            if ("contracts".equals(category)) {
                return "CONTRACT_TO_OBJECT_REPOSITORY_ADAPTER";
            }
            if ("entities".equals(category)) {
                return "ENTITY_TO_OBJECT_REPOSITORY_ADAPTER";
            }
        }
        if ("references".equals(category)
                && serviceParticipantUsesExternalRemoteBoundary(entry, remoteAssignments)) {
            return "REFERENCE_TO_EXTERNAL_DOMAIN_ADAPTER";
        }
        return serviceParticipantRoleOnlyMigrationAction(entry);
    }

    private boolean serviceParticipantUsesQuantumResourceBoundary(ServiceParticipantMigrationEntry entry,
                                                                  List<QuantumAccessPlan> quantumAccessPlans) {
        if (entry == null || quantumAccessPlans == null || quantumAccessPlans.isEmpty()) {
            return false;
        }
        return quantumAccessPlans.stream()
                .anyMatch(plan -> Objects.equals(entry.serviceName(), plan.serviceName())
                        && plan.accessContractAvailable());
    }

    private boolean serviceParticipantUsesObjectTransactionBoundary(ServiceParticipantMigrationEntry entry,
                                                                    List<ObjectSnapshotPlan> objectSnapshotPlans) {
        if (entry == null || objectSnapshotPlans == null || objectSnapshotPlans.isEmpty()) {
            return false;
        }
        return objectSnapshotPlans.stream()
                .anyMatch(plan -> Objects.equals(entry.serviceName(), plan.serviceName())
                        && Objects.equals(entry.participantType(), plan.objectType())
                        && plan.argumentRecoveryEvidence()
                        && plan.objectKeyAppDdlDerived());
    }

    private boolean serviceParticipantUsesObjectRepositoryBoundary(ServiceParticipantMigrationEntry entry,
                                                                   List<RepositoryQueryPlan> repositoryQueryPlans) {
        if (entry == null || repositoryQueryPlans == null || repositoryQueryPlans.isEmpty()) {
            return false;
        }
        return repositoryQueryPlans.stream()
                .anyMatch(plan -> Objects.equals(entry.serviceName(), plan.serviceName())
                        && Objects.equals(entry.participantType(), plan.objectType())
                        && plan.appDdlDerived()
                        && !plan.escapeHatch());
    }

    private boolean serviceParticipantUsesExternalRemoteBoundary(ServiceParticipantMigrationEntry entry,
                                                                 List<RemoteServiceAssignment> remoteAssignments) {
        if (entry == null || remoteAssignments == null || remoteAssignments.isEmpty()) {
            return false;
        }
        return remoteAssignments.stream()
                .anyMatch(assignment -> Objects.equals(entry.serviceName(), assignment.serviceName())
                        && assignment.externalImplementation());
    }

    private boolean serviceParticipantAdapterBoundaryReady(String action) {
        return "CONTRACT_TO_QUANTUM_RESOURCE_ADAPTER".equals(action)
                || "ENTITY_TO_QUANTUM_RESOURCE_ADAPTER".equals(action)
                || "CONTRACT_TO_OBJECT_TRANSACTION_ADAPTER".equals(action)
                || "ENTITY_TO_OBJECT_TRANSACTION_ADAPTER".equals(action)
                || "CONTRACT_TO_OBJECT_REPOSITORY_ADAPTER".equals(action)
                || "ENTITY_TO_OBJECT_REPOSITORY_ADAPTER".equals(action)
                || "REFERENCE_TO_EXTERNAL_DOMAIN_ADAPTER".equals(action);
    }

    private List<String> serviceParticipantAdapterBoundaryReadinessReasons(String action) {
        if ("CONTRACT_TO_QUANTUM_RESOURCE_ADAPTER".equals(action)
                || "ENTITY_TO_QUANTUM_RESOURCE_ADAPTER".equals(action)) {
            return List.of("APP_QUANTUM_RESOURCE_BOUND", "QUANTUM_RESOURCE_BOUNDARY",
                    "IDEMPOTENCY_REVERSAL_INTERNAL");
        }
        if ("CONTRACT_TO_OBJECT_TRANSACTION_ADAPTER".equals(action)
                || "ENTITY_TO_OBJECT_TRANSACTION_ADAPTER".equals(action)) {
            return List.of("APP_DDL_SNAPSHOT_BOUND", "OBJECT_TRANSACTION_BOUNDARY");
        }
        if ("CONTRACT_TO_OBJECT_REPOSITORY_ADAPTER".equals(action)
                || "ENTITY_TO_OBJECT_REPOSITORY_ADAPTER".equals(action)) {
            return List.of("APP_DDL_REPOSITORY_BOUND", "OBJECT_REPOSITORY_BOUNDARY");
        }
        if ("REFERENCE_TO_EXTERNAL_DOMAIN_ADAPTER".equals(action)) {
            return List.of("EXTERNAL_REMOTE_ADAPTER_BOUND", "REFERENCE_BOUNDARY_EXTERNALIZED");
        }
        return List.of();
    }

    private String serviceParticipantRoleOnlyMigrationActionBinding(ServiceParticipantMigrationEntry entry) {
        if (entry == null || entry.path() == null || entry.path().isBlank()) {
            return "";
        }
        return valueOrDash(entry.serviceName())
                + ":" + valueOrDash(entry.participantType())
                + ":category=" + valueOrDash(entry.category())
                + ":action=" + serviceParticipantRoleOnlyMigrationAction(entry)
                + ":path=" + entry.path();
    }

