    private String serviceParticipantRoleOnlyScenarioContractContextBindings(
            List<ServiceParticipantRoleOnlyMigrationActionPlan> plans,
            List<ScenarioContractContextPlan> contextPlans) {
        if (plans == null || plans.isEmpty() || contextPlans == null || contextPlans.isEmpty()) {
            return "";
        }
        return plans.stream()
                .map(plan -> serviceParticipantRoleOnlyScenarioContractContextBinding(plan,
                        scenarioContractContextForActionPlan(plan, contextPlans)))
                .filter(value -> !value.isBlank())
                .distinct()
                .collect(Collectors.joining(";"));
    }

    private String serviceParticipantRoleOnlyScenarioContractContextBinding(
            ServiceParticipantRoleOnlyMigrationActionPlan actionPlan,
            ScenarioContractContextPlan contextPlan) {
        if (actionPlan == null || contextPlan == null) {
            return "";
        }
        return valueOrDash(actionPlan.serviceName())
                + ":" + valueOrDash(actionPlan.participantType())
                + ":path=" + valueOrDash(actionPlan.path())
                + ":context=" + valueOrDash(contextPlan.contractParameterKey())
                + ":signers=" + valueOrDash(String.join("+", contextPlan.signerRoleTypes()))
                + ":targetRoles=" + valueOrDash(String.join("+", actionPlan.targetRoleTypes()))
                + ":targetRoleParams=" + valueOrDash(String.join("+", actionPlan.targetRoleParameterNames()))
                + ":contextComplete=" + contextPlan.contextComplete()
                + ":roleOnlyReady=" + actionPlan.roleOnlyReady();
    }

    private ScenarioContractContextPlan scenarioContractContextForActionPlan(
            ServiceParticipantRoleOnlyMigrationActionPlan actionPlan,
            List<ScenarioContractContextPlan> contextPlans) {
        if (actionPlan == null || contextPlans == null || contextPlans.isEmpty()
                || actionPlan.path() == null || actionPlan.path().isBlank()) {
            return null;
        }
        String participantType = serviceParticipantType(actionPlan.path());
        String parameterKey = serviceParticipantParameterKey(actionPlan.path());
        return contextPlans.stream()
                .filter(plan -> Objects.equals(parameterKey, plan.contractParameterKey()))
                .filter(plan -> Objects.equals(participantType, plan.contractType()))
                .findFirst()
                .orElse(null);
    }

    private String serviceParticipantParameterKey(String path) {
        if (path == null || path.isBlank()) {
            return "";
        }
        int colon = path.lastIndexOf(':');
        String serviceAndParameter = colon < 0 ? path : path.substring(0, colon);
        return serviceAndParameter == null ? "" : serviceAndParameter.trim();
    }

