    private String serviceParticipantRoleOnlyMigrationActionReadinessReasons(
            ServiceParticipantRoleOnlyMigrationActionPlan plan) {
        if (plan == null) {
            return "-";
        }
        if (plan.readinessReasonSummary() != null && !plan.readinessReasonSummary().isBlank()) {
            return plan.readinessReasonSummary();
        }
        return String.join("+", serviceParticipantRoleOnlyMigrationActionReadinessReasonList(
                plan.roleOnlyReady(), plan.roleParticipantPresent(), plan.targetRolePresent(),
                plan.migrationAction()));
    }

    private List<String> serviceParticipantRoleOnlyMigrationActionReadinessReasonList(
            boolean roleOnlyReady, boolean roleParticipantPresent, boolean targetRolePresent,
            String migrationAction) {
        List<String> reasons = new ArrayList<>();
        if (roleOnlyReady) {
            reasons.add("ROLE_PARTICIPANT_PRESENT");
            reasons.add("TARGET_ROLE_PRESENT");
            reasons.add("NON_ROLE_PARTICIPANT_REMOVABLE");
        } else {
            if (!roleParticipantPresent) {
                reasons.add("MISSING_ROLE_PARTICIPANT");
            }
            if (!targetRolePresent) {
                reasons.add("MISSING_TARGET_ROLE");
            }
            if ("REFERENCE_TO_REMOTE_ROLE_ADAPTER".equals(migrationAction)) {
                reasons.add("REMOTE_ROLE_ADAPTER_REQUIRED");
            }
            if (reasons.isEmpty()) {
                reasons.add("MIGRATION_ACTION_NOT_READY");
            }
        }
        return List.copyOf(reasons);
    }

    private String serviceParticipantRoleOnlyMigrationRecommendation(String action, List<String> candidateRoleTypes) {
        if ("CONTRACT_CONTEXT_TO_ROLE_SIGNED_SCENARIO".equals(action)) {
            return "Move the contract object out of the participant list and bind it as role-signed scenario context.";
        }
        if ("ENTITY_TO_ROLE_PERFORMER_OR_REPOSITORY_QUERY".equals(action)) {
            if (candidateRoleTypes != null && !candidateRoleTypes.isEmpty()) {
                return "Accept target Role " + String.join("+", candidateRoleTypes)
                        + " and resolve the concrete entity performer through role identity or repository query.";
            }
            return "Accept a Role participant and resolve the concrete entity performer through role identity or repository query.";
        }
        if ("KEEP_ROLE_PARTICIPANT".equals(action)) {
            return "Keep the participant as a Role and complete its performer identity sidecar if needed.";
        }
        return "Keep the external reference behind a remote Role adapter instead of passing the reference as a service participant.";
    }

