    private List<ContractSignerPlan> contractSignerPlans(List<AppSemanticMigrationPlan> generatedPlans,
                                                         List<RoleParticipantPlan> roleParticipantPlans,
                                                         List<GeneratedServiceMetadata> serviceMetadata) {
        Set<String> roleParticipantTypes = roleParticipantPlans == null
                ? Set.of()
                : roleParticipantPlans.stream()
                        .map(RoleParticipantPlan::roleType)
                        .filter(value -> value != null && !value.isBlank())
                        .collect(Collectors.toCollection(LinkedHashSet::new));
        List<ContractSignerPlan> plans = new ArrayList<>();
        plans.addAll(scenarioContractSignerPlans(serviceMetadata, roleParticipantTypes));
        return List.copyOf(plans);
    }

    private List<ContractSignerPlan> scenarioContractSignerPlans(List<GeneratedServiceMetadata> serviceMetadata,
                                                                 Set<String> roleParticipantTypes) {
        if (serviceMetadata == null || serviceMetadata.isEmpty() || appDdlCatalog == null) {
            return List.of();
        }
        List<ContractSignerPlan> plans = new ArrayList<>();
        for (GeneratedServiceMetadata service : serviceMetadata) {
            if (service == null || service.serviceKind() != GeneratedServiceKind.SCENARIO) {
                continue;
            }
            List<ScenarioParameter> contractParameters = scenarioParametersByCategory(service, "contracts");
            List<ScenarioParameter> roleParameters = scenarioParametersByCategory(service, "roles");
            if (contractParameters.isEmpty() || roleParameters.isEmpty()) {
                continue;
            }
            for (ScenarioParameter contractParameter : contractParameters) {
                for (ScenarioParameter roleParameter : roleParameters) {
                    boolean roleParticipantDefined = roleParticipantTypes != null
                            && roleParticipantTypes.contains(roleParameter.typeName());
                    boolean signedByRole = true;
                    boolean migrationRequired = false;
                    List<String> missingReasons =
                            contractSignerMissingReasons(contractParameter, roleParameter,
                                    roleParticipantDefined, signedByRole, migrationRequired);
                    String readiness = missingReasons.isEmpty()
                            ? "CONTRACT_SIGNER_READY"
                            : "CONTRACT_SIGNER_INCOMPLETE";
                    String signerPath = service.serviceName() + "." + contractParameter.parameterName()
                            + ":" + contractParameter.typeName()
                            + "->" + roleParameter.parameterName()
                            + ":" + roleParameter.typeName();
                    List<String> readyReasons = missingReasons.isEmpty()
                            ? contractSignerReadyReasons(contractParameter, roleParameter,
                                    roleParticipantDefined, signedByRole, migrationRequired, signerPath)
                            : List.of();
                    List<String> normalizedMissingReasons = missingReasons.isEmpty()
                            ? List.of("NO_MISSING_CONTRACT_SIGNER_REASON")
                            : missingReasons;
                    List<String> actions = contractSignerActions(missingReasons);
                    plans.add(new ContractSignerPlan(contractParameter.typeName(),
                            contractParameter.tableName(),
                            service.serviceName(),
                            contractParameter.parameterName(),
                            signerPath,
                            roleParameter.parameterName(),
                            roleParameter.typeName(),
                            "roles",
                            roleParticipantDefined,
                            signedByRole,
                            migrationRequired,
                            "Contract is signed by Role participants in the scenario boundary.",
                            readiness,
                            readyReasons,
                            normalizedMissingReasons,
                            actions,
                            contractSignerSigningContract(contractParameter, roleParameter, service.serviceName(),
                                    readiness)));
                }
            }
        }
        return List.copyOf(plans);
    }

    private List<String> contractSignerReadyReasons(ScenarioParameter contractParameter,
                                                    ScenarioParameter roleParameter,
                                                    boolean roleParticipantDefined,
                                                    boolean signedByRole,
                                                    boolean migrationRequired,
                                                    String signerPath) {
        List<String> reasons = new ArrayList<>();
        if (contractParameter != null && !isBlank(contractParameter.typeName())) {
            reasons.add("contract");
        }
        if (contractParameter != null && !isBlank(contractParameter.tableName())) {
            reasons.add("contractTable");
        }
        if (contractParameter != null && !isBlank(contractParameter.parameterName())) {
            reasons.add("contractParameter");
        }
        if (!isBlank(signerPath)) {
            reasons.add("signerPath");
        }
        if (roleParameter != null && !isBlank(roleParameter.typeName()) && signedByRole) {
            reasons.add("roleSigner");
        }
        if (roleParticipantDefined) {
            reasons.add("roleParticipant");
        }
        if (!migrationRequired) {
            reasons.add("migrationReady");
        }
        return List.copyOf(reasons);
    }

    private List<String> contractSignerMissingReasons(ScenarioParameter contractParameter,
                                                      ScenarioParameter roleParameter,
                                                      boolean roleParticipantDefined,
                                                      boolean signedByRole,
                                                      boolean migrationRequired) {
        List<String> missing = new ArrayList<>();
        if (contractParameter == null || isBlank(contractParameter.typeName())) {
            missing.add("contract");
        }
        if (contractParameter == null || isBlank(contractParameter.parameterName())) {
            missing.add("contractParameter");
        }
        if (roleParameter == null || isBlank(roleParameter.typeName())) {
            missing.add("signerRole");
        }
        if (!signedByRole) {
            missing.add("roleSigner");
        }
        if (!roleParticipantDefined) {
            missing.add("roleParticipant");
        }
        if (migrationRequired) {
            missing.add("migration");
        }
        return List.copyOf(missing);
    }

    private List<String> contractSignerActions(List<String> missingReasons) {
        if (missingReasons == null || missingReasons.isEmpty()) {
            return List.of("NO_ACTION_REQUIRED");
        }
        LinkedHashSet<String> actions = new LinkedHashSet<>();
        for (String reason : missingReasons) {
            switch (reason) {
                case "contract", "contractParameter", "signerRole" ->
                        actions.add("deriveContractSignerFromScenarioRoles");
                case "roleSigner" -> actions.add("moveContractSignerToScenarioRoleParticipant");
                case "roleParticipant" -> actions.add("declareRoleParticipantIdentity");
                case "migration" -> actions.add("suppressLegacyContractFieldSignerOrMigrateToRoleSigner");
                default -> actions.add("resolveContractSignerReadiness");
            }
        }
        return List.copyOf(actions);
    }

    private String contractSignerSigningContract(ScenarioParameter contractParameter,
                                                 ScenarioParameter roleParameter,
                                                 String scenarioName,
                                                 String readiness) {
        String scenario = isBlank(scenarioName) ? "NO_SCENARIO" : scenarioName;
        String contractParameterName = contractParameter == null || isBlank(contractParameter.parameterName())
                ? "NO_CONTRACT_PARAMETER"
                : contractParameter.parameterName();
        String contractType = contractParameter == null || isBlank(contractParameter.typeName())
                ? "NO_CONTRACT"
                : contractParameter.typeName();
        String signerType = roleParameter == null || isBlank(roleParameter.typeName())
                ? "NO_SIGNER_ROLE"
                : roleParameter.typeName();
        String signerParameter = roleParameter == null || isBlank(roleParameter.parameterName())
                ? "NO_SIGNER_PARAMETER"
                : roleParameter.parameterName();
        return scenario + "." + contractParameterName + ":" + contractType
                + "<-" + signerType + ":" + signerParameter + ":" + valueOrDash(readiness);
    }

    private List<ScenarioParameter> scenarioParametersByCategory(GeneratedServiceMetadata service, String category) {
        if (service == null || category == null || category.isBlank() || appDdlCatalog == null) {
            return List.of();
        }
        List<String> parameterTypes = service.serviceParameterTypes() == null
                ? List.of()
                : service.serviceParameterTypes();
        Set<String> contextParameterNames = service.serviceContextParameterNames() == null
                ? Set.of()
                : Set.copyOf(service.serviceContextParameterNames());
        List<ScenarioParameter> parameters = new ArrayList<>();
        for (int index = 0; index < parameterTypes.size(); index++) {
            String typeName = simpleTypeName(parameterTypes.get(index));
            if (typeName.isBlank()) {
                continue;
            }
            Optional<AppDdlCatalog.Table> maybeTable = appDdlCatalog.tableForBusinessType(typeName);
            if (maybeTable.isEmpty() || !category.equals(maybeTable.get().category())) {
                continue;
            }
            String parameterName = serviceParameterName(service, index);
            if (parameterName == null || parameterName.isBlank()) {
                parameterName = lowerFirst(typeName);
            }
            if ("contracts".equals(category) && !contextParameterNames.contains(parameterName)) {
                continue;
            }
            parameters.add(new ScenarioParameter(parameterName, typeName, maybeTable.get().name()));
        }
        return List.copyOf(parameters);
    }

    private record ScenarioParameter(String parameterName,
                                     String typeName,
                                     String tableName) {
    }

    private String contractSignerPlanBinding(ContractSignerPlan plan) {
        if (plan == null || plan.contractType() == null || plan.contractType().isBlank()) {
            return "";
        }
        return plan.contractType()
                + ":scenario=" + valueOrDash(plan.scenarioName())
                + ":contractParameter=" + valueOrDash(plan.contractParameterName())
                + ":" + valueOrDash(plan.signerFieldName())
                + ":" + valueOrDash(plan.signerType())
                + ":category=" + valueOrDash(plan.signerCategory())
                + ":path=" + valueOrDash(plan.signerPath())
                + ":roleParticipantDefined=" + plan.roleParticipantDefined()
                + ":signedByRole=" + plan.signedByRole()
                + ":migrationRequired=" + plan.migrationRequired();
    }

    private List<ScenarioContractContextPlan> scenarioContractContextPlans(List<ContractSignerPlan> signerPlans) {
        if (signerPlans == null || signerPlans.isEmpty()) {
            return List.of();
        }
        Map<String, List<ContractSignerPlan>> plansByParameter = new LinkedHashMap<>();
        for (ContractSignerPlan plan : signerPlans) {
            if (plan == null || plan.scenarioName() == null || plan.scenarioName().isBlank()
                    || plan.contractParameterName() == null || plan.contractParameterName().isBlank()) {
                continue;
            }
            plansByParameter.computeIfAbsent(contractSignerContractParameterKey(plan), ignored -> new ArrayList<>())
                    .add(plan);
        }
        List<ScenarioContractContextPlan> contextPlans = new ArrayList<>();
        for (Map.Entry<String, List<ContractSignerPlan>> entry : plansByParameter.entrySet()) {
            List<ContractSignerPlan> plans = entry.getValue();
            if (plans == null || plans.isEmpty()) {
                continue;
            }
            ContractSignerPlan first = plans.get(0);
            List<String> signerRoles = contractSignerDistinctValues(plans, ContractSignerPlan::signerType);
            List<String> signerParameters = contractSignerDistinctValues(plans, ContractSignerPlan::signerFieldName);
            List<String> signerPaths = contractSignerDistinctValues(plans, ContractSignerPlan::signerPath);
            boolean roleParticipantDefined = plans.stream().allMatch(ContractSignerPlan::roleParticipantDefined);
            boolean signedByRole = plans.stream().allMatch(ContractSignerPlan::signedByRole);
            boolean complete = !signerRoles.isEmpty() && roleParticipantDefined && signedByRole;
            String readiness = complete
                    ? "SCENARIO_CONTRACT_CONTEXT_READY"
                    : "SCENARIO_CONTRACT_CONTEXT_INCOMPLETE";
            List<String> readyReasons = complete
                    ? scenarioContractContextReadyReasons(signerRoles, roleParticipantDefined, signedByRole)
                    : List.of();
            List<String> missingReasons = complete
                    ? List.of("NO_MISSING_SCENARIO_CONTRACT_CONTEXT_REASON")
                    : scenarioContractContextMissingReasons(signerRoles, roleParticipantDefined, signedByRole);
            String action = complete
                    ? "NO_ACTION_REQUIRED"
                    : "BIND_CONTRACT_CONTEXT_TO_ROLE_PARTICIPANTS";
            String signerRoleSet = scenarioContractSignerRoleSetKey(signerRoles);
            String signingContract = scenarioContractSigningContractKey(first.contractType(), signerRoleSet, readiness);
            String executionContract = scenarioContractExecutionContractKey(
                    entry.getKey(), first.contractType(), signerRoleSet, readiness);
            contextPlans.add(new ScenarioContractContextPlan(first.scenarioName(),
                    first.contractType(),
                    first.contractTableName(),
                    first.contractParameterName(),
                    entry.getKey(),
                    signerRoles,
                    signerParameters,
                    signerPaths,
                    plans.size(),
                    roleParticipantDefined,
                    signedByRole,
                    complete,
                    readiness,
                    readyReasons,
                    missingReasons,
                    action,
                    complete
                            ? "Contract context is signed by scenario Role participants."
                            : "Bind the Contract context to Role participants in the scenario boundary.",
                    List.of(action),
                    signerRoleSet,
                    signingContract,
                    executionContract));
        }
        return List.copyOf(contextPlans);
    }

    private List<String> scenarioContractContextReadyReasons(List<String> signerRoleTypes,
                                                             boolean roleParticipantDefined,
                                                             boolean signedByRole) {
        List<String> reasons = new ArrayList<>();
        if (signerRoleTypes != null && !signerRoleTypes.isEmpty()) {
            reasons.add("roleSignedContext");
        }
        if (roleParticipantDefined) {
            reasons.add("roleParticipantDefined");
        }
        if (signedByRole) {
            reasons.add("signedByRole");
        }
        return reasons.isEmpty() ? List.of("contextComplete") : List.copyOf(reasons);
    }

    private List<String> scenarioContractContextMissingReasons(List<String> signerRoleTypes,
                                                               boolean roleParticipantDefined,
                                                               boolean signedByRole) {
        List<String> reasons = new ArrayList<>();
        if (signerRoleTypes == null || signerRoleTypes.isEmpty()) {
            reasons.add("missingSignerRole");
        }
        if (!roleParticipantDefined) {
            reasons.add("missingRoleParticipant");
        }
        if (!signedByRole) {
            reasons.add("missingRoleSignature");
        }
        return reasons.isEmpty() ? List.of("contextIncomplete") : List.copyOf(reasons);
    }

    private List<String> contractSignerDistinctValues(List<ContractSignerPlan> plans,
                                                      Function<ContractSignerPlan, String> valueExtractor) {
        if (plans == null || plans.isEmpty() || valueExtractor == null) {
            return List.of();
        }
        return plans.stream()
                .map(valueExtractor)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .toList();
    }

