    private String scenarioContractSigningContractKey(ScenarioContractContextPlan plan) {
        if (plan == null) {
            return "NO_SCENARIO_CONTRACT_CONTEXT";
        }
        if (plan.signingContract() != null && !plan.signingContract().isBlank()) {
            return plan.signingContract();
        }
        return scenarioContractSigningContractKey(plan.contractType(),
                scenarioContractSignerRoleSetKey(plan.signerRoleTypes()),
                plan.readiness());
    }

    private String scenarioContractExecutionContractKey(ScenarioContractContextPlan plan) {
        if (plan == null) {
            return "NO_SCENARIO_CONTRACT_CONTEXT";
        }
        if (plan.executionContract() != null && !plan.executionContract().isBlank()) {
            return plan.executionContract();
        }
        return scenarioContractExecutionContractKey(plan.contractParameterKey(), plan.contractType(),
                scenarioContractSignerRoleSetKey(plan.signerRoleTypes()),
                plan.readiness());
    }

