    private static String roleParticipantRequestBindingMissingReasonRoleNames(
            List<RoleParticipantRequestBindingPlan> bindings, String reason) {
        if (bindings == null || reason == null || reason.isBlank()) {
            return "";
        }
        return bindings.stream()
                .filter(Objects::nonNull)
                .filter(binding -> reason.equals(roleParticipantRequestMissingReason(binding)))
                .map(RoleParticipantRequestBindingPlan::roleType)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining("+"));
    }

    private static String roleParticipantRequestMissingReason(RoleParticipantRequestBindingPlan binding) {
        if (binding == null || binding.complete()) {
            return "-";
        }
        if (!binding.requestTypeAvailable()) {
            return "requestType";
        }
        if (binding.missingSidecarFieldNames() != null && !binding.missingSidecarFieldNames().isEmpty()) {
            return "performerSidecar";
        }
        return "identityBinding";
    }

    private static String roleParticipantRequestMissingActionsForReason(String reason) {
        return switch (reason == null ? "" : reason) {
            case "requestType" -> "generateRoleParticipantRequestEnvelope";
            case "performerSidecar" -> "addRoleParticipantPerformerSidecarFields";
            case "identityBinding" -> "bindRoleParticipantPerformerIdentity";
            default -> "";
        };
    }

    private String roleParticipantRequestBindingStrictError(RoleParticipantRequestBindingPlan binding) {
        if (binding == null || binding.complete()) {
            return "";
        }
        String missing = binding.missingSidecarFieldNames().isEmpty()
                ? "request type"
                : String.join(", ", binding.missingSidecarFieldNames());
        String action = roleParticipantRequestMissingActions(binding);
        return "Service " + valueOrDash(binding.serviceName())
                + " Role " + valueOrDash(binding.roleType())
                + " parameter " + valueOrDash(binding.roleParameterName())
                + " is missing performer sidecar " + missing
                + " for role-only service boundary"
                + " (request=" + valueOrDash(binding.requestTypeName())
                + ", sidecars=" + valueOrDash(String.join("+", binding.sidecarFieldNames()))
                + ", missingSidecars=" + valueOrDash(String.join("+", binding.missingSidecarFieldNames()))
                + ", source=" + valueOrDash(binding.identityBindingSource())
                + ", requestAvailable=" + binding.requestTypeAvailable()
                + ", complete=" + binding.complete()
                + ")"
                + "; actions=" + action
                + "; action=" + action + ".";
    }

    private String serviceParticipantRoleOnlyReadinessBindings(Set<String> serviceNames,
                                                               Set<String> roleParticipantServiceNames,
                                                               Set<String> nonRoleParticipantServiceNames) {
        Set<String> safeServiceNames = serviceNames == null ? Set.of() : serviceNames;
        Set<String> safeRoleParticipantServiceNames =
                roleParticipantServiceNames == null ? Set.of() : roleParticipantServiceNames;
        Set<String> safeNonRoleParticipantServiceNames =
                nonRoleParticipantServiceNames == null ? Set.of() : nonRoleParticipantServiceNames;
        return safeServiceNames.stream()
                .filter(serviceName -> serviceName != null && !serviceName.isBlank())
                .map(serviceName -> {
                    boolean roleParticipant = safeRoleParticipantServiceNames.contains(serviceName);
                    boolean nonRoleParticipant = safeNonRoleParticipantServiceNames.contains(serviceName);
                    return serviceName
                            + ":roleParticipants=" + roleParticipant
                            + ":nonRoleParticipants=" + nonRoleParticipant
                            + ":roleOnlyReady=" + (roleParticipant && !nonRoleParticipant);
                })
                .collect(Collectors.joining(";"));
    }

    private String serviceParticipantRoleOnlyMissingBindings(Set<String> serviceNames,
                                                             Set<String> roleParticipantServiceNames,
                                                             List<ServiceParticipantMigrationEntry> entries) {
        Set<String> safeServiceNames = serviceNames == null ? Set.of() : serviceNames;
        Set<String> safeRoleParticipantServiceNames =
                roleParticipantServiceNames == null ? Set.of() : roleParticipantServiceNames;
        List<ServiceParticipantMigrationEntry> safeEntries = entries == null ? List.of() : List.copyOf(entries);
        Map<String, List<ServiceParticipantMigrationEntry>> entriesByService = safeEntries.stream()
                .filter(entry -> entry.serviceName() != null && !entry.serviceName().isBlank())
                .collect(Collectors.groupingBy(ServiceParticipantMigrationEntry::serviceName,
                        LinkedHashMap::new, Collectors.toList()));
        return safeServiceNames.stream()
                .filter(serviceName -> serviceName != null && !serviceName.isBlank())
                .map(serviceName -> {
                    List<ServiceParticipantMigrationEntry> serviceEntries =
                            entriesByService.getOrDefault(serviceName, List.of());
                    return serviceName
                            + ":roleParticipants=" + safeRoleParticipantServiceNames.contains(serviceName)
                            + ":nonRoleTypes=" + serviceParticipantEntryValues(serviceEntries,
                                    ServiceParticipantMigrationEntry::participantType, false)
                            + ":categories=" + serviceParticipantEntryValues(serviceEntries,
                                    ServiceParticipantMigrationEntry::category, true)
                            + ":categorySources=" + serviceParticipantEntryValues(serviceEntries,
                                    ServiceParticipantMigrationEntry::categorySource, true)
                            + ":paths=" + serviceParticipantEntryValues(serviceEntries,
                                    ServiceParticipantMigrationEntry::path, false)
                            + ":roleOnlyReady=false";
                })
                .collect(Collectors.joining(";"));
    }

    private String serviceParticipantEntryValues(List<ServiceParticipantMigrationEntry> entries,
                                                 Function<ServiceParticipantMigrationEntry, String> valueExtractor,
                                                 boolean dashBlank) {
        if (entries == null || entries.isEmpty()) {
            return "-";
        }
        String values = entries.stream()
                .map(valueExtractor)
                .map(value -> dashBlank ? valueOrDash(value) : value)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining("+"));
        return valueOrDash(values);
    }

