    private String remainingMigrationSourceBindings(List<AppSemanticMigrationPlan> runtimePlans,
                                                    List<AppSemanticMigrationPlan> activeGeneratedPlans) {
        Map<String, AppSemanticMigrationPlan> plansByKey = new LinkedHashMap<>();
        Map<String, Set<String>> sourcesByKey = new LinkedHashMap<>();
        addRemainingMigrationSourceBindings(plansByKey, sourcesByKey, runtimePlans, "runtime");
        addRemainingMigrationSourceBindings(plansByKey, sourcesByKey, activeGeneratedPlans, "activeGenerated");
        return plansByKey.entrySet().stream()
                .map(entry -> appSemanticMigrationBinding(entry.getValue())
                        + ":sources=" + String.join("+", sourcesByKey.getOrDefault(entry.getKey(), Set.of())))
                .filter(value -> !value.isBlank())
                .collect(Collectors.joining(","));
    }

    private long remainingMigrationSourceClassCount(List<AppSemanticMigrationPlan> runtimePlans,
                                                    List<AppSemanticMigrationPlan> activeGeneratedPlans,
                                                    String sourceClass) {
        Map<String, AppSemanticMigrationPlan> plansByKey = new LinkedHashMap<>();
        Map<String, Set<String>> sourcesByKey = new LinkedHashMap<>();
        addRemainingMigrationSourceBindings(plansByKey, sourcesByKey, runtimePlans, "runtime");
        addRemainingMigrationSourceBindings(plansByKey, sourcesByKey, activeGeneratedPlans, "activeGenerated");
        return plansByKey.keySet().stream()
                .filter(key -> remainingMigrationSourceClassMatches(
                        sourcesByKey.getOrDefault(key, Set.of()), sourceClass))
                .count();
    }

    private String remainingMigrationSourceClassBindings(List<AppSemanticMigrationPlan> runtimePlans,
                                                        List<AppSemanticMigrationPlan> activeGeneratedPlans,
                                                        String sourceClass) {
        Map<String, AppSemanticMigrationPlan> plansByKey = new LinkedHashMap<>();
        Map<String, Set<String>> sourcesByKey = new LinkedHashMap<>();
        addRemainingMigrationSourceBindings(plansByKey, sourcesByKey, runtimePlans, "runtime");
        addRemainingMigrationSourceBindings(plansByKey, sourcesByKey, activeGeneratedPlans, "activeGenerated");
        return plansByKey.entrySet().stream()
                .filter(entry -> remainingMigrationSourceClassMatches(
                        sourcesByKey.getOrDefault(entry.getKey(), Set.of()), sourceClass))
                .map(entry -> appSemanticMigrationBinding(entry.getValue())
                        + ":sources=" + String.join("+", sourcesByKey.getOrDefault(entry.getKey(), Set.of())))
                .filter(value -> !value.isBlank())
                .collect(Collectors.joining(","));
    }

    private boolean remainingMigrationSourceClassMatches(Set<String> sources, String sourceClass) {
        boolean runtime = sources != null && sources.contains("runtime");
        boolean activeGenerated = sources != null && sources.contains("activeGenerated");
        return switch (sourceClass) {
            case "runtimeOnly" -> runtime && !activeGenerated;
            case "activeGeneratedOnly" -> activeGenerated && !runtime;
            case "runtimeAndActiveGenerated" -> runtime && activeGenerated;
            default -> false;
        };
    }

    private void addRemainingMigrationSourceBindings(Map<String, AppSemanticMigrationPlan> plansByKey,
                                                     Map<String, Set<String>> sourcesByKey,
                                                     List<AppSemanticMigrationPlan> plans,
                                                     String source) {
        if (plans == null) {
            return;
        }
        for (AppSemanticMigrationPlan plan : plans) {
            String key = remainingAppSemanticMigrationKey(plan);
            if (key.isBlank()) {
                continue;
            }
            plansByKey.putIfAbsent(key, plan);
            sourcesByKey.computeIfAbsent(key, ignored -> new LinkedHashSet<>()).add(source);
        }
    }

    private String remainingAppSemanticMigrationKey(AppSemanticMigrationPlan plan) {
        if (plan == null) {
            return "";
        }
        return String.join(":",
                metadataValue(plan.migrationType()),
                metadataValue(plan.targetKind()),
                metadataValue(plan.targetName()),
                metadataValue(plan.serviceName()),
                metadataValue(plan.tableName()),
                metadataValue(plan.objectType()),
                metadataValue(plan.adapterName()),
                metadataValue(plan.adapterRole()),
                metadataValue(plan.objectKeySource()),
                metadataValue(plan.objectKeyAppDdlIndexName()),
                String.join("+", plan.paths()),
                String.join("+", plan.appDdlObjectKeyPaths()),
                String.join("+", plan.objectKeyColumns()),
                String.join("+", plan.externalObjectKeyRoots()),
                String.join("+", plan.participantCategories()),
                metadataValue(plan.identityKind()),
                metadataValue(plan.recommendation()));
    }

    private static String metadataValue(String value) {
        return value == null || value.isBlank() ? "-" : value;
    }

