    private String repositoryGeneratedRuntimeReadinessConsistencyBinding(String name,
                                                                        String generatedValue,
                                                                        String runtimeValue) {
        String safeGeneratedValue = generatedValue == null || generatedValue.isBlank() ? "-" : generatedValue;
        String safeRuntimeValue = runtimeValue == null || runtimeValue.isBlank() ? "-" : runtimeValue;
        return name
                + ":generated=" + safeGeneratedValue
                + ":runtime=" + safeRuntimeValue
                + ":consistent=" + safeGeneratedValue.equals(safeRuntimeValue);
    }

