    private boolean quantumServiceProtocolBoundaryCompliant(
            PhysicalQuantumPlan plan, PhysicalRuntimeCatalog.QuantumStore store) {
        if (plan == null || store == null) {
            return false;
        }
        if ("HTTP_JSON".equals(plan.serviceProtocol())) {
            return !store.configuration().containsKey("namespace") && store.definitions().isEmpty();
        }
        if ("LOGICAL_QSERVICE".equals(plan.serviceProtocol())) {
            if (!hasNonBlank(store.configuration(), "namespace") || store.definitions().isEmpty()) {
                return false;
            }
            Set<String> definedAttributeIds = new LinkedHashSet<>();
            try {
                for (PhysicalRuntimeCatalog.QuantumDefinition definition : store.definitions()) {
                    if (!definedAttributeIds.add(definition.attributeId())) {
                        return false;
                    }
                    new QuantumServiceDefinition(definition.attributeId(), definition.numberType(),
                            definition.minValue(), definition.maxValue(), definition.scale());
                }
            } catch (IllegalArgumentException e) {
                return false;
            }
            return definedAttributeIds.equals(new LinkedHashSet<>(plan.attributeIds()));
        }
        return false;
    }

    private String quantumServiceProtocolBoundaryBinding(
            PhysicalQuantumPlan plan, PhysicalRuntimeCatalog.QuantumStore store) {
        if (plan == null || isBlankStatic(plan.storeName())) {
            return "";
        }
        boolean namespaceDeclared = store != null && store.configuration().containsKey("namespace");
        int definitionCount = store == null ? 0 : store.definitions().size();
        boolean compliant = quantumServiceProtocolBoundaryCompliant(plan, store);
        String action;
        if (compliant) {
            action = "NO_ACTION_REQUIRED";
        } else if ("HTTP_JSON".equals(plan.serviceProtocol())) {
            action = "removeLogicalQServiceProvisioningFromHttpProfile";
        } else if ("LOGICAL_QSERVICE".equals(plan.serviceProtocol())) {
            action = "declareLogicalQServiceNamespaceAndDefinitions";
        } else {
            action = "selectSupportedQuantumServiceProtocol";
        }
        String boundary = switch (plan.serviceProtocol()) {
            case "HTTP_JSON" -> "SERVICE_INTERNAL_ENCAPSULATION";
            case "LOGICAL_QSERVICE" -> "EXPLICIT_LOGICAL_PROVISIONING";
            default -> "UNSUPPORTED_PROTOCOL";
        };
        return plan.storeName()
                + ":protocol=" + blankAsDash(plan.serviceProtocol())
                + ":boundary=" + boundary
                + ":applicationNamespaceDeclared=" + namespaceDeclared
                + ":applicationDefinitionCount=" + definitionCount
                + ":compliant=" + compliant
                + ":action=" + action;
    }

