    private static boolean quantumServiceExternalImplementationReady(PhysicalQuantumPlan plan) {
        return plan != null
                && "QUANTUM_SERVICE".equals(plan.implementationStrategy())
                && isAbsoluteHttpEndpoint(plan.endpoint())
                && !quantumServiceDevelopmentEndpoint(plan.endpoint())
                && !quantumServicePlaceholderEndpoint(plan.endpoint());
    }

    private static String quantumServiceExternalImplementationReadinessBinding(PhysicalQuantumPlan plan) {
        if (plan == null || isBlankStatic(plan.storeName())
                || !"QUANTUM_SERVICE".equals(plan.implementationStrategy())) {
            return "";
        }
        boolean ready = quantumServiceExternalImplementationReady(plan);
        return plan.storeName()
                + ":externalImplementationReady=" + ready
                + ":readiness=" + (ready ? "PRODUCTION_READY" : "CONTRACT_ONLY")
                + ":reason=" + quantumServiceExternalImplementationReadinessReason(plan)
                + ":adapter=" + blankAsDash(plan.adapterName())
                + ":strategy=" + blankAsDash(plan.implementationStrategy())
                + ":endpoint=" + blankAsDash(plan.endpoint())
                + ":timeout=" + blankAsDash(plan.timeoutMillis());
    }

    private static String quantumServiceExternalImplementationReadinessReason(PhysicalQuantumPlan plan) {
        if (plan == null) {
            return "plan";
        }
        if (isBlankStatic(plan.endpoint())) {
            return "endpoint";
        }
        if (!isAbsoluteHttpEndpoint(plan.endpoint())) {
            return "endpointInvalid";
        }
        if (quantumServiceDevelopmentEndpoint(plan.endpoint())) {
            return "developmentEndpoint";
        }
        if (quantumServicePlaceholderEndpoint(plan.endpoint())) {
            return "placeholderEndpoint";
        }
        return "-";
    }

    private long quantumServiceExternalImplementationReasonPlanCount(List<PhysicalQuantumPlan> plans) {
        return quantumServiceExternalImplementationReasonCounts(plans).values().stream()
                .mapToLong(Long::longValue)
                .sum();
    }

    private String quantumServiceExternalImplementationReasonCountBindings(List<PhysicalQuantumPlan> plans,
                                                                           long totalPlanCount) {
        Map<String, Long> counts = quantumServiceExternalImplementationReasonCounts(plans);
        return counts.entrySet().stream()
                .map(entry -> entry.getKey()
                        + ":count=" + entry.getValue()
                        + ":coverage=" + coverage(entry.getValue(), totalPlanCount)
                        + ":stores=" + quantumServiceExternalImplementationReasonStoreNames(plans, entry.getKey())
                        + ":actions=" + quantumServiceExternalImplementationStrictActions(entry.getKey()))
                .collect(Collectors.joining(";"));
    }

    private Map<String, Long> quantumServiceExternalImplementationReasonCounts(List<PhysicalQuantumPlan> plans) {
        Map<String, Long> counts = new LinkedHashMap<>();
        if (plans == null) {
            return counts;
        }
        for (PhysicalQuantumPlan plan : plans) {
            String reason = quantumServiceExternalImplementationReadinessReason(plan);
            if (!reason.isBlank() && !"-".equals(reason)) {
                counts.merge(reason, 1L, Long::sum);
            }
        }
        return counts;
    }

    private static String quantumServiceExternalImplementationReasonStoreNames(List<PhysicalQuantumPlan> plans,
                                                                               String reason) {
        if (plans == null || reason == null || reason.isBlank()) {
            return "";
        }
        return plans.stream()
                .filter(plan -> reason.equals(quantumServiceExternalImplementationReadinessReason(plan)))
                .map(PhysicalQuantumPlan::storeName)
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .collect(Collectors.joining("+"));
    }

    private static boolean quantumServiceDevelopmentEndpoint(String endpoint) {
        if (isBlankStatic(endpoint)) {
            return false;
        }
        try {
            URI uri = URI.create(endpoint);
            String host = uri.getHost();
            if (host == null || host.isBlank()) {
                return false;
            }
            String normalizedHost = host.toLowerCase(Locale.ROOT);
            return "localhost".equals(normalizedHost)
                    || "127.0.0.1".equals(normalizedHost)
                    || "0.0.0.0".equals(normalizedHost)
                    || "::1".equals(normalizedHost);
        } catch (IllegalArgumentException e) {
            return false;
        }
    }

    private static boolean quantumServicePlaceholderEndpoint(String endpoint) {
        if (isBlankStatic(endpoint)) {
            return false;
        }
        try {
            URI uri = URI.create(endpoint);
            String host = uri.getHost();
            if (host == null || host.isBlank()) {
                return false;
            }
            String normalizedHost = host.toLowerCase(Locale.ROOT);
            return "example.test".equals(normalizedHost)
                    || normalizedHost.endsWith(".example.test")
                    || "example.com".equals(normalizedHost)
                    || normalizedHost.endsWith(".example.com");
        } catch (IllegalArgumentException e) {
            return false;
        }
    }

