        Map<String, IdempotencyPlan> safePlans = plansByService == null ? Map.of() : plansByService;
        return serviceNames.stream()
                .map(safePlans::get)
                .map(plan -> missingIdempotencyBinding(plan, missingKind))
                .filter(value -> !value.isBlank())
                .collect(Collectors.joining(";"));
