    static String idempotencyMissingActions(String missingKind) {
        if (missingKind == null || missingKind.isBlank()) {
            return "";
        }
        return switch (missingKind) {
            case "key" -> "declareIdempotencyKeyInAppHeader";
            case "physicalBinding" -> "bindIdempotentServiceToPhysicalBackend";
            case "adapterUnavailable" -> "registerIdempotencyPhysicalAdapter";
            case "unsupportedTransaction" -> "enableAdapterTransactionSupport";
            case "storeName" -> "configureIdempotencyStoreName";
            case "tableName" -> "configureIdempotencyTableName";
            case "datasource" -> "configureIdempotencyDatasource";
            case "driver" -> "configureIdempotencyDriver";
            case "serviceInternalIdempotency" -> "completeServiceInternalIdempotencyContract";
            case "runtimeStore" -> "configureFrameworkIdempotencyRuntimeStore";
            default -> "resolveIdempotencyRuntimeBinding";
        };
    }

