    private static String idempotencyHeaderKeyBindings(List<IdempotencyPlan> plans) {
        if (plans == null || plans.isEmpty()) {
            return "";
        }
        Map<String, Set<String>> serviceNamesByHeaderKey = new LinkedHashMap<>();
        plans.stream()
                .filter(Objects::nonNull)
                .forEach(plan -> {
                    if (isBlankStatic(plan.serviceName())) {
                        return;
                    }
                    String key = "header=" + blankAsDash(plan.inputHeaderName())
                            + ":key=" + blankAsDash(plan.idempotencyKeyPath())
                            + ":field=" + blankAsDash(plan.idempotencyKeyFieldName())
                            + ":available=" + plan.idempotencyKeyAvailable();
                    serviceNamesByHeaderKey
                            .computeIfAbsent(key, ignored -> new LinkedHashSet<>())
                            .add(plan.serviceName());
                });
        return serviceNamesByHeaderKey.entrySet().stream()
                .map(entry -> entry.getKey() + ":services=" + String.join("+", entry.getValue()))
                .collect(Collectors.joining(";"));
    }

