    private DeploymentValidationPlan deploymentValidationPlan(String category, List<String> errors) {
        List<String> safeErrors = errors == null ? List.of() : List.copyOf(errors);
        return new DeploymentValidationPlan(category, safeErrors.isEmpty(), safeErrors.size(), safeErrors);
    }

    private List<String> mergeValidationErrors(List<DeploymentValidationPlan> deploymentValidationPlans,
                                               List<String> physicalProfileErrors,
                                               List<String> physicalErrors, List<String> remoteErrors,
                                               List<String> remoteCompensationErrors,
                                               List<String> snapshotErrors, List<String> tccLifecycleErrors,
                                               List<String> repositoryErrors,
                                               List<String> compensationErrors,
                                               List<String> repositoryAdapterErrors,
                                               List<String> quantumStoreErrors,
                                               List<String> idempotencyErrors) {
        List<String> errors = new ArrayList<>();
        errors.addAll(physicalProfileErrors);
        errors.addAll(physicalErrors);
        errors.addAll(remoteErrors);
        errors.addAll(remoteCompensationErrors);
        errors.addAll(snapshotErrors);
        errors.addAll(tccLifecycleErrors);
        errors.addAll(repositoryErrors);
        errors.addAll(compensationErrors);
        errors.addAll(repositoryAdapterErrors);
        errors.addAll(quantumStoreErrors);
        errors.addAll(idempotencyErrors);
        if (deploymentValidationPlans != null) {
            deploymentValidationPlans.stream()
                    .flatMap(plan -> plan.errors().stream())
                    .forEach(errors::add);
        }
        return errors.stream()
                .filter(value -> value != null && !value.isBlank())
                .distinct()
                .toList();
    }

    private PhysicalBackendRegistry createPhysicalBackendRegistry(PhysicalRuntimeCatalog catalog) {
        PhysicalBackendRegistry registry = new PhysicalBackendRegistry(catalog)
                .registerAdapter(configureTccPhaseTwoRecovery(
                        new LocalJdbcPhysicalBackendAdapter(physicalRuntime)));
        registerCatalogPhysicalBackendAdapters(catalog, registry);
        for (PhysicalBackendAdapter adapter : physicalBackendAdapters) {
            registry.registerAdapter(configureTccPhaseTwoRecovery(adapter));
        }
        return registry;
    }

    private void registerCatalogPhysicalBackendAdapters(PhysicalRuntimeCatalog catalog,
                                                        PhysicalBackendRegistry registry) {
        for (PhysicalRuntimeCatalog.PhysicalBackend backend : catalog.backends()) {
            if ("localJdbc".equals(backend.adapterName()) || "local-jdbc".equals(backend.adapterName())) {
                registry.registerAdapter(configureTccPhaseTwoRecovery(new LocalJdbcPhysicalBackendAdapter(
                        physicalRuntime, backend.configuration(), backend.quantumStoreName())));
            }
            if ("seata".equals(backend.adapterName())) {
                registry.registerAdapter(configureTccPhaseTwoRecovery(
                        SeataPhysicalBackendAdapter.from(backend)));
            }
        }
    }

    private <T extends PhysicalBackendAdapter> T configureTccPhaseTwoRecovery(T adapter) {
        adapter.useTccPhaseTwoRecovery(this::recoverTccPhaseTwo);
        return adapter;
    }

    private void recoverTccPhaseTwo(String branchId, TccBranchStatus targetStatus) {
        TccBranchRecord branch = getTccBranchStore().find(branchId)
                .orElseThrow(() -> new IllegalStateException("TCC branch " + branchId + " does not exist."));
        if (branch.status() == targetStatus) {
            return;
        }
        if (branch.status() != TccBranchStatus.TRYING) {
            throw new IllegalStateException("TCC branch " + branchId + " is already "
                    + branch.status() + " and cannot be marked " + targetStatus + ".");
        }
        if (targetStatus == TccBranchStatus.CONFIRMED) {
            confirmTccRecovery(branchId);
            return;
        }
        if (targetStatus == TccBranchStatus.CANCELLED) {
            cancelTccRecovery(branchId, "physical coordinator cancel completed");
            return;
        }
        throw new IllegalArgumentException("Unsupported external TCC phase-two status " + targetStatus + ".");
    }

    private List<Service> rememberGeneratedServices(List<Service> services) {
        for (Service service : services) {
            rememberGeneratedServiceWithoutRefresh(service);
        }
        refreshFrameworkIdempotencyBypassServices();
        return services;
    }

    private Service rememberGeneratedService(Service service) {
        rememberGeneratedServiceWithoutRefresh(service);
        refreshFrameworkIdempotencyBypassServices();
        return service;
    }

    private void rememberGeneratedServiceWithoutRefresh(Service service) {
        registeredGeneratedServices.removeIf(item -> item.getName().equals(service.getName()));
        registeredGeneratedServices.add(service);
    }

    public GeneratedServiceMetadata describeGeneratedService(Service service) {
        install();
        return describeGeneratedServiceInstalled(service);
    }

    private GeneratedServiceMetadata describeGeneratedServiceInstalled(Service service) {
        Service original = originalService(service);
        TransactionalService transactional = service instanceof TransactionalService value ? value : null;
        CompensationRuleProvider compensationRuleProvider =
                service instanceof CompensationRuleProvider value ? value : null;
        RemoteCompensationRuleProvider remoteCompensationRuleProvider =
                original instanceof RemoteCompensationRuleProvider value ? value : null;
        TccLifecycleRuleProvider tccLifecycleRuleProvider =
                original instanceof TccLifecycleRuleProvider value ? value : null;
        TccReservationRuleProvider tccReservationRuleProvider =
                original instanceof TccReservationRuleProvider value ? value : null;
        ObjectSnapshotRuleProvider objectSnapshotRuleProvider =
                service instanceof ObjectSnapshotRuleProvider value ? value : null;
        RepositoryHydrationRuleProvider repositoryHydrationRuleProvider =
                service instanceof RepositoryHydrationRuleProvider value ? value : null;
        ScopeMetadataProvider scopeMetadataProvider =
                original instanceof ScopeMetadataProvider value ? value : null;
        GeneratedServiceKindProvider generatedServiceKindProvider =
                original instanceof GeneratedServiceKindProvider value ? value : null;
        CalculationMetadataProvider calculationMetadataProvider =
                original instanceof CalculationMetadataProvider value ? value : null;
        QuantumServiceMetadataProvider quantumServiceMetadataProvider =
                original instanceof QuantumServiceMetadataProvider value ? value : null;
        SagaTransactionCallProvider sagaTransactionCallProvider =
                original instanceof SagaTransactionCallProvider value ? value : null;
        boolean remote = original instanceof RemoteGeneratedService;
        return new GeneratedServiceMetadata(
                service.getName(),
                original.getClass().getName(),
                generatedServiceKindProvider == null
                        ? GeneratedServiceKind.UNKNOWN
                        : generatedServiceKindProvider.getGeneratedServiceKind(),
                transactional == null ? null : transactional.getTransactionMode(),
                transactional == null ? null : transactional.getTransactionResourceId(),
                tccLifecycleRuleProvider == null ? null : tccLifecycleRuleProvider.getTccConfirmServiceName(),
                tccLifecycleRuleProvider == null ? null : tccLifecycleRuleProvider.getTccCancelServiceName(),
                tccReservationRuleProvider == null
                        ? List.of()
                        : List.copyOf(tccReservationRuleProvider.getTccReservationRules()),
                compensationRuleProvider == null
                        ? List.of()
                        : List.copyOf(compensationRuleProvider.getCompensationServiceNames()),
                remoteCompensationRuleProvider == null
                        ? List.of()
                        : List.copyOf(remoteCompensationRuleProvider.getRemoteCompensationServiceNames()),
                quantumServiceMetadataProvider == null
                        ? List.of()
                        : List.copyOf(quantumServiceMetadataProvider.getQuantumAttributeIds()),
                sagaTransactionCallProvider == null
                        ? List.of()
                        : List.copyOf(sagaTransactionCallProvider.getSagaTransactionCallServiceNames()),
                serviceParameterTypes(original),
                scopeMetadataProvider == null
                        ? List.of()
                        : List.copyOf(scopeMetadataProvider.getServiceParameterNames()),
                scopeMetadataProvider == null
                        ? List.of()
                        : List.copyOf(scopeMetadataProvider.getServiceContextParameterNames()),
                objectSnapshotRuleProvider == null
                        ? List.of()
                        : List.copyOf(objectSnapshotRuleProvider.getObjectSnapshotRules()),
                repositoryHydrationRuleProvider == null
                        ? List.of()
                        : List.copyOf(repositoryHydrationRuleProvider.getRepositoryHydrationRules()),
                scopeMetadataProvider == null || scopeMetadataProvider.isLocalScope(),
                scopeMetadataProvider != null && scopeMetadataProvider.isAsyncScope(),
                scopeMetadataProvider == null ? null : scopeMetadataProvider.getInputHeaderName(),
                scopeMetadataProvider == null ? null : scopeMetadataProvider.getOutputHeaderName(),
                scopeMetadataProvider != null && scopeMetadataProvider.requiresIdempotencyKey(),
                scopeMetadataProvider == null ? null : scopeMetadataProvider.getIdempotencyKeyFieldName(),
                scopeMetadataProvider == null ? "" : idempotencyKeyPath(scopeMetadataProvider),
                scopeMetadataProvider != null && scopeMetadataProvider.hasIdempotencyKeyField(),
                scopeMetadataProvider == null || scopeMetadataProvider.requiresPhysicalBackendBinding(),
                remote,
                calculationMetadataProvider == null
                        ? List.of()
                        : List.copyOf(calculationMetadataProvider.getCalculationAssignments()));
    }

    private void refreshFrameworkIdempotencyBypassServices() {
        if (registeredGeneratedServices.isEmpty()) {
            BusinessIdempotencyManager.clearFrameworkBypassServices();
            return;
        }
        List<GeneratedServiceMetadata> metadata = registeredGeneratedServices.stream()
                .map(this::describeGeneratedServiceInstalled)
                .toList();
        List<PhysicalBackendAssignment> physicalAssignments = physicalBackendRegistry.resolve(metadata);
        List<PhysicalQuantumPlan> quantumPlans = physicalQuantumPlans();
        List<String> bypassServices = idempotencyPlans(metadata, physicalAssignments, quantumPlans).stream()
                .filter(plan -> "SERVICE_IDEMPOTENCY".equals(plan.idempotencyMode()))
                .map(IdempotencyPlan::serviceName)
                .toList();
        BusinessIdempotencyManager.setFrameworkBypassServices(bypassServices);
    }

    private String idempotencyKeyPath(ScopeMetadataProvider scopeMetadataProvider) {
        String fieldName = scopeMetadataProvider.getIdempotencyKeyFieldName();
        if (fieldName == null || fieldName.isBlank()) {
            return "";
        }
        return "appHeader." + fieldName;
    }

    private List<String> serviceParameterTypes(Service service) {
        List<List<String>> declaredCandidates = serviceParameterTypes(service, service.getClass().getDeclaredMethods());
        if (declaredCandidates.size() == 1) {
            return declaredCandidates.get(0);
        }
        List<List<String>> candidates = serviceParameterTypes(service, service.getClass().getMethods());
        if (candidates.size() == 1) {
            return candidates.get(0);
        }
        return List.of();
    }

    private List<List<String>> serviceParameterTypes(Service service, Method[] methods) {
        List<List<String>> candidates = new ArrayList<>();
        for (Method method : methods) {
            if (method.isSynthetic() || !method.getName().equals(service.getName())) {
                continue;
            }
            List<String> parameterTypes = new ArrayList<>();
            for (Class<?> parameterType : method.getParameterTypes()) {
                parameterTypes.add(parameterType.getName());
            }
            candidates.add(List.copyOf(parameterTypes));
        }
        return candidates;
    }

    private String nullToBlank(String value) {
        return value == null ? "" : value;
    }

    private Service originalService(Service service) {
        Service current = service;
        while (current instanceof DelegatingService delegatingService) {
            Service delegate = delegatingService.getDelegateService();
            if (delegate == null || delegate == current) {
                return current;
            }
            current = delegate;
        }
        return current;
    }

    public Object executeGeneratedService(String serviceName, Object request) {
        return executeGeneratedService(DefaultServiceContainer.getInstance(), serviceName, request);
    }

    public Object executeGeneratedService(DefaultServiceContainer services, String serviceName, Object request) {
        install();
        GeneratedRoleIdentityContextBinder.attach(request);
        Service service = services.getService(serviceName);
        if (service == null) {
            throw new IllegalStateException("Generated S++ service is not registered: " + serviceName);
        }
        if (originalService(service) instanceof RemoteGeneratedService) {
            RemoteServiceAdapter adapter = remoteServiceAdapterFor(serviceName)
                    .orElseThrow(() -> new IllegalStateException("Remote service " + serviceName
                            + " has no registered adapter."));
            return CurrentObjectContext.withObjects(new Object[] { request }, () -> adapter.execute(serviceName, request));
        }
        return CurrentObjectContext.withObjects(new Object[] { request }, () -> service.execute(request));
    }

