    public List<RemoteCompensationRecoveryCandidate> findRemoteCompensationRecoveryCandidates() {
        install();
        List<SagaLogEntry> entries = getSagaLogStore().findAll();
        Set<String> recoveredKeys = entries.stream()
                .filter(entry -> "REMOTE_COMPENSATION_RECOVERED".equals(entry.status()))
                .map(entry -> remoteCompensationRecoveryKey(entry.globalSerialNumber(), entry.serviceName()))
                .collect(Collectors.toCollection(LinkedHashSet::new));
        List<RemoteCompensationRecoveryCandidate> candidates = new ArrayList<>();
        for (SagaLogEntry entry : entries) {
            if ("REMOTE_COMPENSATION_FAILED".equals(entry.status())
                    || "REMOTE_COMPENSATION_MANUAL_REQUIRED".equals(entry.status())) {
                if (recoveredKeys.contains(remoteCompensationRecoveryKey(entry.globalSerialNumber(),
                        entry.serviceName()))) {
                    continue;
                }
                candidates.add(RemoteCompensationRecoveryCandidate.from(entry));
            }
        }
        return List.copyOf(candidates);
    }

    private String remoteCompensationRecoveryKey(String globalSerialNumber, String serviceName) {
        return String.valueOf(globalSerialNumber) + "\u0000" + String.valueOf(serviceName);
    }

    public SagaLogEntry retryRemoteCompensationRecovery(String sagaId) {
        install();
        SagaLogEntry failedEntry = getSagaLogStore().findAll().stream()
                .filter(entry -> entry.sagaId().equals(sagaId))
                .filter(entry -> "REMOTE_COMPENSATION_FAILED".equals(entry.status())
                        || "REMOTE_COMPENSATION_MANUAL_REQUIRED".equals(entry.status()))
                .findFirst()
                .orElseThrow(() -> new IllegalStateException("Remote compensation saga " + sagaId
                        + " is not a recovery candidate."));
        if (failedEntry.recoveryPayload() == null || failedEntry.recoveryPayload().isBlank()) {
            throw new IllegalStateException("Remote compensation saga " + sagaId
                    + " does not have recovery payload.");
        }
        Service compensationService = DefaultServiceContainer.getInstance().getService(failedEntry.serviceName());
        if (compensationService == null) {
            throw new IllegalStateException("Remote compensation service not found: " + failedEntry.serviceName());
        }
        Object[] arguments = TccRecoveryPayloadCodec.decode(failedEntry.recoveryPayload());
        compensationService.execute(arguments);
        return new SagaLogRecorder(getSagaLogStore()).append(failedEntry.globalSerialNumber(), failedEntry.serviceName(),
                "REMOTE_COMPENSATION_RECOVERED",
                "remote compensation recovered for " + failedEntry.serviceName(),
                failedEntry.recoveryPayload());
    }

    public List<RemoteCompensationRecoveryScanResult> recoverRemoteCompensationCandidates(
            Function<RemoteCompensationRecoveryCandidate, RemoteCompensationRecoveryDecision> resolver) {
        Objects.requireNonNull(resolver, "resolver");
        List<RemoteCompensationRecoveryScanResult> results = new ArrayList<>();
        for (RemoteCompensationRecoveryCandidate candidate : findRemoteCompensationRecoveryCandidates()) {
            RemoteCompensationRecoveryDecision decision;
            try {
                decision = Optional.ofNullable(resolver.apply(candidate))
                        .orElse(RemoteCompensationRecoveryDecision.SKIP);
            } catch (RuntimeException error) {
                results.add(new RemoteCompensationRecoveryScanResult(candidate,
                        RemoteCompensationRecoveryDecision.SKIP, null, error.getMessage()));
                continue;
            }
            if (decision == RemoteCompensationRecoveryDecision.SKIP) {
                results.add(new RemoteCompensationRecoveryScanResult(candidate, decision, null, null));
                continue;
            }
            try {
                SagaLogEntry recovered = retryRemoteCompensationRecovery(candidate.sagaId());
                results.add(new RemoteCompensationRecoveryScanResult(candidate, decision, recovered, null));
            } catch (RuntimeException error) {
                results.add(new RemoteCompensationRecoveryScanResult(candidate, decision, null, error.getMessage()));
            }
        }
        return List.copyOf(results);
    }

