    public List<RecoveryWorkItem> findRecoveryWorkItems(Instant reservationExpiryCutoff) {
        List<RecoveryWorkItem> items = new ArrayList<>();
        nativeSagaBackend().ifPresent(backend -> items.add(RecoveryWorkItem.nativeSaga(
                backend.name(), nativeSagaServiceNames())));
        for (TccRecoveryCandidate candidate : findTccRecoveryCandidates(reservationExpiryCutoff)) {
            items.add(RecoveryWorkItem.tcc(candidate));
        }
        for (RemoteCompensationRecoveryCandidate candidate : findRemoteCompensationRecoveryCandidates()) {
            items.add(RecoveryWorkItem.remoteCompensation(candidate));
        }
        return List.copyOf(items);
    }

    public List<RecoveryWorkItemScanResult> recoverRecoveryWorkItems(
            Function<RecoveryWorkItem, RecoveryWorkItemDecision> resolver) {
        return recoverRecoveryWorkItems(resolver, nativeSagaRecoveryBatchSize());
    }

    public List<RecoveryWorkItemScanResult> recoverRecoveryWorkItems(
            Function<RecoveryWorkItem, RecoveryWorkItemDecision> resolver,
            int nativeSagaBatchSize) {
        Objects.requireNonNull(resolver, "resolver");
        if (nativeSagaBatchSize <= 0) {
            throw new IllegalArgumentException(
                    "Native Saga recovery batch size must be positive");
        }
        List<RecoveryWorkItemScanResult> results = new ArrayList<>();
        for (RecoveryWorkItem workItem : findRecoveryWorkItems()) {
            RecoveryWorkItemDecision decision;
            try {
                decision = Optional.ofNullable(resolver.apply(workItem))
                        .orElse(RecoveryWorkItemDecision.SKIP);
            } catch (RuntimeException error) {
                results.add(new RecoveryWorkItemScanResult(workItem,
                        RecoveryWorkItemDecision.SKIP, null, null, null, error.getMessage()));
                continue;
            }
            if (decision == RecoveryWorkItemDecision.SKIP) {
                results.add(new RecoveryWorkItemScanResult(
                        workItem, decision, null, null, null, null));
                continue;
            }
            try {
                results.add(recoverRecoveryWorkItem(
                        workItem, decision, nativeSagaBatchSize));
            } catch (RuntimeException error) {
                results.add(new RecoveryWorkItemScanResult(
                        workItem, decision, null, null, null, error.getMessage()));
            }
        }
        return List.copyOf(results);
    }

    private RecoveryWorkItemScanResult recoverRecoveryWorkItem(RecoveryWorkItem workItem,
                                                               RecoveryWorkItemDecision decision,
                                                               int nativeSagaBatchSize) {
        if ("TCC".equals(workItem.kind())) {
            if (decision == RecoveryWorkItemDecision.CONFIRM) {
                TccBranchRecord recovered = confirmTccRecovery(workItem.workId());
                return new RecoveryWorkItemScanResult(
                        workItem, decision, recovered, null, null, null);
            }
            if (decision == RecoveryWorkItemDecision.CANCEL) {
                TccBranchRecord recovered = cancelTccRecovery(workItem.workId(), "cancel recovery completed");
                return new RecoveryWorkItemScanResult(
                        workItem, decision, recovered, null, null, null);
            }
            throw new IllegalStateException("Recovery work item " + workItem.workId()
                    + " of kind TCC does not support decision " + decision + ".");
        }
        if ("REMOTE_COMPENSATION".equals(workItem.kind())) {
            if (decision == RecoveryWorkItemDecision.RETRY) {
                SagaLogEntry recovered = retryRemoteCompensationRecovery(workItem.workId());
                return new RecoveryWorkItemScanResult(
                        workItem, decision, null, recovered, null, null);
            }
            throw new IllegalStateException("Recovery work item " + workItem.workId()
                    + " of kind REMOTE_COMPENSATION does not support decision " + decision + ".");
        }
        if ("NATIVE_SAGA".equals(workItem.kind())) {
            if (decision == RecoveryWorkItemDecision.SCAN) {
                return new RecoveryWorkItemScanResult(
                        workItem,
                        decision,
                        null,
                        null,
                        SagaTransactionGroupManager.recoverPending(nativeSagaBatchSize),
                        null);
            }
            throw new IllegalStateException("Recovery work item " + workItem.workId()
                    + " of kind NATIVE_SAGA does not support decision " + decision + ".");
        }
        throw new IllegalStateException("Unsupported recovery work item kind " + workItem.kind()
                + " for work item " + workItem.workId() + ".");
    }

    private Optional<PhysicalRuntimeCatalog.PhysicalBackend> nativeSagaBackend() {
        return physicalRuntimeCatalog.backends().stream()
                .filter(backend -> "SEATA_SAGA".equalsIgnoreCase(
                        backend.configuration().getOrDefault("sagaImplementation", "")))
                .findFirst();
    }

    private List<String> nativeSagaServiceNames() {
        return describeGeneratedServices().stream()
                .filter(service -> service.transactionMode() == TransactionMode.SAGA)
                .map(GeneratedServiceMetadata::serviceName)
                .distinct()
                .toList();
    }

    private int nativeSagaRecoveryBatchSize() {
        String configured = nativeSagaBackend()
                .map(backend -> backend.configuration().get("sagaRecoveryBatchSize"))
                .orElse(null);
        if (configured == null || configured.isBlank()) {
            return 100;
        }
        try {
            return Math.max(1, Integer.parseInt(configured.trim()));
        } catch (NumberFormatException error) {
            throw new IllegalStateException(
                    "Native Saga recovery batch size must be a positive integer", error);
        }
    }

    public List<TccRecoveryCandidate> findTccRecoveryCandidates(Instant reservationExpiryCutoff) {
        Map<String, GeneratedServiceMetadata> servicesByName = new LinkedHashMap<>();
        for (GeneratedServiceMetadata service : describeGeneratedServices()) {
            servicesByName.put(service.serviceName(), service);
        }
        Instant effectiveCutoff = reservationExpiryCutoff == null ? Instant.now() : reservationExpiryCutoff;
        Map<String, List<TccReservationRecord>> reservationsByBranch = tccReservationsByBranch();
        List<TccRecoveryCandidate> candidates = new ArrayList<>();
        for (TccBranchRecord branch : findTryingTccBranches()) {
            GeneratedServiceMetadata service = servicesByName.get(branch.actionName());
            List<TccReservationRecord> reservations = reservationsByBranch.getOrDefault(branch.branchId(), List.of());
            boolean expiredReservationAvailable = reservations.stream()
                    .anyMatch(record -> isExpiredTryingReservation(record, effectiveCutoff));
            boolean lifecycleAvailable = service != null
                    && service.transactionMode() == TransactionMode.TCC
                    && branch.resourceId().equals(service.transactionResourceId())
                    && service.tccConfirmServiceName() != null
                    && service.tccCancelServiceName() != null
                    && !service.objectSnapshotRules().isEmpty();
            List<ObjectSnapshotRule> snapshotRules = service == null ? List.of() : service.objectSnapshotRules();
            candidates.add(new TccRecoveryCandidate(branch, branch.actionName(),
                    service == null ? null : service.tccConfirmServiceName(),
                    service == null ? null : service.tccCancelServiceName(),
                    snapshotRules,
                    lifecycleAvailable,
                    branch.recoveryPayload() != null && !branch.recoveryPayload().isBlank(),
                    reservations,
                    expiredReservationAvailable));
        }
        return List.copyOf(candidates);
    }

    private Map<String, List<TccReservationRecord>> tccReservationsByBranch() {
        Map<String, List<TccReservationRecord>> result = new LinkedHashMap<>();
        for (TccReservationRecord reservation : findTccReservations()) {
            if (reservation.branchId() == null || reservation.branchId().isBlank()) {
                continue;
            }
            result.computeIfAbsent(reservation.branchId(), ignored -> new ArrayList<>()).add(reservation);
        }
        return result;
    }

    private boolean isExpiredTryingReservation(TccReservationRecord record, Instant cutoff) {
        if (record.status() != TccReservationStatus.TRYING
                || record.expiresAt() == null
                || record.expiresAt().isBlank()) {
            return false;
        }
        try {
            return !Instant.parse(record.expiresAt()).isAfter(cutoff);
        } catch (RuntimeException ignored) {
            return false;
        }
    }

    public TccBranchRecord confirmTccRecovery(String branchId) {
        return executeTccRecovery(branchId, true, "confirm recovery completed");
    }

    public TccBranchRecord cancelTccRecovery(String branchId, String message) {
        return executeTccRecovery(branchId, false,
                message == null || message.isBlank() ? "cancel recovery completed" : message);
    }

    public List<TccRecoveryScanResult> recoverTccCandidates(
            Function<TccRecoveryCandidate, TccRecoveryDecision> resolver) {
        Objects.requireNonNull(resolver, "resolver");
        List<TccRecoveryScanResult> results = new ArrayList<>();
        for (TccRecoveryCandidate candidate : findTccRecoveryCandidates()) {
            TccRecoveryDecision decision;
            try {
                decision = Optional.ofNullable(resolver.apply(candidate))
                        .orElse(TccRecoveryDecision.SKIP);
            } catch (RuntimeException error) {
                results.add(new TccRecoveryScanResult(candidate, TccRecoveryDecision.SKIP, null,
                        error.getMessage()));
                continue;
            }
            if (decision == TccRecoveryDecision.SKIP) {
                results.add(new TccRecoveryScanResult(candidate, decision, null, null));
                continue;
            }
            try {
                TccBranchRecord recovered = decision == TccRecoveryDecision.CONFIRM
                        ? confirmTccRecovery(candidate.branch().branchId())
                        : cancelTccRecovery(candidate.branch().branchId(), "cancel recovery completed");
                results.add(new TccRecoveryScanResult(candidate, decision, recovered, null));
            } catch (RuntimeException error) {
                results.add(new TccRecoveryScanResult(candidate, decision, null, error.getMessage()));
            }
        }
        return List.copyOf(results);
    }

    private TccBranchRecord executeTccRecovery(String branchId, boolean confirm, String message) {
        install();
        TccRecoveryCandidate candidate = findTccRecoveryCandidates().stream()
                .filter(item -> item.branch().branchId().equals(branchId))
                .findFirst()
                .orElseThrow(() -> new IllegalStateException("TCC branch " + branchId
                        + " is not a TRYING recovery candidate."));
        if (!candidate.lifecycleAvailable()) {
            throw new IllegalStateException("TCC branch " + branchId
                    + " does not have complete lifecycle metadata for recovery.");
        }
        if (!candidate.recoveryPayloadAvailable()) {
            throw new IllegalStateException("TCC branch " + branchId
                    + " does not have recovery payload.");
        }
        validateTccReservationRecovery(candidate);
        Object[] arguments = TccRecoveryPayloadCodec.decode(candidate.branch().recoveryPayload());
        String serviceName = confirm ? candidate.confirmServiceName() : candidate.cancelServiceName();
        TccLifecycleServiceInvoker.invoke(serviceName, arguments);
        recoverTccObjectSnapshots(candidate, arguments);
        TccBranchStatus status = confirm ? TccBranchStatus.CONFIRMED : TccBranchStatus.CANCELLED;
        recoverTccReservations(candidate, confirm);
        TccBranchRecord current = candidate.branch();
        TccBranchRecord recovered = new TccBranchRecord(current.branchId(), current.globalSerialNumber(),
                current.resourceId(), current.actionName(), status, message, Instant.now().toString(),
                current.recoveryPayload());
        getTccBranchStore().save(recovered);
        return recovered;
    }

    private void recoverTccObjectSnapshots(TccRecoveryCandidate candidate, Object[] arguments) {
        if (candidate.objectSnapshotRules().isEmpty()) {
            return;
        }
        TccBranchRecord branch = candidate.branch();
        BusinessTraceContext.execute(branch.globalSerialNumber(), () -> {
            TransactionContext recoveryContext = new TransactionContext(
                    Map.of(branch.resourceId(), TransactionMode.TCC));
            ObjectSnapshotParticipant snapshots =
                    new ObjectSnapshotParticipant(branch.resourceId(), this::getRepository)
                            .resolveRoleIdentities(this::resolveRepositoryRoleIdentity)
                            .rules(candidate.objectSnapshotRules(), ignored -> null);
            snapshots.setArguments(arguments);
            snapshots.afterExecute(recoveryContext);
            snapshots.commit(recoveryContext);
            return null;
        });
    }

    private void validateTccReservationRecovery(TccRecoveryCandidate candidate) {
        List<TccReservationRecord> tryingReservations = candidate.reservations().stream()
                .filter(record -> record.status() == TccReservationStatus.TRYING)
                .toList();
        if (tryingReservations.isEmpty()) {
            return;
        }
        if (!(getRepository() instanceof JdbcObjectRepository)) {
            throw new IllegalStateException("TCC branch " + candidate.branch().branchId()
                    + " reservation recovery requires a JDBC object repository.");
        }
        for (TccReservationRecord reservation : tryingReservations) {
            if (reservation.objectId() == null || reservation.objectId().isBlank()) {
                throw new IllegalStateException("TCC reservation " + reservation.reservationId()
                        + " cannot be recovered because its object identity was not persisted.");
            }
        }
    }

    private void recoverTccReservations(TccRecoveryCandidate candidate, boolean confirm) {
        if (!(getRepository() instanceof JdbcObjectRepository repository)) {
            return;
        }
        TccReservationStatus status = confirm
                ? TccReservationStatus.CONFIRMED
                : TccReservationStatus.CANCELLED;
        String message = confirm ? "confirm recovery completed" : "cancel recovery completed";
        for (TccReservationRecord reservation : candidate.reservations()) {
            if (reservation.status() != TccReservationStatus.TRYING) {
                continue;
            }
            repository.adjustAppDdlPlatformColumn(
                    objectType(reservation.reservationAttributeId()),
                    reservation.objectId(),
                    null,
                    objectPath(reservation.reservationAttributeId()),
                    reservation.quantity().negate());
            getTccReservationStore().save(new TccReservationRecord(
                    reservation.reservationId(),
                    reservation.branchId(),
                    reservation.globalSerialNumber(),
                    reservation.transactionId(),
                    reservation.resourceId(),
                    reservation.actionName(),
                    reservation.sourceAttributeId(),
                    reservation.reservationAttributeId(),
                    reservation.quantity(),
                    status,
                    message,
                    JdbcTccReservationStore.updatedNow(),
                    reservation.expiresAt(),
                    reservation.objectId()));
        }
    }

