    private static String stripLeadingSlash(String resourceName) {
        return resourceName != null && resourceName.startsWith("/")
                ? resourceName.substring(1)
                : resourceName;
    }

    private static String addLeadingSlash(String resourceName) {
        return resourceName != null && !resourceName.startsWith("/")
                ? "/" + resourceName
                : resourceName;
    }
